local config = {
  ui_story_5088_50880100_1_dialog_content = "<color=#e8d9bb>Tolong ingat kembali cerita yang lama dilupakan itu.</color>",
  ui_story_5088_50880100_2_dialog_content = "<color=#e8d9bb>Cerita tentang kerajaan kuno yang berada di ambang bencana, dan kedatangan sekelompok pahlawan—</color>",
  ui_story_5088_50880100_3_dialog_content = "<color=#e8d9bb>Untuk menyelamatkan kerajaan mereka dari kehadiran yang jahat, mereka dengan sukarela menjalani peningkatan yang berbahaya.</color>",
  ui_story_5088_50880100_4_dialog_content = "<color=#e8d9bb>Tapi ketika kedamaian kembali dipulihkan, para pahlawan dikutuk dan dihina sebagai monster, baik dalam tubuh maupun pikiran.</color>",
  ui_story_5088_50880100_5_dialog_content = "<color=#e8d9bb>Difitnah oleh para pendeta, ditinggalkan oleh raja, dan ditakuti oleh massa yang bodoh yang mereka janjikan untuk melindungi.</color>",
  ui_story_5088_50880100_6_dialog_content = "<color=#e8d9bb>Dalam keputusasaan mereka yang tak terduga, para pahlawan saling mencari kehangatan dan penghiburan, namun mereka tak bisa melawan korupsi dari kutukan mereka.</color>",
  ui_story_5088_50880100_7_dialog_content = "<color=#e8d9bb>Untuk memberi mereka satu kesempatan terakhir untuk bahagia, pemimpin mereka dan seorang teman yang terkasih mengorbankan diri mereka.</color>",
  ui_story_5088_50880100_8_dialog_content = "<color=#e8d9bb>Tersegel di luar aliran waktu, mereka menunggu dalam diam—</color>",
  ui_story_5088_50880100_9_dialog_content = "Heh, heh...",
  ui_story_5088_50880100_10_dialog_content = "Graaaaah!",
  ui_story_5088_50880100_11_dialog_content = "<color=#e8d9bb>Hari Pertama: Bencana Besar Turun.</color>",
  ui_story_5088_50880100_12_dialog_content = "Ini buruk! Mereka mengejar—",
  ui_story_5088_50880100_13_dialog_content = "Tidak di jam tangan saya!",
  ui_story_5088_50880100_14_dialog_content = "Itu kamu... Orang itu dari perayaan ibu kota kerajaan...",
  ui_story_5088_50880100_15_dialog_content = "Bisakah kamu berjalan? Sini, pegang tanganku.",
  ui_story_5088_50880100_16_dialog_content = "... Itu pahlawan.",
  ui_story_5088_50880100_17_dialog_content = "Aku bukan pahlawan, kamu bisa memanggilku Adras.",
  ui_story_5088_50880100_18_dialog_content = "<color=#e8d9bb>Hari Kedua: Pahlawan-pahlawan Takdir.</color>",
  ui_story_5088_50880100_19_dialog_content = "Apa yang terjadi?",
  ui_story_5088_50880100_20_dialog_content = "Tidak ada apa-apa, saya hanya membantu pengembara ini.",
  ui_story_5088_50880100_21_dialog_content = "Kau baik-baik saja?",
  ui_story_5088_50880100_22_dialog_content = "Kota itu aman, dan tidak ada laporan korban. Kita bisa beristirahat di sana untuk sementara ini.",
  ui_story_5088_50880100_23_dialog_content = "<color=#e8d9bb>Hari Ketiga: Memuji Bintang-Bintang</color>",
  ui_story_5088_50880100_24_dialog_content = "Maafkan aku, tapi...",
  ui_story_5088_50880100_25_dialog_content = "Oh! Aku belum memperkenalkan diri.",
  ui_story_5088_50880100_26_dialog_content = "Nama saya adalah—",
  ui_story_5088_50880100_27_dialog_content = "<color=#e8d9bb>Hari Keempat: Perdamaian, Perubahan, dan Ketegangan.</color>",
  ui_story_5088_50880100_28_dialog_content = "Achilles... Kepalaku terasa berputar...",
  ui_story_5088_50880100_29_dialog_content = "Saya sangat minta maaf, temanku... Tapi saya harus menahanmu di sini...",
  ui_story_5088_50880100_30_dialog_content = "Simpan tenagamu. Aku akan membawamu ke medik segera.",
  ui_story_5088_50880100_31_dialog_content = "T-Tidak, itu tidak perlu. Aku sangat lelah... Dan aku sangat merindukan rumahku...",
  ui_story_5088_50880100_32_dialog_content = "Maka izinkan aku mengantarmu pulang.",
  ui_story_5088_50880100_33_dialog_content = "Jangan melangkah lagi, Claymore! Apakah membunuh Lord Lucius dan memberontak terhadap Dewan Tetua tidak cukup untukmu?! Menyerahlah, monster!",
  ui_story_5088_50880100_34_dialog_content = "... Minggir. Aku tidak akan mengangkat pedangku terhadap orang yang tidak bersalah.",
  ui_story_5088_50880100_35_dialog_content = "Kalau begitu, kau harus membayar dengan darah yang kau hutang kepada Imam Besar!",
  ui_story_5088_50880100_36_dialog_content = "<size=45>Saya bilang minggir!</size>",
  ui_story_5088_50880100_37_dialog_content = "Argh... A-Aku tidak bisa menggerakkan kakiku... Apa ini...?!",
  ui_story_5088_50880100_38_dialog_content = "Apa yang terjadi, Achilles...? Aku tidak bisa melihat warna cahaya mu lagi...",
  ui_story_5088_50880100_39_dialog_content = "Ini bukan apa-apa, Ludweiss. Sini, ulurkan tanganmu. Sudah waktunya kita kembali.",
  ui_story_5088_50880100_40_dialog_content = "Tidak, tunggu, aku ingat sekarang... Teman-teman kita jauh lebih penting. Mereka masih terkurung, jadi tolong bawa mereka dan pergi...",
  ui_story_5088_50880100_41_dialog_content = "Kami di sini, Tuhan Achilles!",
  ui_story_5088_50880100_42_dialog_content = "Apa... Apa yang sebenarnya terjadi di sini...?",
  ui_story_5088_50880100_43_dialog_content = "Anthony... Mengapa kamu terus menerus mencampuri monster seperti kami?",
  ui_story_5088_50880100_44_dialog_content = "Saya tidak tahu apa yang Anda bicarakan, Lord Achilles. Yang saya tahu adalah Anda membutuhkan bantuan saya.",
  ui_story_5088_50880100_45_dialog_content = "... Jaga baik-baik Adras dan yang lainnya.",
  ui_story_5088_50880100_46_dialog_content = "Aku akan membuat celah untuk kabur.",
  ui_story_5088_50880100_47_dialog_content = "Ayo, Ludweiss.",
  ui_story_5088_50880100_48_dialog_content = "Apakah sudah berakhir? Apakah Dewan Tetua telah mengakhiri pemberontakan mereka? Saya bertanya-tanya... Akankah anak-anak menderita karena ini...?",
  ui_story_5088_50880100_49_dialog_content = "Semuanya akan segera berakhir, Ludweiss. Teruslah berbicara denganku.",
  ui_story_5088_50880100_50_dialog_content = "Ceritakan lebih banyak tentang rumahmu. Aku ingat kamu pernah menggambarkannya sebagai semacam surga.",
  ui_story_5088_50880100_51_dialog_content = "Tidak, kaumku tidak pernah menginjakkan kaki di tempat itu... Kami semua hanya pengasing yang tersesat... Berusaha keras untuk kembali ke surga nenek moyang kami...",
  ui_story_5088_50880100_52_dialog_content = "Di masa lalu, saya hanya bisa mengingat keindahan Eraveil melalui kenangan leluhur saya... Tapi sekarang... Akhirnya saya menemukannya...",
  ui_story_5088_50880100_53_dialog_content = "Suara dalam mimpiku... Itu milik seorang anak laki-laki dari Eraveil.",
  ui_story_5088_50880100_54_dialog_content = "Betapa saya ingin melihat tempat itu sendiri.",
  ui_story_5088_50880100_55_dialog_content = "Lalu kita akan pergi ke Eraveil bersama. Kamu, saya, dan kita semua.",
  ui_story_5088_50880100_56_dialog_content = "Aku sangat menyesal... Aku juga ingin menyelamatkanmu, tapi sekarang sudah terlambat...",
  ui_story_5088_50880100_57_dialog_content = "Cahayamu telah ditelan. Kamu tidak bisa terus seperti ini...",
  ui_story_5088_50880100_58_dialog_content = "Jangan khawatirkan dirimu demi saya.",
  ui_story_5088_50880100_59_dialog_content = "Saya bersumpah akan memenuhi ramalanmu, dan membawamu untuk melihat keindahan rumahmu secara langsung.",
  ui_story_5088_50880100_60_dialog_content = "Jika itu yang kamu rasakan... Maka aku menaruh semua kepercayaanku padamu.",
  ui_story_5088_50880100_61_dialog_content = "Dengan hanya kekuatan Bintang Jatuh yang tersisa, kini giliranmu untuk mewujudkan keajaiban itu.",
  ui_story_5088_50880100_62_dialog_content = "Jangan pernah kehilangan keyakinanmu pada harapan, karena itu akan membimbingmu keluar dari kegelapan ini suatu hari nanti.",
  ui_story_5088_50880100_63_dialog_content = "Semuanya terserah padamu sekarang... Achilles...",
  ui_story_5088_50880100_64_dialog_content = "...",
  ui_story_5088_50880100_65_dialog_content = "...",
  ui_story_5088_50880100_66_dialog_content = "<color=#e8d9bb>Dan ini adalah akhir dari cerita tragis dan terkutuk ini. Sendirian di dunia, sang pahlawan memulai perjalanannya yang tak berujung...</color>",
  ui_story_5088_50880100_67_dialog_content = "Tidak, bukan yang ini... Bukan yang ini juga...",
  ui_story_5088_50880100_68_dialog_content = "Aku tahu kamu sedang terburu-buru, sayang, tapi tolong sedikit lebih hati-hati saat menangani barang dagangan. Mereka adalah barang antik, setelah semua.",
  ui_story_5088_50880100_69_dialog_content = "Benarkah? Karena aku ingat kamu menggunakan jurnal itu untuk melapisi peti harta karun sebelum kamu menjualnya padaku.",
  ui_story_5088_50880100_70_dialog_content = "Itu hanya karena item tersebut sudah cacat sejak awal. Tulisan di atasnya pada dasarnya tidak dapat dimengerti.",
  ui_story_5088_50880100_71_dialog_content = "Dan masih tetap memiliki nilai untukmu, bukan?",
  ui_story_5088_50880100_72_dialog_content = "Kiriman lainnya untukmu, bos.",
  ui_story_5088_50880100_73_dialog_content = "Pekerjaan yang luar biasa, Casta. Di mana saja tidak masalah, terima kasih.",
  ui_story_5088_50880100_74_dialog_content = "...",
  ui_story_5088_50880100_75_dialog_content = "PlayerName? Kamu mencari sesuatu?",
  ui_story_5088_50880100_76_dialog_content = "Ini cerita panjang... Kamu tahu, aku membiarkan Sheol membujukku untuk mengais barang antik karena dia bilang aku bisa menjadi kaya jika beruntung.",
  ui_story_5088_50880100_77_dialog_content = "Tapi ketika saya mulai merasakan beberapa dari mereka, saya menemukan sebuah buku catatan kuno yang ditinggalkan oleh salah satu orang saya.",
  ui_story_5088_50880100_78_dialog_content = "Aku benar-benar tertarik untuk belajar lebih banyak tentang ini... Dan meskipun hampir tidak bisa dibaca, aku ingin terus mencari hal-hal seperti ini.",
  ui_story_5088_50880100_79_dialog_content = "Aku harus membantu mereka... Aku harus menemukan lebih banyak lagi kenangan untuk teman-temanku.",
  ui_story_5088_50880100_80_dialog_content = "Jadi kamu datang ke Lady Sheol untuk minta bantuan?",
  ui_story_5088_50880100_81_dialog_content = "Ya, dia melakukannya, tapi waktu adalah uang, jadi tolong lanjutkan pencarian.",
  ui_story_5088_50880100_82_dialog_content = "Ada begitu banyak barang yang berserakan di sini. Kamu yakin kamu tidak hanya membuatnya semakin sulit untuk dia?",
  ui_story_5088_50880100_83_dialog_content = "Saya pasti bisa merasakan sesuatu yang serupa datang dari salah satu barang antik ini... Tapi jumlahnya terlalu banyak.",
  ui_story_5088_50880100_84_dialog_content = "*batuk-batuk* Wah, lihatlah semua debu ini... Bukan berarti saya tidak ingin membantu Anda, sayangku. Barang-barang ini sederhana saja terlalu tua, dan melacak asal-usul mereka hampir mustahil.",
  ui_story_5088_50880100_85_dialog_content = "Seandainya aku tidak menyimpannya untuk menjaganya, mungkin sekarang ini sudah ada orang lain di Umbraton yang merusaknya.",
  ui_story_5088_50880100_86_dialog_content = "Lagi pula, saya bukan ahli dalam hal-hal ini. Ah, jika saja Vergil di sini untuk menyelesaikannya.",
  ui_story_5088_50880100_87_dialog_content = "Sini, biar kubantu—Ini dia.",
  ui_story_5088_50880100_88_dialog_content = "Eh... Apakah kamu hanya mengambil barang secara acak?",
  ui_story_5088_50880100_89_dialog_content = "Ketika kerja keras tidak bisa menyelesaikan pekerjaan, kamu harus mengandalkan keberuntungan dan intuisi.",
  ui_story_5088_50880100_90_dialog_content = "Percayalah padaku.",
  ui_story_5088_50880100_91_dialog_content = "I-Ini...",
  ui_story_5088_50880100_92_dialog_content = "Huh? Astaga, ternyata berhasil juga.",
  ui_story_5088_50880100_93_dialog_content = "Tidak ada keraguan lagi. Ini adalah Star Crest!",
  ui_story_5088_50880100_94_dialog_content = "Ini persis yang sedang saya cari!",
  ui_story_5088_50880100_95_dialog_content = "Baguslah kalau begitu.",
  ui_story_5088_50880100_96_dialog_content = "Karena tampaknya sangat berharga bagi kamu, aku akan membiarkan kamu menyimpannya secara gratis.",
  ui_story_5088_50880100_97_dialog_content = "Saya tidak memerlukannya di sini, jadi anggaplah ini sebagai hadiah untuk pelanggan nomor satu saya.",
  ui_story_5088_50880100_98_dialog_content = "Terima kasih banyak, Nona Sheol!",
  ui_story_5088_50880100_99_dialog_content = "Aku harus pergi sekarang. Sampai jumpa!",
  ui_story_5088_50880100_100_dialog_content = "Sudah gelap di luar. Biar aku antar kamu pulang.",
  ui_story_5088_50880100_101_dialog_content = "Aduh—",
  ui_story_5088_50880100_102_dialog_content = "Ah! M-maaf, saya tidak bermaksud untuk... Tweety?",
  ui_story_5088_50880100_103_dialog_content = "Hoi! Itu kamu, Tuan Navigator!",
  ui_story_5088_50880100_104_dialog_content = "Maafkan itu, saya tadi terlalu terburu-buru.",
  ui_story_5088_50880100_105_dialog_content = "Apakah Anda baik-baik saja, Ma'am?",
  ui_story_5088_50880100_106_dialog_content = "Oh bagus, tidak ada surat yang hilang.",
  ui_story_5088_50880100_107_dialog_content = "\"Bu\"?",
  ui_story_5088_50880100_108_dialog_content = "Izinkan saya untuk memperkenalkan Courier terbaru kami! Dia cukup berbakat, kamu tahu!",
  ui_story_5088_50880100_109_dialog_content = "Senang bertemu dengan kalian semua. Nama saya Mithra, dan saya telah ditugaskan kepada Miss Tweety sebagai asistennya.",
  ui_story_5088_50880100_110_dialog_content = "Ini terasa benar-benar aneh... Kamu jauh lebih tinggi darinya.",
  ui_story_5088_50880100_111_dialog_content = "Hihi...",
  ui_story_5088_50880100_112_dialog_content = "Maaf semua orang, tapi aku benar-benar harus pergi! Aku akan pastikan untuk minta maaf dengan layak kepadamu nanti, Tweety!",
  ui_story_5088_50880100_113_dialog_content = "Sampai jumpa di sekitar, Tuan Navigator!",
  ui_story_5088_50880100_114_dialog_content = "Kamu yakin tidak ada yang lain?",
  ui_story_5088_50880100_115_dialog_content = "Ini semua yang bisa kamu ingat?",
  ui_story_5088_50880100_116_dialog_content = "Untuk alasan tertentu, kamu menghabiskan sebagian besar waktu kamu tinggal di kota tempat kamu ditugaskan.",
  ui_story_5088_50880100_117_dialog_content = "Lupakan saja. Mengingat hal-hal ini tidak akan memberimu kebaikan sekarang.",
  ui_story_5088_50880100_118_dialog_content = "Aku tidak peduli jika itu menyakitkan. Aku harus memulihkan ingatanku.",
  ui_story_5088_50880100_119_dialog_content = "Aku masih bisa mengingatnya... Cintaku... Tapi entah kenapa, aku bahkan tidak bisa mengingat wajahnya...",
  ui_story_5088_50880100_120_dialog_content = "Hanya karena dia, aku bersumpah untuk melindungi orang-orang benar dengan pedangku.",
  ui_story_5088_50880100_121_dialog_content = "Jadi tolong, setidaknya beri tahu saya namanya!",
  ui_story_5088_50880100_122_dialog_content = "Ta-daaa! Bagaimana? Apakah kedatangan anggun saya membuatmu terkejut?",
  ui_story_5088_50880100_123_dialog_content = "Hei! Kalian mulai tanpa aku!",
  ui_story_5088_50880100_124_dialog_content = "Ini salahmu karena terlalu lambat.",
  ui_story_5088_50880100_125_dialog_content = "Aku tidak melewatkan apapun, bukan?",
  ui_story_5088_50880100_126_dialog_content = "...",
  ui_story_5088_50880100_127_dialog_content = "Maaf, tapi saya juga tidak ingat apa-apa.",
  ui_story_5088_50880100_128_dialog_content = "Oh, begitu…",
  ui_story_5088_50880100_129_dialog_content = "Lalu bagaimana dengan nama lain itu? \"Claymore\"?",
  ui_story_5088_50880100_130_dialog_content = "?!",
  ui_story_5088_50880100_131_dialog_content = "Berani-beraninya kau menyebut-nyebut nama orang itu lagi!",
  ui_story_5088_50880100_132_dialog_content = "Hei, tenanglah sudah!",
  ui_story_5088_50880100_133_dialog_content = "Lepaskan saya—! Kita sudah sepakat untuk tidak pernah membicarakan dia lagi!",
  ui_story_5088_50880100_134_dialog_content = "Anda sendiri yang memotong-motong orang itu hari itu.",
  ui_story_5088_50880100_135_dialog_content = "Apakah ini alasan Anda mengumpulkan kami di sini hari ini? Untuk membuat kami mengingat rasa sakit lagi?!",
  ui_story_5088_50880100_136_dialog_content = "Aku... Aku membenci orang itu. Entah bagaimana aku hanya melakukannya, dan aku tidak tahu mengapa...",
  ui_story_5088_50880100_137_dialog_content = "Tapi ketika PlayerName menunjukkannya kepada saya, itu hanya semakin meyakinkan saya... Orang itu...",
  ui_story_5088_50880100_138_dialog_content = "Namanya adalah Achilles, dan dia adalah pemimpin kami.",
  ui_story_5088_50880100_139_dialog_content = "Ya? Jadi apa?",
  ui_story_5088_50880100_140_dialog_content = "Dia adalah jenderalmu, dan pemimpin dari kelompok kita.",
  ui_story_5088_50880100_141_dialog_content = "Tapi dia mengkhianati kita.",
  ui_story_5088_50880100_142_dialog_content = "Kenyataannya, kita semua sepakat tentang itu—tentang membiarkan diri kita hancur.",
  ui_story_5088_50880100_143_dialog_content = "Tapi ketika pedangnya menembus hatiku, saya merasa... kesal.",
  ui_story_5088_50880100_144_dialog_content = "Aku sangat lega bisa merasakan sesuatu setelah semua ini... Tapi segera aku menyadari... Rasa sakit itu tidak kunjung hilang.",
  ui_story_5088_50880100_145_dialog_content = "Kapten pernah menjadi pahlawan besar, dan teman baik bagi kita semua. Mengakhiri penderitaannya adalah hal terkecil yang bisa kita lakukan.",
  ui_story_5088_50880100_146_dialog_content = "Benar. Dia adalah seorang pahlawan... Dan aku berutang nyawa padanya.",
  ui_story_5088_50880100_147_dialog_content = "Itulah sebabnya... Rasa benci itu semakin memuncak ketika dia tiba-tiba menyerang.",
  ui_story_5088_50880100_148_dialog_content = "Mestinya tak seperti ini... Aku tahu aku seharusnya tidak membencinya...",
  ui_story_5088_50880100_149_dialog_content = "Mungkin kita melupakan sesuatu yang penting?",
  ui_story_5088_50880100_150_dialog_content = "Sebagai contoh... Apakah benar-benar hanya ada lima dari kita waktu itu?",
  ui_story_5088_50880100_151_dialog_content = "Saya ingin mengingat segalanya.",
  ui_story_5088_50880100_152_dialog_content = "Apa yang terjadi pada kita di masa lalu? Dan apa yang terjadi ketika kita akhirnya terbangun kembali?",
  ui_story_5088_50880100_153_dialog_content = "Apa tepatnya yang telah kita lupakan? Akankah kita pernah mengingat semuanya?",
  ui_story_5088_50880100_154_dialog_content = "<size=30>Orang yang tidak bisa kita ingat adalah orang yang mencatat segala hal tentang kita. Maafkan kami... Teman lama yang telah kita lupakan.</size>",
  ui_story_5088_50880100_155_dialog_content = "Aku bisa merasakan keberadaan Aurorian di dalam gua beku ini... Tapi bagaimana? Apakah ini alasan Ratu memintaku untuk menyelidiki?",
  ui_story_5088_50880100_156_dialog_content = "Bertahanlah! Aku akan mengeluarkan kalian dari sana...",
  ui_story_5088_50880100_157_dialog_content = "Semuanya sudah siap sekarang. Segel hanya akan pecah ketika seorang Caelestite memutuskan untuk membebaskan mereka dari tempat ini.",
  ui_story_5088_50880100_158_dialog_content = "Sebagai gantinya, itu akan menjebak saya di sini dan perlahan-lahan menguras kekuatan saya. Tapi meskipun saya menjadi Eclipsite, saya akan terus mengawasi mereka.",
  ui_story_5088_50880100_159_dialog_content = "Apakah itu...?",
  ui_story_5088_50880100_160_dialog_content = "Kapten... Kenapa...",
  ui_story_5088_50880100_161_dialog_content = "Apakah aku...?",
  ui_story_5088_50880100_162_dialog_content = "Hah? Aku masih hidup?",
  ui_story_5088_50880100_163_dialog_content = "Hei... Cahaya apa itu yang muncul dari bawah sana? Apakah segelnya sudah diaktifkan?",
  ui_story_5088_50880100_164_dialog_content = "Formasi ini... Apakah ini tempat dari sebelumnya? Gua di mana pria itu...",
  ui_story_5088_50880100_165_dialog_content = "Seorang... Seorang Caelestite?",
  ui_story_5088_50880100_166_dialog_content = "Keren!!!",
  ui_story_5088_50880100_167_dialog_content = "Argh... Kepalaku... Apa yang terjadi? Kenapa tiba-tiba aku mendengar begitu banyak suara?!",
  ui_story_5088_50880100_168_dialog_content = "Tidak—Pergilah! Tinggalkan aku sendiri!",
  ui_story_5088_50880100_169_dialog_content = "A-Apakah kamu baik-baik saja?",
  ui_story_5088_50880100_170_dialog_content = "Suara itu... dia masih hidup!",
  ui_story_5088_50880100_171_dialog_content = "Claymore... Pembela kerajaan ini akan menghancurkan kita semua!",
  ui_story_5088_50880100_172_dialog_content = "Hai! Sekarang bukan waktunya memikirkan hal itu!",
  ui_story_5088_50880100_173_dialog_content = "Anak laki-laki ini menyelamatkan kita, tetapi sepertinya kondisinya sangat buruk.",
  ui_story_5088_50880100_174_dialog_content = "Menyelamatkan orang-orang adalah prioritas utama, seperti biasa. Kita akan menyelesaikan sisanya nanti.",
  ui_story_5088_50880100_175_dialog_content = "...Kalau begitu, ayo pergi.",
  ui_story_5088_50880100_176_dialog_content = "Dia mengejar kita.",
  ui_story_5088_50880100_177_dialog_content = "Sihir hutan, sembunyikan kami dari pandangan pengejar kami—Pergi!",
  ui_story_5088_50880100_178_dialog_content = "T-Tidak ada jalan keluar!",
  ui_story_5088_50880100_179_dialog_content = "<size=45>Maut bagi semua musuh!!!</size>",
  ui_story_5088_50880100_180_dialog_content = "<color=#e8d9bb>Lonjakan kekuatan mentah meledak keluar, merobek melalui cabang-cabang magis yang tebal.</color>",
  ui_story_5088_50880100_181_dialog_content = "Sakit...",
  ui_story_5088_50880100_182_dialog_content = "Seorang Caelestite... Aku harus menyelamatkannya...",
  ui_story_5088_50880100_183_dialog_content = "<color=#e8d9bb>Energi dari pedang besar itu membelah tanah saat melonjak menuju grup.</color>",
  ui_story_5088_50880100_184_dialog_content = "<color=#e8d9bb>Tapi pada detik-detik terakhir, Eclipsite mengalihkan kekuatan luar biasanya dari mereka.</color>",
  ui_story_5088_50880100_185_dialog_content = "<color=#e8d9bb>Diam-diam, dia mengamati saat buruannya melarikan diri.</color>",
  ui_story_5088_50880100_186_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50880201_1_dialog_content = "(Emblem ini berbeda dari yang dibawa oleh Adras dan yang lainnya. Ada gambar unik yang terukir di atasnya.)",
  ui_story_5088_50880201_2_dialog_content = "Mungkinkah ini milik Claymore...?",
  ui_story_5088_50880201_3_dialog_content = "(Aku bisa merasakan kekuatannya yang berasal dari itu.)",
  ui_story_5088_50880201_4_option_content = "Psychic Scan",
  ui_story_5088_50880201_5_dialog_content = "<color=#e8d9bb>Hari Kelima: Dan Si Pengkhianat Berkata, \"Para Pahlawan Akan Mati.\"</color>",
  ui_story_5088_50880201_6_dialog_content = "Minggir!",
  ui_story_5088_50880201_7_dialog_content = "Kriek—Kriek—",
  ui_story_5088_50880201_8_dialog_content = "... Begitu, ya.",
  ui_story_5088_50880201_9_dialog_content = "Mereka sekarang adalah Eclipsite...",
  ui_story_5088_50880201_10_dialog_content = "Mereka adalah prajurit yang berani dan setia, tetapi kamu mengubah mereka menjadi monster.",
  ui_story_5088_50880201_11_dialog_content = "Dan sekarang, hanya \"monster\" lain seperti aku yang bisa mengakhiri penderitaan mereka.",
  ui_story_5088_50880201_12_dialog_content = "Tidak ada pilihan lain.",
  ui_story_5088_50880201_13_dialog_content = "Bisakah Anda masih menyebut diri Anda \"raja\" sekarang?",
  ui_story_5088_50880201_14_dialog_content = "Atau seorang manusia, sejauh itu?",
  ui_story_5088_50880201_15_dialog_content = "<size=45>Gaius Agamemnon!!!</size>",
  ui_story_5088_50880201_16_dialog_content = "Turun dari tahta busukmu dan hadapilah aku!",
  ui_story_5088_50880202_1_dialog_content = "Apa... Apa di dunia...",
  ui_story_5088_50880202_2_dialog_content = "Tuan Achilles... Jangan bilang kamu juga sudah kehilangan akal sehatmu?",
  ui_story_5088_50880202_3_dialog_content = "...",
  ui_story_5088_50880202_4_dialog_content = "Di luar sana ada raja. Kami tidak bisa membiarkan kamu lewat.",
  ui_story_5088_50880202_5_dialog_content = "Jika ada di antara kalian yang masih melihat saya sebagai Achilles, tolong minggir.",
  ui_story_5088_50880202_6_dialog_content = "Ada yang ingin kukatakan pada pria itu.",
  ui_story_5088_50880202_7_dialog_content = "Namun…",
  ui_story_5088_50880202_8_dialog_content = "Biarkan dia lewat.",
  ui_story_5088_50880202_9_dialog_content = "Kamu tidak bisa menghentikannya meskipun kamu mencoba. Tidak ada gunanya mengorbankan diri kalian dengan sia-sia.",
  ui_story_5088_50880202_10_dialog_content = "Ya, Yang Mulia!",
  ui_story_5088_50880202_11_dialog_content = "Dengan cara ini, Lord Achilles...",
  ui_story_5088_50880202_12_dialog_content = "... Tidak ada satu pun dari kawan-kawan ku yang pernah kehilangan akal sehat mereka. Ingat itu.",
  ui_story_5088_50880202_13_dialog_content = "Kamu sudah menderita banyak hanya untuk bertahan hidup sampai sekarang, Achilles. Kenapa tidak membiarkan segalanya berakhir seperti seharusnya?",
  ui_story_5088_50880202_14_dialog_content = "Kawan-kawan dan aku... tidak peduli tentang menjadi martir.",
  ui_story_5088_50880202_15_dialog_content = "Tapi aku tahu mereka pantas mendapatkan akhir yang jauh lebih baik, dan aku bersedia menukar hidupku untuk memberikannya kepada mereka.",
  ui_story_5088_50880202_16_dialog_content = "Tapi sejak detik pengawalmu mengacungkan pedang pada ku... Aku menyadari kau tidak pernah berniat membiarkan kami hidup.",
  ui_story_5088_50880202_17_dialog_content = "Kesetiaanku padamu berakhir hari ini.",
  ui_story_5088_50880202_18_dialog_content = "Apa yang membuatmu berkata seperti itu? Jangan-jangan... karena Caelestite yang sudah wafat yang kamu gendong di punggungmu?",
  ui_story_5088_50880202_19_dialog_content = "Yah, kamu bisa menjaganya. Lagipula, aku tahu hari ini pasti akan datang.",
  ui_story_5088_50880202_20_dialog_content = "Kamu dan kawan-kawanmu tidak berhutang apa-apa padaku. Jika ada, aku yang berhutang padamu.",
  ui_story_5088_50880202_21_dialog_content = "Tapi kita semua tahu dengan baik bahwa tindakan yang telah kulakukan adalah benar.",
  ui_story_5088_50880202_22_dialog_content = "Saya mencari kehancuranmu bukan karena keinginan pribadi, tetapi demi kedamaian yang telah susah payah kita raih di kerajaan kita sekarang.",
  ui_story_5088_50880202_23_dialog_content = "Kamu... Bagaimana kamu bisa mengatakan itu?!",
  ui_story_5088_50880202_24_dialog_content = "Aku mengorbankan semua yang aku sayangi, dan kerajaan kita sekarang damai karena itu.",
  ui_story_5088_50880202_25_dialog_content = "Aku akan selalu mengenang setiap tetes darah yang kau dan kawan-kawanmu tumpahkan demi bangsa kita.",
  ui_story_5088_50880202_26_dialog_content = "Dewan Tetua dipaksa untuk memberontak, dan api perang masih membakar seluruh kerajaan! Apakah ini yang kamu sebut \"damai\"?!",
  ui_story_5088_50880202_27_dialog_content = "Api berada di bawah kendaliku. Saya tahu persis apa yang harus mereka bakar.",
  ui_story_5088_50880202_28_dialog_content = "…!",
  ui_story_5088_50880202_29_dialog_content = "Siapa mata-mata Anda di dalam Dewan Tetua?",
  ui_story_5088_50880202_30_dialog_content = "Dan siapa yang telah kamu kirim untuk menghancurkan mereka?",
  ui_story_5088_50880202_31_dialog_content = "Kenapa aku dibiarkan dalam kegelapan selama ini?!",
  ui_story_5088_50880202_32_dialog_content = "Achilles, ketika kamu bersumpah untuk menegakkan keadilan tanpa memandang biaya...",
  ui_story_5088_50880202_33_dialog_content = "Aku tahu aku harus menjauhkan diri dari kamu.",
  ui_story_5088_50880202_34_dialog_content = "Tapi masih banyak orang di Dewan Tetua yang setia pada kerajaan... Bagaimana bisa kamu...",
  ui_story_5088_50880202_35_dialog_content = "Pikirkan, Achilles.",
  ui_story_5088_50880202_36_dialog_content = "Utara dulunya adalah tempat yang kacau dan penuh perang, tapi kamu dan saya telah meletakkan dasar untuk perdamaian.",
  ui_story_5088_50880202_37_dialog_content = "Tidak ada seorang pun di Dewan Penatua yang menghargai perdamaian, itulah sebabnya mereka memilih untuk menabur kebencian di antara kita.",
  ui_story_5088_50880202_38_dialog_content = "Ketika keluargaku menjadi tersangka, tiran itu mengasingkan mereka ke daerah terdingin di negeri ini dan meninggalkan mereka untuk mati.",
  ui_story_5088_50880202_39_dialog_content = "Dewan Penatua menjadi saksi kehancuran keluargaku, dan tidak melakukan apa-apa untuk membantuku saat aku ditawan.",
  ui_story_5088_50880202_40_dialog_content = "Saya telah menerima segala yang telah terjadi pada saya.",
  ui_story_5088_50880202_41_dialog_content = "Jadi kamu memutuskan untuk membasmi seluruh keluarga mantan raja.",
  ui_story_5088_50880202_42_dialog_content = "Pada saat itu... Aku terlambat untuk menghentikanmu.",
  ui_story_5088_50880202_43_dialog_content = "Tapi bahkan saat itu, saya tidak menyadari bahwa kebencian Anda juga merambah ke Dewan Tetua...",
  ui_story_5088_50880202_44_dialog_content = "Kamu salah. Aku sudah lama melepaskan dendamku, itulah sebabnya kita bisa menyatukan negara-negara kota yang bertikai di Northland menjadi satu bangsa yang sejati.",
  ui_story_5088_50880202_45_dialog_content = "Apa yang telah dilakukan Elder Council hingga mereka pantas mendapatkan nasib mereka?",
  ui_story_5088_50880202_46_dialog_content = "Mereka takut padaku, Achilles. Mereka berharap untuk menghentikan revolusiku dengan membalikkan rakyat kita melawan saya, termasuk para imam.",
  ui_story_5088_50880202_47_dialog_content = "Mereka juga telah menzalimi kamu untuk memenangkan simpati dan kekuatan militermu, bukan?",
  ui_story_5088_50880202_48_dialog_content = "Itu bukan urusanku.",
  ui_story_5088_50880202_49_dialog_content = "Pernah ada waktu ketika aku percaya salah satu dari kita bisa menjadi raja. Tapi kamu selalu terlalu tegak untuk tahta.",
  ui_story_5088_50880202_50_dialog_content = "Seseorang seperti kamu tidak akan pernah bisa membersihkan korupsi dari kerajaan kita dan membawa kedamaian bagi rakyatnya.",
  ui_story_5088_50880202_51_dialog_content = "Seandainya saja kau terlahir di era damai. Sehebat dan seadil-adilnya dirimu, kau bisa menjadi marshal terhebat dalam sejarah kerajaan kita.",
  ui_story_5088_50880202_52_dialog_content = "Tapi saat ini, tidak ada yang bisa kamu lakukan untuk membantuku. Kamu sama sekali bukan marshal yang dibutuhkan Northland saat ini.",
  ui_story_5088_50880202_53_dialog_content = "Itulah sebabnya kamu tidak pernah bisa lebih dari seorang jenderal... Atau monster yang memimpin monster lainnya.",
  ui_story_5088_50880202_54_dialog_content = "Cukup sudah omong kosongmu yang tak berarti, Agamemnon! Bebaskan kawan-kawan ku dan hentikan pembunuhan tak berarti ini.",
  ui_story_5088_50880202_55_dialog_content = "Dan jika saya menolak?",
  ui_story_5088_50880202_56_dialog_content = "Sumber ancaman Eclipsite telah diberantas, Dewan Tetua berada di ambang kehancuran, dan kuil telah kehilangan Imam Besarnya.",
  ui_story_5088_50880202_57_dialog_content = "Sebagai pemenang yang tak terbantahkan, mengapa Anda bersikeras untuk melanjutkan aksi pembunuhan Anda?",
  ui_story_5088_50880202_58_dialog_content = "Sekarang setelah kamu telah mengeliminasi dua dari tiga badan pemerintahan kerajaan kita, kamu bisa menjadi kaisar dari seluruh Northland.",
  ui_story_5088_50880202_59_dialog_content = "Anda dan kawan-kawan Anda terlalu kuat untuk dibiarkan hidup. Keberadaan Anda sendiri menimbulkan risiko besar terhadap perdamaian yang sangat saya inginkan.",
  ui_story_5088_50880202_60_dialog_content = "Dan kenyataannya tetap bahwa kalian semua tidak berdaya untuk menekan korupsi dalam tubuh kalian.",
  ui_story_5088_50880202_61_dialog_content = "Setidaknya... Kamu harus membiarkan anak-anak dan membiarkan kawan-kawan ku meninggalkan kerajaan... Sehingga mereka dapat membawa teman baik kita kembali ke tanah airnya yang jauh dan menidurkannya dengan tenang.",
  ui_story_5088_50880202_62_dialog_content = "Aku akan tinggal di sini, dan membayar berapapun harga yang kamu minta dariku.",
  ui_story_5088_50880202_63_dialog_content = "Saya tidak pernah berpikir bahwa Anda akan berbicara atas nama Dewan Tetua di akhir. Apakah Anda melakukan ini karena keadilan? Atau mungkin karena kesetiaan kepada orang-orang Anda sendiri?",
  ui_story_5088_50880202_64_dialog_content = "Aku melakukan ini sebagai seorang individu, Agamemnon.",
  ui_story_5088_50880202_65_dialog_content = "... Para Star Warriors lainnya telah jatuh ke dalam kegilaan. Kamu, Achilles, adalah satu-satunya yang tekadnya belum goyah.",
  ui_story_5088_50880202_66_dialog_content = "Tidak heran Caelestite bodoh itu memberikan hidupnya untuk—",
  ui_story_5088_50880202_67_dialog_content = "<color=#e8d9bb>Tekanan dari sebuah kriek yang kuat memotong kalimatnya di tengah jalan.</color>",
  ui_story_5088_50880202_68_dialog_content = "Bukan kata lain!",
  ui_story_5088_50880202_69_dialog_content = "Aku tidak akan membiarkanmu menghina temanku lagi!",
  ui_story_5088_50880202_70_dialog_content = "...\"Teman,\" kata kamu?",
  ui_story_5088_50880202_71_dialog_content = "Bukankah aku juga temanmu, Achilles?",
  ui_story_5088_50880202_72_dialog_content = "Selama hari-hari militer kita, kamu adalah sekutu paling dapat diandalkan saya, sepercaya lengan pedang saya sendiri. Saya masih ingat berapa kali kamu menyelamatkan hidup saya.",
  ui_story_5088_50880202_73_dialog_content = "Tapi momen yang paling berkesan... adalah ketika aku menjatuhkan perisai ku dalam pertempuran, dan kamu melindungi saya dengan tubuhmu. Aku ingat semua tujuh belas luka yang kamu alami hari itu.",
  ui_story_5088_50880202_74_dialog_content = "... Dan karena aku, kamu memecah barisan dan memotong para tombak yang mendekat padaku, semua tanpa perisaimu.",
  ui_story_5088_50880202_75_dialog_content = "Luka-lukamu sama parahnya dengan luka saya, dan kamu diberi belenggu karena melanggar perintah. Kakakmu sendiri meninggal di penjara karena hal itu juga.",
  ui_story_5088_50880202_76_dialog_content = "Sekutu...",
  ui_story_5088_50880202_77_dialog_content = "Aku tahu kamu tidak akan pernah bisa membunuhku, Achilles, karena tidak ada orang yang lebih baik yang bisa menggantikan tempatku.",
  ui_story_5088_50880202_78_dialog_content = "Tak satu pun dari kita yang ingin menenggelamkan kerajaan kita dalam kekacauan sekali lagi.",
  ui_story_5088_50880202_79_dialog_content = "...",
  ui_story_5088_50880202_80_dialog_content = "Sekarang pergi.",
  ui_story_5088_50880202_81_dialog_content = "?!",
  ui_story_5088_50880202_82_dialog_content = "Tidak ada bedanya jika saya membiarkan satu dari kalian atau semua kalian pergi.",
  ui_story_5088_50880202_83_dialog_content = "Bawa mereka semua bersamamu. Rekan timmu, para pejuang yang bersumpah setia padamu, anak-anak dari Dewan Tetua, dan teman Caelestite-mu...",
  ui_story_5088_50880202_84_dialog_content = "Bawa mereka ke tempat yang jauh, dan jangan pernah menginjak tanah kami yang suci dan tak ternoda lagi.",
  ui_story_5088_50880202_85_dialog_content = "Aku akan menghapus segala catatan tentang kamu dan kawan-kawanmu dari sejarah kita. Tak seorang pun akan menyanyikan pujianmu atau mencari kekuatan yang kamu miliki lagi.",
  ui_story_5088_50880202_86_dialog_content = "Aku akan memastikan bahwa seni menciptakan prajurit Eclipsite hilang seiring berjalannya waktu.",
  ui_story_5088_50880202_87_dialog_content = "Pandanglah mataku, Gaius Agamemnon, dan katakanlah bahwa kamu melakukan ini bukan untuk keuntungan pribadi, tetapi demi cita-cita kita.",
  ui_story_5088_50880202_88_dialog_content = "Ya. Bahkan saat aku terjun ke dalam sungai dosa yang tak termaafkan... Aku akan selalu merindukan kedamaian. Ini akan menjadi sangat benar setelah aku naik takhta dan melihat kekacauan sebagai raja.",
  ui_story_5088_50880202_89_dialog_content = "Dan dengan demikian, aku akan menanggung kotoran yang tidak pernah bisa kamu terima. Selama Northland tidak diganggu oleh perang atau orang-orang yang mencarinya, aku bersumpah dengan sungguh-sungguh—",
  ui_story_5088_50880202_90_dialog_content = "Tidak ada anak laki-laki yang harus meminta-minta roti untuk bertahan hidup. Tidak ada Suci Perempuan yang harus terbakar lagi. Tidak ada Anak Kecil yang akan tersesat di hutan lagi...",
  ui_story_5088_50880202_91_dialog_content = "Tak ada gadis yang akan ditakuti karena apinya. Tak ada anak kecil yang akan lahir dan ditinggalkan di panti asuhan. Tak seorang pun harus menghabiskan seluruh hidupnya dalam air mata...",
  ui_story_5088_50880202_92_dialog_content = "Dan tak seorang pun yang jujur harus merasakan sakit pengkhianatan lagi.",
  ui_story_5088_50880202_93_dialog_content = "Aku akan menghabiskan setiap jejak kotoran sampai seluruh Northland sebersih dan sempurna seperti salju yang menutupinya.",
  ui_story_5088_50880202_94_dialog_content = "Untuk ini, saya akan membayar berapapun harganya.",
  ui_story_5088_50880202_95_dialog_content = "Beritahu aku, bagaimana rasanya duduk sendirian di atas takhta yang busuk?",
  ui_story_5088_50880202_96_dialog_content = "...",
  ui_story_5088_50880202_97_dialog_content = "...",
  ui_story_5088_50880202_98_dialog_content = "Selamat tinggal, Gaius Agamemnon.",
  ui_story_5088_50880202_99_dialog_content = "Selamat tinggal, teman saya.",
  ui_story_5088_50880202_100_dialog_content = "May Semua kamu menemukan kedamaian suatu hari nanti.",
  ui_story_5088_50880202_101_dialog_content = "... Dingin.",
  ui_story_5088_50880202_102_dialog_content = "Takhta ini lebih dingin daripada yang bisa kamu bayangkan, temanku.",
  ui_story_5088_50880202_103_dialog_content = "<color=#e8d9bb>Hari Keenam: Para Pemburu—Kisah yang Hilang Dimakan Waktu.</color>",
  ui_story_5088_50880202_104_dialog_content = "Kebenaran sering terkubur di bawah pasir waktu.",
  ui_story_5088_50880202_105_dialog_content = "Apa lagi yang bisa kulakukan? Bahkan jika aku merekam semuanya... Akankah ada yang tahu kebenarannya?",
  ui_story_5088_50880202_106_dialog_content = "Aku sudah gagal. Tak ada yang bisa kulakukan untuk menyelamatkanmu.",
  ui_story_5088_50880202_107_dialog_content = "Tapi aku juga berhasil. Tak seorang pun di kerajaan akan menyebut namamu lagi.",
  ui_story_5088_50880202_108_dialog_content = "Kamu akan dilupakan. Terlepas dari pencapaian atau aib, kamu akan dilupakan.",
  ui_story_5088_50880202_109_dialog_content = "Kalian semua adalah bintang yang memudar. Setelah cahayamu meredup, tak akan ada yang mengingatmu.",
  ui_story_5088_50880202_110_dialog_content = "Dan kamu masih menulis di jurnal Anda, Tuan Achilles.",
  ui_story_5088_50880202_111_dialog_content = "Bahkan jika kita menghancurkan setiap catatan tentang keberadaan mereka, kamu tidak akan pernah bisa melupakan mereka.",
  ui_story_5088_50880202_112_dialog_content = "Ini karena Freya pernah mengatakan bahwa dia tidak ingin kita dilupakan.",
  ui_story_5088_50880202_113_dialog_content = "Sisanya dunia bisa melupakan kita, karena bencana itu tidak akan pernah muncul di dunia ini lagi.",
  ui_story_5088_50880202_114_dialog_content = "Tapi aku tidak bisa... Aku tidak bisa melupakan mereka...",
  ui_story_5088_50880202_115_dialog_content = "Kata-kata yang saya tulis hanya untuk diriku sendiri.",
  ui_story_5088_50880202_116_dialog_content = "... Dan kamu yakin segel ini cukup kokoh untuk bertahan melawan ujian waktu?",
  ui_story_5088_50880202_117_dialog_content = "Semuanya sudah siap sekarang. Segel hanya akan pecah ketika seorang Caelestite memutuskan untuk membebaskan mereka dari tempat ini.",
  ui_story_5088_50880202_118_dialog_content = "Bintang-bintang kini berada dalam kedamaian, dan anak-anak telah berhasil dikawal keluar dari Northland oleh yang lainnya...",
  ui_story_5088_50880202_119_dialog_content = "Hanya ada satu hal terakhir yang bisa kulakukan untukmu, Tuan Achilles, dan sekaranglah waktunya untuk melakukannya.",
  ui_story_5088_50880202_120_dialog_content = "Apa ya kira-kira?",
  ui_story_5088_50880202_121_dialog_content = "Saya satu-satunya manusia di dunia ini yang tahu tentang tempat ini, dan saya harus memastikan bahwa keberadaannya tetap menjadi rahasia selamanya.",
  ui_story_5088_50880202_122_dialog_content = "Aku berutang nyawa padamu, Tuan, dan sekarang saatnya aku membayar hutang itu dengan nyawaku!",
  ui_story_5088_50880202_123_dialog_content = "Lord Achilles? Mengapa Anda menghentikan saya?",
  ui_story_5088_50880202_124_dialog_content = "Cukup, Anthony. Kau sudah memberikan kesetiaan dan persahabatanmu padaku. Tidak perlu memberikan hidupmu untukku.",
  ui_story_5088_50880202_125_dialog_content = "Namun…",
  ui_story_5088_50880202_126_dialog_content = "Formasi ini memiliki dua tujuan: untuk mempertahankan segel pada kawan-kawan saya, dan untuk mencegah saya merugikan mereka saat saya kehilangan akal sehat saya.",
  ui_story_5088_50880202_127_dialog_content = "Sebagai gantinya, itu akan menjebak saya di sini dan perlahan-lahan menguras kekuatan saya. Tapi meskipun saya menjadi Eclipsite, saya akan terus mengawasi mereka.",
  ui_story_5088_50880202_128_dialog_content = "Aku tidak memiliki cara untuk meninggalkan tempat ini, Anthony.",
  ui_story_5088_50880202_129_dialog_content = "Jadi tolong, temukan Eraveil di tempatku dan bantu aku meletakkan Ludweiss untuk beristirahat di tanah airnya.",
  ui_story_5088_50880202_130_dialog_content = "Ini adalah janji yang saya buat padanya.",
  ui_story_5088_50880202_131_dialog_content = "Ludweiss pernah memberitahuku bahwa Eraveil belum terbuka untuk dunia luar. Mungkin butuh bertahun-tahun untuk kamu menemukannya.",
  ui_story_5088_50880202_132_dialog_content = "Tapi sampai saat itu, kau tidak diperbolehkan mati.",
  ui_story_5088_50880202_133_dialog_content = "Tuan Achilles... Kamu tahu aku akan mencoba mengambil nyawaku sendiri untuk menjaga tempat ini tetap rahasia, bukan?",
  ui_story_5088_50880202_134_dialog_content = "...",
  ui_story_5088_50880202_135_dialog_content = "Jadi, kamu memutuskan untuk menggunakan ini sebagai alasan untuk mencegahku melakukannya.",
  ui_story_5088_50880202_136_dialog_content = "Anda telah memberikan setiap ons kebaikan dalam tubuh Anda kepada setiap orang kecuali diri Anda sendiri. Itu tidak adil, tuanku.",
  ui_story_5088_50880202_137_dialog_content = "Tapi jika ini adalah keinginanmu... Maka, saya, Anthony Longinus, dengan ini bersumpah kepada kamu:",
  ui_story_5088_50880202_138_dialog_content = "Keluarga Longinus akan mencari Eraveil, serta cara untuk menyelamatkan kamu dan kawan-kawanmu. Meskipun pencarian kami melintasi generasi, kami tidak akan berhenti sampai kami berhasil.",
  ui_story_5088_50880202_139_dialog_content = "Anthony...",
  ui_story_5088_50880202_140_dialog_content = "Mulai hari ini dan seterusnya, keturunanku dan aku akan menjaga rahasia Anda.",
  ui_story_5088_50880202_141_dialog_content = "Dan jika aku tidak bisa bersamamu di akhir penjagaan abadimu, Tuhan Achilles...",
  ui_story_5088_50880202_142_dialog_content = "Keluarga Longinus akan tetap di sisi Anda sepanjang zaman.",
  ui_story_5088_50880202_143_dialog_content = "Tidak perlu untuk itu.",
  ui_story_5088_50880202_144_dialog_content = "Dunia mungkin akan melupakan bintang-bintang, tetapi kami akan selalu bertahan dalam pencarian kami untuk menyelamatkanmu. Jika kami harus melakukannya dalam kegelapan total, maka biarlah demikian.",
  ui_story_5088_50880202_145_dialog_content = "Kamu dan yang lainnya pantas mendapatkannya.",
  ui_story_5088_50880202_146_dialog_content = "...",
  ui_story_5088_50880202_147_dialog_content = "<color=#e8d9bb>Segera setelah Anthony pergi, Claymore menggunakan seperangkat alat sederhana untuk membuat sejumlah lambang baru.</color>",
  ui_story_5088_50880202_148_dialog_content = "<color=#e8d9bb>Setelah hati-hati mengukir gambar gulungan pada salah satunya, dia dengan hati-hati menaruhnya di dalam buku catatannya.</color>",
  ui_story_5088_50880202_149_dialog_content = "Ludweiss, mari kita tunggu bersama melelehnya salju dan kedatangan musim semi.",
  ui_story_5088_50880301_1_dialog_content = "Jadi, lambang ini dibuat untuk Miss Ludweiss...",
  ui_story_5088_50880301_2_dialog_content = "Dan seperti dalam mimpi Adras, Claymore, atau lebih tepatnya Achilles, dulunya adalah orang yang baik dan jujur.",
  ui_story_5088_50880301_3_dialog_content = "Tapi Claymore yang baru saja kita lihat adalah makhluk yang sangat ganas. Apa yang mungkin terjadi antara waktu itu dan sekarang?",
  ui_story_5088_50880301_4_dialog_content = "(Bukan hanya itu... Adras dan kawan-kawannya adalah orang-orang yang membunuh kapten mereka dengan tangan mereka sendiri.)",
  ui_story_5088_50880301_5_dialog_content = "Kau baik-baik saja?",
  ui_story_5088_50880301_6_dialog_content = "Sejak hari itu, wajahmu tampak sangat khawatir.",
  ui_story_5088_50880301_7_dialog_content = "Apakah ada sesuatu tentang mimpiku yang mengganggumu?",
  ui_story_5088_50880301_8_dialog_content = "Jika memang begitu, selalu baik untuk memberitahu orang lain tentang itu. Jangan simpan semuanya sendiri, oke?",
  ui_story_5088_50880301_9_dialog_content = "Apakah kalian masih ingat saat kita kembali ke gua beku itu?",
  ui_story_5088_50880301_10_dialog_content = "Kalian semua tampaknya sangat akrab dengan tempat itu...",
  ui_story_5088_50880301_11_dialog_content = "Itu karena kami pergi ke sana dalam sebuah misi yang sangat lama sekali.",
  ui_story_5088_50880301_12_dialog_content = "Kami tidak bisa mengingat detail spesifik apa pun, meskipun begitu. Mungkin ini efek samping dari disegel begitu lama...",
  ui_story_5088_50880301_13_dialog_content = "Tapi yang aku ingat adalah ada sesuatu yang jelas salah dengan pria itu selama misi kita...",
  ui_story_5088_50880301_14_dialog_content = "Ugh... Tidak ada gunanya, aku tidak bisa mengingat apa pun lagi... Tapi bertahun-tahun kemudian, itulah tempat kamu menemukan kami...",
  ui_story_5088_50880301_15_dialog_content = "Ini membuktikan bahwa dia mengkhianati kita.",
  ui_story_5088_50880301_16_dialog_content = "Tapi saat kami bangun, tempat itu sangat berbeda dari saat kami pertama kali memasukinya.",
  ui_story_5088_50880301_17_dialog_content = "Kurasa dua ribu tahun bisa benar-benar mengubah suatu tempat, bukan?",
  ui_story_5088_50880301_18_dialog_content = "Aku... Aku hanya pergi ke gua itu di bawah bimbingan Queen Bethlehem.",
  ui_story_5088_50880301_19_dialog_content = "Beberapa waktu lalu, saya menyelamatkan seorang Aurorian yang telah membeku di dalam es. Sejak awal, saya berpikir...",
  ui_story_5088_50880301_20_dialog_content = "Bethlehem...?",
  ui_story_5088_50880301_21_dialog_content = "...Hah?",
  ui_story_5088_50880301_22_dialog_content = "(Saya sudah kehabisan petunjuk. Apa yang harus saya lakukan sekarang?)",
  ui_story_5088_50880301_23_dialog_content = "(Jika saya menggabungkan semua yang baru saja saya lihat dengan apa yang saya lihat dalam mimpi, itu membuktikan bahwa Claymore adalah orang yang menyegel setiap orang di arena sebelum membawa mereka ke gua beku.)",
  ui_story_5088_50880301_24_dialog_content = "(Tapi ketika mereka akhirnya bangun, ingatan mereka benar-benar kacau, dan mereka akhirnya membunuh Claymore tanpa menyadarinya...)",
  ui_story_5088_50880301_25_dialog_content = "(Jika ini benar-benar kebenaran... Hampir terlalu menyakitkan untuk ditanggung...)",
  ui_story_5088_50880301_26_dialog_content = "Maaf, tapi ada tempat yang ingin saya kunjungi.",
  ui_story_5088_50880301_27_dialog_content = "Bukankah aku sudah bilang cukup banyak kali, sayangku? Mustahil bagi saya untuk mengetahui sejarah lengkap dari setiap objek ini.",
  ui_story_5088_50880301_28_dialog_content = "Belum lagi banyak dari barang-barang ini adalah hasil rampasan dari hari-hari awal senior Istvan.",
  ui_story_5088_50880301_29_dialog_content = "Dulu, Umbraton adalah sarang kejahatan dan kekacauan. Hampir segala sesuatu di kota itu berasal dari asal-usul yang meragukan pada dasarnya.",
  ui_story_5088_50880301_30_dialog_content = "Aku adalah satu-satunya yang juga bersedia menjaga benda-benda ini.",
  ui_story_5088_50880301_31_dialog_content = "Tapi ini sangat penting bagiku...",
  ui_story_5088_50880301_32_dialog_content = "Oh jangan cemberut seperti itu, Sayang! Sungguh menyakitkan melihatmu begitu putus asa! Ah, jika saja Vergil di sini untuk menyelesaikan semuanya.",
  ui_story_5088_50880301_33_dialog_content = "Bagaimana kalau ini?",
  ui_story_5088_50880301_34_dialog_content = "Sudah larut, jadi mengapa saya tidak menjual semua gulungan dan catatan tulisan tangan di sini sekaligus kepada kamu?",
  ui_story_5088_50880301_35_dialog_content = "Dengan cara itu, kamu bisa membawa semuanya pulang dan menelitinya dengan kecepatanmu sendiri. Saya bahkan akan memberikan diskon keluarga, hanya untuk kamu! Jadi, apa kata kamu?",
  ui_story_5088_50880301_36_dialog_content = "O-Oke kalau begitu...",
  ui_story_5088_50880301_37_dialog_content = "Hei Caelestite... Kamu yakin ingin berjalan-jalan sendirian di Umbraton malam ini?",
  ui_story_5088_50880301_38_dialog_content = "Hei, lihat itu? Caelestite baru saja membeli banyak barang dari Cloudrover Guild.",
  ui_story_5088_50880301_39_dialog_content = "Aku tidak tahu. Merampok Caelestite terakhir bisa memiliki konsekuensi yang sangat serius. Apakah kamu memiliki ide seberapa menakutkan Lovegator itu?",
  ui_story_5088_50880301_40_dialog_content = "Ayo, ini tengah malam! Kita hanya perlu sedikit mengusiknya dan kabur dengan barang-barang sebelum ada yang menyadari!",
  ui_story_5088_50880301_41_dialog_content = "Kita bisa meninggalkan kota dan pergi ke tempat yang jauh, tempat di mana bahkan Shadowlord tidak bisa menemukan kita.",
  ui_story_5088_50880301_42_dialog_content = "Lihat saja ukuran kotak itu! Setelah kita melarikan diri, kita bisa hidup seperti raja sepanjang hidup kita!",
  ui_story_5088_50880301_43_dialog_content = "... Baiklah, tapi mari kita tunggu sampai dia sedikit lebih jauh dari Umbraton. Itulah saatnya kita akan bergerak.",
  ui_story_5088_50880301_44_dialog_content = "Siapa di sana?!",
  ui_story_5088_50880301_45_dialog_content = "Oh? Tampaknya benar bahwa Caelestite bisa merasakan kita.",
  ui_story_5088_50880301_46_dialog_content = "Kalau begitu, kita harus membuat langkah kita sekarang!",
  ui_story_5088_50880301_47_dialog_content = "T-Tunggu sebentar! Kamu tidak menginginkan semua barang ini! Ini hanya sekelompok tulisan dan gulungan kuno!",
  ui_story_5088_50880301_48_dialog_content = "Dengar itu? Bagi saya, terdengar seperti harta karun bersejarah!",
  ui_story_5088_50880301_49_dialog_content = "(Mereka sama sekali tidak mendengarkanku!)",
  ui_story_5088_50880301_50_dialog_content = "Pergilah, idiot.",
  ui_story_5088_50880301_51_dialog_content = "Hah?",
  ui_story_5088_50880301_52_dialog_content = "I-Itu dia! Pemburu Raven!",
  ui_story_5088_50880301_53_dialog_content = "Apa yang dia lakukan di sini?!",
  ui_story_5088_50880301_54_dialog_content = "Baiklah, kalian pengecut tak tahu malu... Saatnya kalian menerima hukuman!",
  ui_story_5088_50880302_1_dialog_content = "Eh... Terima kasih.",
  ui_story_5088_50880302_2_dialog_content = "Goblog sia!",
  ui_story_5088_50880302_3_dialog_content = "Hah?",
  ui_story_5088_50880302_4_dialog_content = "Kamu tahu betul bahwa kamu seorang Caelestite, jadi mengapa kamu tetap berkeliling tanpa perlindungan sama sekali?",
  ui_story_5088_50880302_5_dialog_content = "Meskipun kamu berada dalam hubungan baik dengan Shadowlord dan gengnya, itu bukan alasan untuk meremehkan bahaya Umbraton.",
  ui_story_5088_50880302_6_dialog_content = "Jangan biarkan saya memergoki Anda berjalan sendirian di jalan-jalan ini lagi.",
  ui_story_5088_50880302_7_dialog_content = "Tak bisa dipercaya. Ternyata kau malah berhasil menjadi korban perampokan.",
  ui_story_5088_50880302_8_dialog_content = "Semua Umbraton sedang ramai sekarang ini karena kamu.",
  ui_story_5088_50880302_9_dialog_content = "Ketika saya melihat bahwa kamu baik-baik saja, saya pikir ada kesalahan.",
  ui_story_5088_50880302_10_dialog_content = "Hah?",
  ui_story_5088_50880302_11_dialog_content = "Shadowlord dan orang-orangnya marah ketika mereka mengetahui hal itu, jadi mereka memburu orang-orang yang mencoba merampokmu.",
  ui_story_5088_50880302_12_dialog_content = "Tapi karena kamu baik-baik saja, saya rasa ini adalah kesempatan yang baik untuk menghilangkan lebih banyak sampah di sekitar sini.",
  ui_story_5088_50880302_13_dialog_content = "Ini, tanda simpati dari Lady Sheol. Dia sangat menekankan agar aku memberikan ini padamu.",
  ui_story_5088_50880302_14_dialog_content = "Terima kasih... Tapi sungguh, saya baik-baik saja. Ada yang datang menyelamatkan saya tepat pada waktunya.",
  ui_story_5088_50880302_15_dialog_content = "Aku dengar. Para penjahat yang merampokmu memberi tahu kami bahwa Pemburu Ravenlah yang menyelamatkanmu.",
  ui_story_5088_50880302_16_dialog_content = "Ya, itu juga yang mereka panggil dia... Pemburu Raven...",
  ui_story_5088_50880302_17_dialog_content = "Dia mulai muncul sekitar dua tahun lalu. Sesekali, dia memburu penjahat di tengah malam dan menghukum mereka.",
  ui_story_5088_50880302_18_dialog_content = "Seorang pengawal Umbraton yang hanya muncul di malam hari? Terdengar sangat mirip dengan Pittman dari masa lalu.",
  ui_story_5088_50880302_19_dialog_content = "Hati-hati dengan apa yang kamu katakan. Metode orang itu jauh lebih brutal.",
  ui_story_5088_50880302_20_dialog_content = "Kami berdua adalah burung gagak, tetapi satu hal yang tidak kami miliki bersama adalah dia tidak meninggalkan ujung yang longgar.",
  ui_story_5088_50880302_21_dialog_content = "Terlepas dari kejahatan mereka, dia mengalahkan mereka semua hingga hampir mati.",
  ui_story_5088_50880302_22_dialog_content = "Banyak orang mencurigai bahwa dia mungkin adalah Justice Knight yang nakal atau semacamnya.",
  ui_story_5088_50880302_23_dialog_content = "Paket untuk kamu, Pak Navigator! Tolong tanda tangani di sini.",
  ui_story_5088_50880302_24_dialog_content = "Terima kasih.",
  ui_story_5088_50880302_25_dialog_content = "Kamu bahkan membeli lebih banyak barang ini?",
  ui_story_5088_50880302_26_dialog_content = "Bukankah pada titik ini Anda hanya mencoba mencari jarum di tumpukan jerami?",
  ui_story_5088_50880302_27_dialog_content = "Aku tahu... Tapi ini semua yang bisa aku lakukan sekarang... Lagipula, mencari pengetahuan yang hilang dalam sejarah selalu menjadi tantangan.",
  ui_story_5088_50880302_28_dialog_content = "...",
  ui_story_5088_50880302_29_dialog_content = "(Hah?)",
  ui_story_5088_50880302_30_dialog_content = "Jadi Tweety, apakah kamu juga harus membuat pengiriman di sini?",
  ui_story_5088_50880302_31_dialog_content = "Memori yang payah, Tuan Navigator. Hampir Windelion, tahu!",
  ui_story_5088_50880302_32_dialog_content = "Aku datang untuk mengkonfirmasi surat Ewaveil!",
  ui_story_5088_50880302_33_dialog_content = "Eh, kamu benar! Aku benar-benar melupakan semuanya!",
  ui_story_5088_50880302_34_dialog_content = "Vice dan Carleen seharusnya kembali sebelum Windelion. Saya yakin Vice akan lebih dari senang untuk...",
  ui_story_5088_50880302_35_dialog_content = "Sekarang setelah saya telah mengantarkan hadiah Lady Sheol dan memastikan keamanan Anda, saya akan pergi.",
  ui_story_5088_50880302_36_dialog_content = "Kita juga harus berangkat! Sampai jumpa di sekitaw, Tuan Navigator!",
  ui_story_5088_50880302_37_dialog_content = "... Dah.",
  ui_story_5088_50880302_38_dialog_content = "Baiklah, sampai jumpa semua nanti!",
  ui_story_5088_50880302_39_dialog_content = "Tunggu, Casta—",
  ui_story_5088_50880302_40_dialog_content = "Saya tidak tahu apakah saya bisa mengatasinya membolak-balik setiap satu dari catatan-catatan ini.",
  ui_story_5088_50880302_41_dialog_content = "Pikirkan kamu bisa menggunakan keberuntungan luar biasamu untuk memberi tahu saya harus mulai dari mana?",
  ui_story_5088_50880302_42_dialog_content = "Ketika kerja keras tidak bisa menyelamatkanmu dan kamu tidak memiliki tempat lain untuk berpaling, itulah saatnya kamu bertepuk tangan dan berdoa untuk keberuntungan.",
  ui_story_5088_50880302_43_dialog_content = "Tapi kamu tidak bisa mengandalkan keberuntungan ketika kerja keras masih menjadi pilihan.",
  ui_story_5088_50880302_44_dialog_content = "Lagi pula, aku bisa menambahkannya ke daftar layanan yang telah kuberikan... Di sini, mulai dengan yang ini.",
  ui_story_5088_50880302_45_dialog_content = "Hah?",
  ui_story_5088_50880302_46_dialog_content = "Sepertinya teknik rahasia Anda gagal kali ini. Saya tidak merasakan apa-apa dari notebook ini.",
  ui_story_5088_50880302_47_dialog_content = "Aku mengandalkan lebih dari sekedar keberuntungan, kamu tahu.",
  ui_story_5088_50880302_48_dialog_content = "Mengapa kamu tidak mencoba sedikit lebih percaya pada dirimu sendiri?",
  ui_story_5088_50880302_49_dialog_content = "Kurasa kamu benar... Maaf, Casta, seharusnya aku tidak mencoba memanfaatkan keberuntungan baikmu seperti itu.",
  ui_story_5088_50880302_50_dialog_content = "H-hah?!",
  ui_story_5088_50880302_51_dialog_content = "Lihat sampul buku catatan ini... Itu adalah Boneka Windelion!",
  ui_story_5088_50880302_52_dialog_content = "Ini... Ini pasti milik seorang Caelestite!",
  ui_story_5088_50880302_53_dialog_content = "(Meski samar, buku catatan ini memancarkan panjang gelombang yang familiar seperti emblem-emblem itu. Ini mungkin saja buku catatan Miss Ludweiss...)",
  ui_story_5088_50880302_54_dialog_content = "Sepertinya kamu kembali berada di jalur yang benar. Sampai jumpa.",
  ui_story_5088_50880302_55_dialog_content = "(Tapi Nyonya Ludweiss tidak pernah kembali ke Eraveil selama hidupnya. Mungkin ada Caelestite pengembara lain seperti dia yang tahu cara membuat Boneka Windelion?)",
  ui_story_5088_50880302_56_dialog_content = "Tetap saja, tidak bisa dipungkiri ada perasaan familiar yang datang dari buku catatan ini... Kurasa aku tidak akan tahu sampai aku membukanya dan melihat...",
  ui_story_5088_50880401_1_dialog_content = "<color=#e8d9bb>Di tengah malam musim dingin yang dingin, sekelompok orang khusus berkumpul tepat di luar gua yang membeku.</color>",
  ui_story_5088_50880401_2_dialog_content = "<color=#e8d9bb>Dari dalam gua, tuan mereka yang terhormat dan menua berbicara kepada mereka tentang keberadaan yang harus mereka lindungi.</color>",
  ui_story_5088_50880401_3_dialog_content = "... Sang raja telah memenuhi janjinya, dan kedamaian telah dipulihkan. Sekarang, tidak ada kebutuhan bagi dunia untuk mengingat Prajurit Eclipsite, atau teknik augmentasi yang melahirkan mereka.",
  ui_story_5088_50880401_4_dialog_content = "Anak-anak yang diasingkan dari tanah ini menemukan suku baru untuk mereka sebut milik mereka sendiri. Bahkan, beberapa mengklaim bahwa mereka bahkan menemukan surga yang mengapung di langit.",
  ui_story_5088_50880401_5_dialog_content = "Kerabat Lady Freya telah membangun kembali kota perbatasan menjadi tempat yang indah dan megah. Gunung beku yang telah berdiri sejak zaman dahulu kala telah meleleh dan membentuk danau yang sebersih dan sehalus cermin.",
  ui_story_5088_50880401_6_dialog_content = "*batuk* Dan masih... Saya tidak pernah berhasil menemukan Eraveil.",
  ui_story_5088_50880401_7_dialog_content = "Meskipun hidupku telah berlangsung bertahun-tahun, saya gagal membawa teman baik kita Ludweiss kembali ke rumahnya dan meletakkannya untuk beristirahat.",
  ui_story_5088_50880401_8_dialog_content = "... Itu bukan salahmu, Anthony.",
  ui_story_5088_50880401_9_dialog_content = "Aku telah menjadi tua, Lord Achilles... Kematian mengancam untuk membawaku kapan saja.",
  ui_story_5088_50880401_10_dialog_content = "Tapi, sebelum itu terjadi, aku memiliki lebih banyak hal untuk dikatakan kepada kamu. Itulah mengapa aku meminta anak-anakku untuk membawaku ke sini hari ini.",
  ui_story_5088_50880401_11_dialog_content = "Saya ingin menyampaikan penyesalan saya, Lord. Dengan gagal menyelesaikan misi yang Anda berikan, saya telah mengecewakan Anda sebagai penjaga Anda... Dan meski saya adalah tentara Anda, saya tidak memiliki cara untuk mati di sisi Anda dalam pertempuran.",
  ui_story_5088_50880401_12_dialog_content = "Saya percaya diri saya setia, dan namun saya tidak melakukan apa-apa selain mengecewakan Anda... dan bahkan di akhir, saya harus menutup mata saya di depan Anda.",
  ui_story_5088_50880401_13_dialog_content = "Angkat kepalamu, Anthony. Saya tidak menyalahkanmu, hanya rasa bangga dan terima kasih yang paling dalam.",
  ui_story_5088_50880401_14_dialog_content = "Kamu sudah melakukan lebih dari cukup untuk kami, teman ku.",
  ui_story_5088_50880401_15_dialog_content = "Tidak... Anda pantas mendapatkan yang jauh lebih baik dari ini, tuanku! Anda sudah kehilangan begitu banyak orang... Anda pasti berpikir saya kejam karena membiarkan Anda melihat saya dalam keadaan tua dan sekarat.",
  ui_story_5088_50880401_16_dialog_content = "Tapi aku khawatir jika aku tidak datang, kamu akan khawatir tanpa alasan untukku.",
  ui_story_5088_50880401_17_dialog_content = "Sebagai penjagamu... Hanya benar jika saya mati sebelum Anda. Jika saya tidak tahu tentang beban besar Anda, saya akan bermimpi untuk bertarung di sisi Anda lagi suatu hari nanti.",
  ui_story_5088_50880401_18_dialog_content = "Jenderal ku, pahlawan kerajaan... Kamu telah menelan kegelapan, namun aku adalah satu-satunya yang menjadi saksi cahaya mu.",
  ui_story_5088_50880401_19_dialog_content = "Keturunanku akan menjadi orang yang tetap berada di sisimu mulai sekarang... Tapi hanya sedikit yang akan mengingat kehebatan pencapaianmu.",
  ui_story_5088_50880401_20_dialog_content = "Tenang saja, Anthony.",
  ui_story_5088_50880401_21_dialog_content = "Meski sejarah melupakan kita, aku tak akan pernah meninggalkan tujuanku. Aku telah berjanji pada kawan-kawanku bahwa aku akan menanggung semuanya.",
  ui_story_5088_50880401_22_dialog_content = "Jadi lepaskan penyesalanmu dan istirahatlah, teman yang lelah. Kau lebih dari layak mendapatkannya.",
  ui_story_5088_50880401_23_dialog_content = "Ah... Pengampunanmu berarti lebih dari yang pernah kamu ketahui, tuanku.",
  ui_story_5088_50880401_24_dialog_content = "Tapi bagaimana dengan Ludweiss? Aku belum bisa memejamkan mataku. Aku tidak bisa...",
  ui_story_5088_50880401_25_dialog_content = "Kamu menyelamatkan aku, namun aku gagal padamu, Lord Achilles. Aku juga gagal pada Dominic.",
  ui_story_5088_50880401_26_dialog_content = "Lihat kembali kehidupanmu, Anthony.",
  ui_story_5088_50880401_27_dialog_content = "Kamu selalu melindungi yang lemah dan tak berdaya, serta menjaga kehormatan kita. Kamu telah menanam benih cinta dan kesetiaan, dan membesarkan anak-anak dan cucu-cucumu dengan bangga.",
  ui_story_5088_50880401_28_dialog_content = "Anda mengorbankan kekayaan dan kejayaan demi menepati janji Anda. Tidak ada jiwa yang lebih bersinar dari Anda, teman saya.",
  ui_story_5088_50880401_29_dialog_content = "Tidak ada bagian dari hidupmu yang dihabiskan sia-sia. Kamu telah menghormati keinginan mereka yang mengorbankan diri mereka sendiri... Dan juga keinginan saya sendiri.",
  ui_story_5088_50880401_30_dialog_content = "Namun…",
  ui_story_5088_50880401_31_dialog_content = "Tetap tenang, Anthony. Kamu telah mendapatkan tempatmu di surga prajurit.",
  ui_story_5088_50880401_32_dialog_content = "Dan jika pintu itu tertutup untukmu, aku akan ada di sana untuk membukanya dengan pedangku.",
  ui_story_5088_50880401_33_dialog_content = "Jadi jangan khawatir... Ludweiss dan aku akan tetap berada di dunia ini, menunggu fajar masa depan yang pernah dia lihat.",
  ui_story_5088_50880401_34_dialog_content = "Jadi, biarkan momen terakhirmu dipenuhi dengan harapan, teman saya.",
  ui_story_5088_50880401_35_dialog_content = "Tuhan Achilles...",
  ui_story_5088_50880401_36_dialog_content = "Kamu ingin tahu kenapa aku sampai sejauh ini untuk mereka?",
  ui_story_5088_50880401_37_dialog_content = "Kamu juga melakukan hal yang sama, bukan? Menurutku, tidak ada perbedaan antara kita.",
  ui_story_5088_50880401_38_dialog_content = "Sebagai penjaga setia Lord Achilles, aku memiliki kewajiban untuk menjalankan.",
  ui_story_5088_50880401_39_dialog_content = "Tapi, aku tidak yakin apakah hal-hal benar-benar bisa berubah...",
  ui_story_5088_50880401_40_dialog_content = "Hei, Anthony... Jika kamu bertanya padaku, itulah yang disebut harapan: sebuah obor yang menyala di malam tergelap.",
  ui_story_5088_50880401_41_dialog_content = "Aku tahu aku akan kelelahan...",
  ui_story_5088_50880401_42_dialog_content = "Tapi jalan yang telah kubentuk akan membimbing orang lain keluar dari kegelapan.",
  ui_story_5088_50880401_43_dialog_content = "Mulai sekarang, mereka yang mengikuti jalan ini tidak perlu lagi takut tersesat.",
  ui_story_5088_50880401_44_dialog_content = "Bintang-bintang bersinar turun pada kita semua. Kamu, aku, dan tak terhitung orang lain yang menderita di dunia kita.",
  ui_story_5088_50880401_45_dialog_content = "Apakah kamu benar-benar berpikir mereka bisa melihat lapisan perak sebelum mereka mulai?",
  ui_story_5088_50880401_46_dialog_content = "Kamu mengatakan...",
  ui_story_5088_50880401_47_dialog_content = "Lihat di belakangmu, Anthony.",
  ui_story_5088_50880401_48_dialog_content = "Anda sudah menerangi jalan bagi begitu banyak orang.",
  ui_story_5088_50880401_49_dialog_content = "Mungkin bukan sekarang, tetapi perubahan itu pasti akan terjadi di masa depan, dan semua berkat apa yang telah kamu lakukan dalam hidup.",
  ui_story_5088_50880401_50_dialog_content = "Percayalah pada masa depan. Kamu telah melakukan banyak hal untuk semua orang, tetapi sekarang giliranmu untuk beristirahat.",
  ui_story_5088_50880401_51_dialog_content = "Apakah aku... benar-benar pantas mendapatkan ini?",
  ui_story_5088_50880401_52_dialog_content = "Heh, apakah kamu benar-benar harus bertanya?",
  ui_story_5088_50880401_53_dialog_content = "Anthony Longinus... Saya merasa terhormat telah menyaksikan momen di mana nyala jiwa bangga dan mulia Anda padam. Selamat berjuang menuju surga prajurit, teman saya.",
  ui_story_5088_50880401_54_dialog_content = "Kamu pantas mendapatkan semuanya.",
  ui_story_5088_50880401_55_dialog_content = "Kakek tersenyum saat dia meninggal.",
  ui_story_5088_50880401_56_dialog_content = "...",
  ui_story_5088_50880401_57_dialog_content = "Sebagai penggantinya, saya merasa terhormat untuk memasuki gua ini dan melayani Anda, Tuanku Achilles.",
  ui_story_5088_50880401_58_dialog_content = "Kemudian, ambil emblem ini dan kenakanlah dengan bangga.",
  ui_story_5088_50880401_59_dialog_content = "Saya persembahkan ini kepada dia dan kepada kamu, keturunan bangsawan-nya.",
  ui_story_5088_50880401_60_dialog_content = "T-Tapi tuanku, lambang ini... Ini jauh terlalu berharga untuk kami terima.",
  ui_story_5088_50880401_61_dialog_content = "Anthony adalah rekan seperjuanganku, sekaligus teman sejati. Dia mendapatkan rasa hormatku, dan oleh karena itu aku memberikan hal yang sama kepada kamu.",
  ui_story_5088_50880401_62_dialog_content = "Saya hanya berharap bahwa kekuatan dari emblem ini akan berguna bagi keluarga Anda.",
  ui_story_5088_50880401_63_dialog_content = "Bawa dia pulang. Kakekmu telah menjalani hidup yang penuh dan bermakna, dan layak untuk diberi istirahat dengan air mata dan berkat dari keluarganya.",
  ui_story_5088_50880401_64_dialog_content = "A-Aku mengerti, Lord Achilles. Jika Anda memaafkan kami...",
  ui_story_5088_50880401_65_dialog_content = "Teman-temanku... Aku juga ingin istirahatkan mataku sebentar...",
  ui_story_5088_50880401_66_dialog_content = "...",
  ui_story_5088_50880401_67_dialog_content = "Tolong... Kunjungi aku dalam mimpi dan temani aku sekali lagi.",
  ui_story_5088_50880401_68_dialog_content = "<color=#e8d9bb>Dan begitulah awal mimpinya yang sepi dan tak berujung.</color>",
  ui_story_5088_50880401_69_dialog_content = "<color=#e8d9bb>Tapi dia akan menyimpang dari dunianya sekali lagi ketika dia terbangun dari tidurnya.</color>",
  ui_story_5088_50880401_70_dialog_content = "Maaf... Tapi apakah kamu tahu cara masuk ke Eraveil?",
  ui_story_5088_50880401_71_dialog_content = "Kami telah mencari tempat itu selama bertahun-tahun dan diberitahu bahwa pintu masuknya ada di dekat sini.",
  ui_story_5088_50880401_72_dialog_content = "Hah? Kenapa kamu pergi ke Eraveil?",
  ui_story_5088_50880401_73_dialog_content = "... Kami memiliki janji untuk ditepati.",
  ui_story_5088_50880401_74_dialog_content = "Maafkan saya karena terlalu langsung, tapi kamu sangat mirip dengan Caelestite yang disebutkan dalam legenda keluarga kami.",
  ui_story_5088_50880401_75_dialog_content = "Oh, apakah begitu? Nah, kamu beruntung karena kebetulan aku...",
  ui_story_5088_50880401_76_dialog_content = "<color=#FFB400>Peningkatan Kekuatan!</color>",
  ui_story_5088_50880401_77_dialog_content = "Baiklah kalian orang asing yang aneh, mari kita lihat apa jenis pikiran jahat yang ada di kepala kalian...",
  ui_story_5088_50880401_78_dialog_content = "Anda sudah bangun, Tuan Achilles!",
  ui_story_5088_50880401_79_dialog_content = "Apakah kamu... cucu Anthony?",
  ui_story_5088_50880401_80_dialog_content = "Tidak, Tuanku. Sudah banyak, banyak zaman sejak zaman leluhur kita.",
  ui_story_5088_50880401_81_dialog_content = "?!",
  ui_story_5088_50880401_82_dialog_content = "Ingatanku telah hancur lagi... Berapa banyak yang aku hilangkan kali ini?",
  ui_story_5088_50880401_83_dialog_content = "... Jangan sedih, ya, Tuan Achilles.",
  ui_story_5088_50880401_84_dialog_content = "Kami datang membawa kabar baik.",
  ui_story_5088_50880401_85_dialog_content = "Oh... Mereka memang mengatakan yang sebenarnya.",
  ui_story_5088_50880401_86_dialog_content = "Jadi kamu adalah Claymore, ya?",
  ui_story_5088_50880401_87_dialog_content = "Saya harus meminta Anda untuk memanggil Lord Achilles dengan cara yang lebih tepat, Tuan Czerny.",
  ui_story_5088_50880401_88_dialog_content = "Sungguh? Karena menurutku Claymore terdengar jauh lebih keren.",
  ui_story_5088_50880401_89_dialog_content = "Apakah... Apakah kamu...?",
  ui_story_5088_50880401_90_dialog_content = "Pakaianmu... wajahmu...",
  ui_story_5088_50880401_91_dialog_content = "Apakah kamu salah satu dari orang-orang Ludweiss?",
  ui_story_5088_50880401_92_dialog_content = "Maaf, tapi saya tidak kenal Ludweiss. Orang-orang kami tidak terlalu suka berlarian di dunia luar, tahu?",
  ui_story_5088_50880401_93_dialog_content = "Dia pernah berkata... Keluarganya meninggalkan Eraveil sudah lama, jadi dia menghabiskan seluruh hidupnya mencari tempat itu lagi.",
  ui_story_5088_50880401_94_dialog_content = "Bisakah kalian berdua... memberitahu saya namamu?",
  ui_story_5088_50880401_95_dialog_content = "Aku akan berusaha keras untuk mengingat.",
  ui_story_5088_50880401_96_dialog_content = "Saya merasa terhormat, Tuanku... Saya adalah Dominic Longinus, dan saya tinggal di sebuah pulau yang saat ini dikenal sebagai Azurite.",
  ui_story_5088_50880401_97_dialog_content = "Dominic... Mendengar nama itu membuatku merasa nostalgia.",
  ui_story_5088_50880401_98_dialog_content = "Tuan Anthony berharap bahwa, di usia berapapun, kehadiran yang akrab akan ada untuk menyapa kamu saat kamu terbangun.",
  ui_story_5088_50880401_99_dialog_content = "Maaf jika aku terdengar kasar tadi. Namaku Czerny, dan aku menemukan temanmu ini berkeliaran di Eraveil, jadi aku sedikit mengintip pikirannya.",
  ui_story_5088_50880401_100_dialog_content = "Aku melihat seluruh ceritamu, dan aku harus bilang... Itu luar biasa!",
  ui_story_5088_50880401_101_dialog_content = "Terutama persahabatanmu dengan gadis Caelestite itu! Seluruh hal itu mengguncangku sampai ke inti hatiku!",
  ui_story_5088_50880401_102_dialog_content = "Jadi, aku tidak hanya akan membawa Ludweiss kembali ke Eraveil untuk diberikan peristirahatan terakhir, tapi aku juga akan menyelamatkan kalian semua!",
  ui_story_5088_50880401_103_dialog_content = "Sekarang, di mana segel itu? Apakah ada Caelestite yang bisa membukanya?",
  ui_story_5088_50880401_104_dialog_content = "... Tolong jangan lepaskan mereka sekarang.",
  ui_story_5088_50880401_105_dialog_content = "Ini belum waktunya mereka.",
  ui_story_5088_50880401_106_dialog_content = "Hah?",
  ui_story_5088_50880401_107_dialog_content = "... Ludweiss menyegel mereka untuk mencegah korupsi dalam tubuh mereka menyebar ke pikiran mereka.",
  ui_story_5088_50880401_108_dialog_content = "Dia ingin memberikan mereka istirahat yang sangat dibutuhkan dari penderitaan mereka.",
  ui_story_5088_50880401_109_dialog_content = "Hanya ketika tubuh mereka telah sepenuhnya berubah, barulah ada harapan untuk mempertahankan kesadaran mereka.",
  ui_story_5088_50880401_110_dialog_content = "Saya juga telah menyuntikkan sihir tanpa warna ke dalam segel mereka semua. Setelah tubuh mereka dibebaskan, saya ingin membebaskan emosi mereka yang terkunci juga.",
  ui_story_5088_50880401_111_dialog_content = "Aku tidak benar-benar mengerti... Tapi tak apa. Itu memang keputusanmu, setelah semua.",
  ui_story_5088_50880401_112_dialog_content = "Kamu juga sudah lama melawan korupsi itu, 'kan?",
  ui_story_5088_50880401_113_dialog_content = "Aku akan membantumu menemukan jalan keluar dari kekacauan ini... Dan jika itu tidak berhasil, aku juga bisa menyegelmu.",
  ui_story_5088_50880401_114_dialog_content = "Benarkah itu mungkin?",
  ui_story_5088_50880401_115_dialog_content = "Tidak ada salahnya mencoba, bukan?",
  ui_story_5088_50880401_116_dialog_content = "Kita bisa mencari tahu cara menyelamatkanmu terlebih dahulu, lalu kita bisa membawa Ludweiss kembali dan meletakkannya untuk beristirahat.",
  ui_story_5088_50880401_117_dialog_content = "... Aku tidak bisa disegel seperti yang lainnya. Jika aku masuk ke dalam keadaan tidak sadar yang serupa, tidak akan ada orang yang tersisa untuk menjaga segel mereka.",
  ui_story_5088_50880401_118_dialog_content = "Aku menghargai tawaran baikmu, tapi aku memiliki tugas untuk menjaga formasi ini dan memastikan bahwa teman-temanku tetap tersegel.",
  ui_story_5088_50880401_119_dialog_content = "Ah... Itu juga tidak masalah! Kita punya banyak waktu! Aku akan tetap di sini dan mencoba beberapa hal. Silakan pulang kapan saja kamu mau, Dominic.",
  ui_story_5088_50880401_120_dialog_content = "Jika Anda membutuhkan sesuatu, Tuan Czerny, Anda hanya perlu bertanya. Keluarga kami lebih dari bersedia untuk membantu Anda.",
  ui_story_5088_50880401_121_dialog_content = "Czerny... Apakah kamu benar-benar melakukan perjalanan kemari dari Eraveil hanya karena tergerak oleh cerita kami?",
  ui_story_5088_50880401_122_dialog_content = "Tentu saja! Tapi, aku juga ingin membuktikan sesuatu kepada diriku sendiri.",
  ui_story_5088_50880401_123_dialog_content = "Aku ingin membuktikan... bahwa aku bukan orang lemah.",
  ui_story_5088_50880401_124_dialog_content = "Saya ingin mereka semua tahu bahwa saya juga mampu melakukan hal-hal besar. Ketika semua ini berakhir, saya yakin setiap orang akhirnya akan menghargai saya sebagai pahlawan!",
  ui_story_5088_50880401_125_dialog_content = "Dan kemudian, mereka tidak akan punya pilihan selain memilihku sebagai Colossus'... Ah, tapi itu bukan masalahnya.",
  ui_story_5088_50880401_126_dialog_content = "Siapa saja yang menyelamatkan seorang pahlawan juga bisa disebut pahlawan, bukan?",
  ui_story_5088_50880401_127_dialog_content = "Bagus memiliki ambisi, Czerny. Terlepas dari alasan Anda berada di sini, saya berterima kasih Anda datang.",
  ui_story_5088_50880401_128_dialog_content = "Tapi, kebesaran seseorang tidak hanya berasal dari pencapaian mereka.",
  ui_story_5088_50880401_129_dialog_content = "Saya harap kamu ingat apa yang kamu inginkan pada awalnya.",
  ui_story_5088_50880401_130_dialog_content = "Ya, tentu saja, saya mendengarmu. Serahkan saja padaku!",
  ui_story_5088_50880401_131_dialog_content = "Nah, sebaiknya aku mulai dari mana, ya...",
  ui_story_5088_50880401_132_dialog_content = "Tidak ada kebutuhan bagi kamu untuk melakukan ini, Czerny. Sudah cukup banyak orang yang mengorbankan diri mereka demi kita.",
  ui_story_5088_50880401_133_dialog_content = "Jadi tolong, bawa saja Ludweiss kembali ke Eraveil.",
  ui_story_5088_50880401_134_dialog_content = "Saya akan sangat berterima kasih kepada Anda karena melakukan itu sendiri.",
  ui_story_5088_50880401_135_dialog_content = "<color=#FFB400>Peningkatan Kekuatan!</color>",
  ui_story_5088_50880402_1_dialog_content = "... Ini akan lebih rumit dari yang kukira.",
  ui_story_5088_50880402_2_dialog_content = "Saya tidak meragukan hal itu.",
  ui_story_5088_50880402_3_dialog_content = "Tapi jangan khawatir, aku akan menemukan caranya!",
  ui_story_5088_50880402_4_dialog_content = "Selain itu, kamu bisa menggunakan perusahaan ini, bukan begitu?",
  ui_story_5088_50880402_5_dialog_content = "Dominic bisa mengurus semua makanan dan air yang aku butuhkan, jadi jangan khawatir tentangku.",
  ui_story_5088_50880402_6_dialog_content = "Haha, ini juga petualangan baru dan menarik bagi saya, kamu tahu!",
  ui_story_5088_50880402_7_dialog_content = "... Dalam hal ini, kamu bisa tinggal bersama kawan-kawan lainnya.",
  ui_story_5088_50880402_8_dialog_content = "Tapi tidak peduli apa yang mungkin kamu dengar di malam hari, kamu tidak bisa meninggalkan tempat itu. Mengerti?",
  ui_story_5088_50880402_9_dialog_content = "Oh? Ini mulai terdengar jauh lebih berbahaya sekarang!",
  ui_story_5088_50880402_10_dialog_content = "Cahayaku telah lama terkuras. Tidak ada yang bisa mengatakan berapa lama lagi aku bisa bertahan.",
  ui_story_5088_50880402_11_dialog_content = "Apakah kamu melihat tanda-tanda itu di dinding? Itu adalah hasil kerja tanganku.",
  ui_story_5088_50880402_12_dialog_content = "Tapi jika kamu tetap dekat dengan mereka, aku tidak akan mendekatimu.",
  ui_story_5088_50880402_13_dialog_content = "...",
  ui_story_5088_50880402_14_dialog_content = "Humph, cobaan bagus, tapi kau tidak akan bisa mengusirku. Karena aku sudah menerima tugas ini, aku akan melakukannya dengan baik. Tunggu dan lihat saja!",
  ui_story_5088_50880402_15_dialog_content = "Aku kehabisan petunjuk lagi... Apa yang terjadi selanjutnya, ya? Dan siapa sebenarnya pria ini, Czerny?",
  ui_story_5088_50880402_16_dialog_content = "(Dia tampaknya tidak terlalu bisa dipercaya. Apakah ini benar-benar baik-baik saja?)",
  ui_story_5088_50880402_17_dialog_content = "Huh... Aku harus menulis ke Jeriah.",
  ui_story_5088_50880402_18_dialog_content = "(Dia adalah ahli sejarah. Mungkin dia tahu lebih banyak tentang Star Warriors?)",
  ui_story_5088_50880402_19_dialog_content = "Apa... Hidungku berdarah?",
  ui_story_5088_50880402_20_dialog_content = "(Apakah aku telah menggunakan kekuatanku terlalu banyak belakangan ini?)",
  ui_story_5088_50880402_21_dialog_content = "Ini tidak baik... Aku tidak bisa membiarkan siapa pun melihatku seperti ini...",
  ui_story_5088_50880402_22_dialog_content = "Jadi ini juga tidak akan berhasil, ya? Bertanya-tanya apa yang salah kali ini...",
  ui_story_5088_50880402_23_dialog_content = "Aku tidak bermaksud menyalahkanmu, Czerny, tetapi... tolong jangan buang waktu lagi untuk ini.",
  ui_story_5088_50880402_24_dialog_content = "Ini tidak sebanding dengan waktunya, kamu masih muda.",
  ui_story_5088_50880402_25_dialog_content = "Tidak mungkin! Bahkan, itulah alasan tepat mengapa aku tidak bisa menyerah sekarang!",
  ui_story_5088_50880402_26_dialog_content = "Kamu mungkin tidak tahu ini, tetapi kaumku telah menjadi lengah sejak Eraveil memutuskan untuk mundur dari perang.",
  ui_story_5088_50880402_27_dialog_content = "Untuk menemukan kedamaian dan ketenangan dengan mundur dari dunia... Atau begitu kami katakan. Kenyataannya, kami hanya bersembunyi dalam gelembung kecil kami sendiri.",
  ui_story_5088_50880402_28_dialog_content = "Namun begitu, kita masih terjebak dalam berbagai jenis konflik.",
  ui_story_5088_50880402_29_dialog_content = "Saya akan membuktikan kepada semua orang bahwa saya bisa melakukannya. Saya memiliki apa yang dibutuhkan.",
  ui_story_5088_50880402_30_dialog_content = "...",
  ui_story_5088_50880402_31_dialog_content = "Aku tidak akan kemana-mana dengan tetap di rumah. Daripada terjebak di tanah selamanya, lebih baik aku mencoba dan melihat seberapa tinggi aku bisa terbang.",
  ui_story_5088_50880402_32_dialog_content = "Masih ada waktu, jadi tolong percayalah padaku! Saya berjanji akan menemukan cara untuk menyegel Anda atau mencegah korupsi mengambil alih pikiran Anda.",
  ui_story_5088_50880402_33_dialog_content = "Aku hanya butuh beberapa hari untuk istirahat... Hanya beberapa hari saja...",
  ui_story_5088_50880402_34_dialog_content = "... Maaf, Czerny, tapi waktuku hampir habis.",
  ui_story_5088_50880402_35_dialog_content = "Saya sudah membaca setiap jurnal Ludweiss satu per satu.",
  ui_story_5088_50880402_36_dialog_content = "Tapi selain cerita dan partitur musik, tidak ada yang bisa membantuku.",
  ui_story_5088_50880402_37_dialog_content = "Saya sudah pergi begitu lama... Saya bertanya-tanya berapa kali saya bisa dipilih sebagai pilot sampai sekarang...",
  ui_story_5088_50880402_38_dialog_content = "Sial!",
  ui_story_5088_50880402_39_dialog_content = "Aku tidak berpikir bahwa kertas musik itu tidak berguna.",
  ui_story_5088_50880402_40_dialog_content = "Jadi, kamu dengar, ya? Tapi aku di luar sini.",
  ui_story_5088_50880402_41_dialog_content = "Czerny, di dunia kejam dan tak kenal ampun saya, kata-kata kebencian mudah diucapkan, tetapi sedikit yang bisa mempertahankan kebaikan mereka di tengah rasa sakit.",
  ui_story_5088_50880402_42_dialog_content = "Musik itu, yang berasal dari hati, adalah bukti kemuliaan orang-orang di dunia ini.",
  ui_story_5088_50880402_43_dialog_content = "Banyak tahun yang lalu, saya memiliki keistimewaan untuk mendengarkan salah satu lagu Ludweiss. Itu adalah melodi yang elegan dan penuh belas kasih, sehalus dan selembut sinar bulan.",
  ui_story_5088_50880402_44_dialog_content = "Bisakah kamu... masuk ke dalam mimpiku dan membantu saya mengingat musiknya sekali lagi?",
  ui_story_5088_50880402_45_dialog_content = "Malam ini gelap dan tempat ini sangat dingin. Saya pikir kita berdua bisa menggunakan cahaya redup bulan.",
  ui_story_5088_50880402_46_dialog_content = "... Sekarang bahwa cahayamu telah ditelan, satu-satunya yang tersisa adalah kegelapan yang terus merusakmu dari dalam.",
  ui_story_5088_50880402_47_dialog_content = "Meski sebagai Caelestite, saya tidak bisa mengetahui warnanya. Maaf, tapi pikiranmu terlalu berbahaya untuk saya masuki sekarang.",
  ui_story_5088_50880402_48_dialog_content = "Saya tidak memiliki cara untuk mencari dengan aman di kesadaranmu untuk cara memisahkanmu dari kegelapan itu. Itulah sebabnya ini memakan waktu begitu lama untukku.",
  ui_story_5088_50880402_49_dialog_content = "Tapi tolong, beri aku sedikit lebih banyak waktu...",
  ui_story_5088_50880402_50_dialog_content = "Baiklah... Setelah beristirahat sehari, aku seharusnya bisa melanjutkan pencarian melalui kenangan-kenangan itu...",
  ui_story_5088_50880402_51_dialog_content = "(Saya pikir firasat saya benar. Seseorang sengaja menyebar catatan-catatan ini di seluruh Astra.)",
  ui_story_5088_50880402_52_dialog_content = "(Meskipun tulisannya hampir sepenuhnya tidak terbaca, halaman-halaman ini masih begitu penuh dengan sejarah. Seolah-olah siapapun yang melakukan ini tidak tega untuk menghancurkan catatan-catatan ini.)",
  ui_story_5088_50880402_53_dialog_content = "(Seolah-olah... Mereka menunggu seorang Caelestite untuk merasakan keberadaan mereka suatu hari nanti.)",
  ui_story_5088_50880402_54_dialog_content = "... Pokoknya, saatnya bekerja.",
  ui_story_5088_50880402_55_dialog_content = "Bagaimana ini bisa terjadi? Saya berlatih selama lebih dari satu dekade hanya untuk bisa mengemudikan Colossus.",
  ui_story_5088_50880402_56_dialog_content = "Jadi, mengapa aku begitu tidak berguna saat datang untuk membantu Claymore?",
  ui_story_5088_50880402_57_dialog_content = "Mestinya tidak seperti ini... Mestinya tidak...",
  ui_story_5088_50880402_58_dialog_content = "Saya sudah di sini begitu lama. Saya tidak mungkin pulang dengan tangan kosong.",
  ui_story_5088_50880402_59_dialog_content = "Czerny...",
  ui_story_5088_50880402_60_dialog_content = "B-Beri aku sedikit waktu untuk istirahat. Aku telah menggunakan kekuatan psikisku selama ini sampai-sampai rasanya kepala ini akan pecah.",
  ui_story_5088_50880402_61_dialog_content = "Lari, Czerny.",
  ui_story_5088_50880402_62_dialog_content = "Hah?",
  ui_story_5088_50880402_63_dialog_content = "Aku tidak bisa menyingkirkan mereka—",
  ui_story_5088_50880402_64_dialog_content = "Kegelapan di dalam diriku sedang meningkat.",
  ui_story_5088_50880402_65_dialog_content = "Kamu harus pergi, sekarang juga! Jika tidak...",
  ui_story_5088_50880402_66_dialog_content = "Saya akan membunuh kamu!",
  ui_story_5088_50880402_67_dialog_content = "T-Tidak mungkin!",
  ui_story_5088_50880402_68_dialog_content = "Oh, tidak, dia serius... dia tidak akan bertahan lama lagi.",
  ui_story_5088_50880402_69_dialog_content = "Bagaimana mungkin ini bisa terjadi? Apa yang saya lewatkan di sini?!",
  ui_story_5088_50880402_70_dialog_content = "Benar, jurnal-jurnal itu! Aku perlu mencari setiap detail pikirannya dan menemukan jawabannya...",
  ui_story_5088_50880402_71_dialog_content = "PlayerName! Bangun! Kenapa kamu tidur di lantai?",
  ui_story_5088_50880402_72_dialog_content = "Dan lihat dirimu sendiri! Kamu memiliki darah kering yang mengalir dari hidungmu sampai ke dada.",
  ui_story_5088_50880402_73_dialog_content = "Apa sebenarnya yang kamu sembunyikan dari kami? Katakanlah!",
  ui_story_5088_50880402_74_dialog_content = "Maaf, tapi aku belum bisa memberitahumu!",
  ui_story_5088_50880402_75_dialog_content = "Tolong, beri aku beberapa hari lagi, dan aku akan memberitahu kamu semua. Sampai jumpa!",
  ui_story_5088_50880402_76_dialog_content = "Hei, tahan sebentar!",
  ui_story_5088_50880402_77_dialog_content = "(Tidak bisa memberi tahu mereka apa-apa jika Claymore diselamatkan. Aku hanya tidak bisa...)",
  ui_story_5088_50880402_78_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5088_50880402_79_dialog_content = "Tidak... Ini tak mungkin...",
  ui_story_5088_50880402_80_dialog_content = "Dia membuat <color=#FFB400>pilihannya</color> sudah lama. Dia bahkan <color=#FFB400>memprediksinya</color>...",
  ui_story_5088_50880402_81_dialog_content = "Orang yang akan menyelamatkan mereka bukanlah saya, tetapi Caelestite lain di masa depan yang jauh.",
  ui_story_5088_50880402_82_dialog_content = "<color=#e8d9bb>Di tengah hujan lebat, raungan petir mengoyak langit. Jauh di dalam gua yang membeku, raungan lain dapat terdengar...</color>",
  ui_story_5088_50880402_83_dialog_content = "Graaaaaaah—!!!",
  ui_story_5088_50880402_84_dialog_content = "<color=#e8d9bb>Dengan satu tusukan kuat, gelombang energi murni melonjak keluar dari gua dan merobek tanah menjadi terbelah.</color>",
  ui_story_5088_50880402_85_dialog_content = "<color=#e8d9bb>Meskipun tusukan itu nyaris meleset dari Czerny, semangatnya sepenuhnya tergulung oleh niat membunuhnya.</color>",
  ui_story_5088_50880402_86_dialog_content = "<color=#e8d9bb>Pada saat itu, dia akhirnya menyadari betapa berbahayanya teman seperjalanannya.</color>",
  ui_story_5088_50880402_87_dialog_content = "Kenapa... Kenapa harus seperti ini...?",
  ui_story_5088_50880402_88_dialog_content = "<color=#e8d9bb>Berguncang keras, Czerny mencoba berdiri, tetapi kakinya segera gagal menopangnya.</color>",
  ui_story_5088_50880402_89_dialog_content = "<color=#e8d9bb>Dia menjatuhkan jurnal Ludweiss, dan badai yang mengaum cepat menyebar halaman-halamannya.</color>",
  ui_story_5088_50880402_90_dialog_content = "Tidak! Tidaaaak—!!!",
  ui_story_5088_50880402_91_dialog_content = "<color=#e8d9bb>Czerny dengan putus asa mencengkeram halaman-halaman itu, tetapi hanya berhasil mengambil sejumlah kecil dari mereka.</color>",
  ui_story_5088_50880402_92_dialog_content = "<color=#e8d9bb>Dia telah gagal.</color>",
  ui_story_5088_50880402_93_dialog_content = "Aku... Aku gagal... Semua dari mereka.",
  ui_story_5088_50880402_94_dialog_content = "Aku telah menyia-nyiakan upaya terakhir Ludweiss...",
  ui_story_5088_50880402_95_dialog_content = "Dan aku gagal pada Achilles.",
  ui_story_5088_50880402_96_dialog_content = "<color=#e8d9bb>Hujan akhirnya mereda setelah waktu yang tidak diketahui, bersamaan dengan suara mengerikan dari dalam gua.</color>",
  ui_story_5088_50880402_97_dialog_content = "<color=#e8d9bb>Czerny memasuki gua sekali lagi, menggenggam beberapa halaman buku catatan yang bisa ia pulihkan.</color>",
  ui_story_5088_50880402_98_dialog_content = "Apakah benar-benar tidak ada yang bisa kita lakukan untuk membantu kamu? Achilles...",
  ui_story_5088_50880402_99_dialog_content = "...",
  ui_story_5088_50880402_100_dialog_content = "Aku tidak bisa melakukan apa-apa untukmu selain membuang waktumu. Aku tidak pernah berarti apa-apa, bukan?",
  ui_story_5088_50880402_101_dialog_content = "Beritahu aku, Achilles! Beritahu aku betapa bodoh diriku ini!",
  ui_story_5088_50880402_102_dialog_content = "Pergilah, Czerny. Dengan momen kejernihan terakhirku, aku ingin berterima kasih karena telah bertahan bersamaku selama ini.",
  ui_story_5088_50880402_103_dialog_content = "Memiliki seseorang untuk diajak bicara sudah cukup untuk menenangkan monster di dalam hatiku.",
  ui_story_5088_50880402_104_dialog_content = "Tinggalkan tempat ini, dan jangan beritahu siapa pun tentang itu... Aku tidak ingin ada orang baik hati lagi... yang berkorban apa pun demi aku.",
  ui_story_5088_50880402_105_dialog_content = "Ahhhhhh—!!!",
  ui_story_5088_50880402_106_dialog_content = "Dadah... Czerny.",
  ui_story_5088_50880402_107_dialog_content = "Kamu tidak gagal, Czerny, aku masih bisa membantumu!",
  ui_story_5088_50880402_108_dialog_content = "Tidak, suaraku tidak bisa sampai padanya...",
  ui_story_5088_50880402_109_dialog_content = "Argh, mengapa ini terjadi sekarang?!",
  ui_story_5088_50880402_110_dialog_content = "Biarkan saya membantu Anda, Czerny! Saya bisa—",
  ui_story_5088_50880402_111_dialog_content = "Tunggu, jangan tinggalkan dia sendirian!!!",
  ui_story_5088_50880402_112_dialog_content = "Aku masih bisa membantumu!!!",
  ui_story_5088_50880501_1_dialog_content = "Kamu lagi-lagi terlumuri darah. Bahkan Caelestites punya batas kekuatan mereka, bukan?",
  ui_story_5088_50880501_2_dialog_content = "Siapa... yang sedang kamu bicarakan?",
  ui_story_5088_50880501_3_dialog_content = "Czerny... Dimana Czerny?!",
  ui_story_5088_50880501_4_dialog_content = "Tidak ada orang lain di sini selain kita.",
  ui_story_5088_50880501_5_dialog_content = "Tunggu, siapa itu Czerny?",
  ui_story_5088_50880501_6_dialog_content = "Tidak... Tidak, tidak! Dia baru saja di sana! Dia juga menangis... Aku harus membantunya menyelamatkan Achilles—",
  ui_story_5088_50880501_7_dialog_content = "Minggir! Saya akan menggunakan sihir penyembuhan saya untuk—",
  ui_story_5088_50880501_8_dialog_content = "Itu tidak perlu. Aku bisa mengurusnya dari sini.",
  ui_story_5088_50880501_9_dialog_content = "Argh…",
  ui_story_5088_50880501_10_dialog_content = "Lihatlah semua darah ini! Apa yang telah kamu lakukan beberapa hari terakhir ini?!",
  ui_story_5088_50880501_11_dialog_content = "Kurir ini cukup baik untuk membuatkanmu obat untuk menghentikan pendarahan. Kamu harus berterima kasih padanya atas usahanya.",
  ui_story_5088_50880501_12_dialog_content = "T-Terima kasih.",
  ui_story_5088_50880501_13_dialog_content = "Tidak apa-apa. Saya hanya datang untuk mengambil suratmu.",
  ui_story_5088_50880501_14_dialog_content = "Kami bukan orang bodoh... Apapun yang kamu lakukan, itu pasti ada hubungannya dengan kita.",
  ui_story_5088_50880501_15_dialog_content = "Dan lihatlah di mana kamu berada. Jika kamu tidak mau memberi tahu kami apa-apa, saya harus memberi tahu orang lain tentang rahasia Anda, seperti mungkin—",
  ui_story_5088_50880501_16_dialog_content = "Jangan beri tahu Vice atau Carleen soal ini! Tolong!",
  ui_story_5088_50880501_17_dialog_content = "Jadi, kamu akan bicara?",
  ui_story_5088_50880501_18_dialog_content = "A... Aku mencoba mencari tahu kebenaran tentang sesuatu. Maaf... Tapi itu saja yang bisa kuberitahu sekarang.",
  ui_story_5088_50880501_19_dialog_content = "Ketika saatnya tiba, aku akan memberitahumu segalanya.",
  ui_story_5088_50880501_20_dialog_content = "Apakah kamu menahan diri karena khawatir tentang apa yang akan kami rasakan?",
  ui_story_5088_50880501_21_dialog_content = "Ini karena mimpi saya bahwa kamu terlibat dalam semua ini sekarang.",
  ui_story_5088_50880501_22_dialog_content = "Maaf... Tapi aku harus mengetahui kebenaran tentang apa yang terjadi pada Achilles... Maksudku, Claymore.",
  ui_story_5088_50880501_23_dialog_content = "Tapi saya tidak bisa menjangkau mereka setelah saya meninggalkan mimpimu...",
  ui_story_5088_50880501_24_dialog_content = "Harus ada cara lain untuk menyampaikan pikiranku... Victoria pernah mengatakan bahwa semua pikiran Caelestite akan sampai...",
  ui_story_5088_50880501_25_dialog_content = "A... Aku harus membantu mereka...",
  ui_story_5088_50880501_26_dialog_content = "Ada Caelestite di sisinya. Dia belum menyerah...",
  ui_story_5088_50880501_27_dialog_content = "Anda terlihat seperti hampir tidak ada darah tersisa di tubuh Anda. Jika Anda terus memaksakan diri seperti ini, Anda akan mati.",
  ui_story_5088_50880501_28_dialog_content = "Mengapa Anda sampai sejauh ini untuk sekelompok orang luar seperti kami?",
  ui_story_5088_50880501_29_dialog_content = "Tidak ada orang luar di Soroz. Kamu adalah keluarga.",
  ui_story_5088_50880501_30_dialog_content = "?!",
  ui_story_5088_50880501_31_dialog_content = "Hmm…",
  ui_story_5088_50880501_32_dialog_content = "(Dan juga... Aku sama seperti Czerny. Aku tidak bisa hanya berdiam diri dan tidak melakukan apa-apa, tidak setelah melihat cerita mereka.)",
  ui_story_5088_50880501_33_dialog_content = "(Aku menolak untuk membiarkan bintang-bintang ini memudar begitu tragis.)",
  ui_story_5088_50880501_34_dialog_content = "Tolong, aku hanya butuh sedikit lebih banyak waktu...",
  ui_story_5088_50880501_35_dialog_content = "... Apakah kepalamu masih sakit?",
  ui_story_5088_50880501_36_dialog_content = "Aku baik-baik saja, aku hanya butuh udara segar.",
  ui_story_5088_50880501_37_dialog_content = "Hampir lupa, tapi bisakah kamu mengantarkan ini ke Jeriah? Dia bertugas di pos Gurun Rediesel.",
  ui_story_5088_50880501_38_dialog_content = "... Kamu memperlakukan teman-temanmu dengan sangat baik. Kamu mencari-cari buku antik itu untuk teman-temanmu, bukan?",
  ui_story_5088_50880501_39_dialog_content = "Maafkan saya jika saya mengganggu, tapi ini adalah surat yang meminta bantuan Lady Jeriah, bukan?",
  ui_story_5088_50880501_40_dialog_content = "Ya...",
  ui_story_5088_50880501_41_dialog_content = "Saya ingin membantu mereka, apa pun itu.",
  ui_story_5088_50880501_42_dialog_content = "Aku hanya ingin mengungkap kebenaran... Meski sudah terlambat.",
  ui_story_5088_50880501_43_dialog_content = "(Aku ingin melihat apa yang terjadi pada Achilles dan mengerti bagaimana dia bisa seperti itu...)",
  ui_story_5088_50880501_44_dialog_content = "(Masih ada harapan bahwa aku bisa menemukan cara untuk membantunya.)",
  ui_story_5088_50880501_45_dialog_content = "(Juga, saya masih perlu menemukan sisa-sisa Ludweiss.)",
  ui_story_5088_50880501_46_dialog_content = "Maaf telah memberimu jawaban yang aneh.",
  ui_story_5088_50880501_47_dialog_content = "Jangan. Aku ini yang awalnya bertanya aneh kepadamu.",
  ui_story_5088_50880501_48_dialog_content = "Saya akan memastikan surat ini sampai dengan selamat ke Nona Jeriah.",
  ui_story_5088_50880501_49_dialog_content = "Terima kasih atas bantuanmu, dan juga obatnya. Itu membuat merinding, tapi pasti menghentikan pendarahannya.",
  ui_story_5088_50880501_50_dialog_content = "Aku seorang kurir, dan kurir selalu memiliki beberapa trik di lengan baju mereka.",
  ui_story_5088_50880501_51_dialog_content = "Yah, aku akan pergi sekarang.",
  ui_story_5088_50880501_52_dialog_content = "Saya usulkan kita akhiri ini di sini dan sekarang.",
  ui_story_5088_50880501_53_dialog_content = "Saya setuju dengan Friegson. Mengembalikan ingatan kita tidak seharusnya mengorbankan kesehatan Anda, jadi mari kita hentikan ini.",
  ui_story_5088_50880501_54_dialog_content = "Bahkan jika itu berarti kau tak akan pernah mengingat cintamu lagi?",
  ui_story_5088_50880501_55_dialog_content = "... Aku punya seluruh waktu di dunia ini untuk terus mencarinya.",
  ui_story_5088_50880501_56_dialog_content = "Apa pendapatmu, Freya?",
  ui_story_5088_50880501_57_dialog_content = "\"Tidak ada orang luar di Soroz, kamu adalah keluarga.\" Itulah kata-katanya.",
  ui_story_5088_50880501_58_dialog_content = "Saya selalu mempercayai teman-teman saya, dan dia tidak berbeda. Saya menghormati keputusannya.",
  ui_story_5088_50880501_59_dialog_content = "Kamu masih berharap, meskipun kamu telah dikhianati di masa lalu?",
  ui_story_5088_50880501_60_dialog_content = "Aku seorang ksatria, memimpin serangan ke medan perang selalu menjadi tugas ku. Beberapa luka tusukan tidak pernah bisa membuatku berhenti dari itu.",
  ui_story_5088_50880501_61_dialog_content = "Lalu aku juga ingin percaya padanya.",
  ui_story_5088_50880501_62_dialog_content = "Kita tidak sempurna dalam segala hal, jadi mungkin kita tidak seharusnya terlalu cepat mengabaikan PlayerName.",
  ui_story_5088_50880501_63_dialog_content = "Di masa lalu, tidak peduli jenis rasa sakit atau kelemahan yang kita hadapi, selama kita memiliki satu sama lain...",
  ui_story_5088_50880501_64_dialog_content = "Kita bisa mengatasi apa pun dan terus mendorong maju.",
  ui_story_5088_50880501_65_dialog_content = "Wow... Itu sangat indah, Cynthia. Sudah lama sekali kamu tidak mengatakan sesuatu yang serius seperti itu. Itu benar-benar tidak seperti kamu sama sekali.",
  ui_story_5088_50880501_66_dialog_content = "Aku ingin Silent Hunters bisa berkumpul lagi. Apa yang setiap orang pikirkan tentang itu?",
  ui_story_5088_50880501_67_dialog_content = "...",
  ui_story_5088_50880501_68_dialog_content = "Bahkan setelah semua yang saya katakan kepadanya, dia masih beruntung dan menemukan ini dengan salah satu bos lainnya.",
  ui_story_5088_50880501_69_dialog_content = "Saya pikir itu disebut Star Crest?",
  ui_story_5088_50880501_70_dialog_content = "...",
  ui_story_5088_50880501_71_dialog_content = "Dia sedang mencari tahu rahasia dari Star Warriors...",
  ui_story_5088_50880501_72_dialog_content = "Aku... harus menjalankan misiku... Dan menghentikannya...",
  ui_story_5088_50880501_73_dialog_content = "Namun…",
  ui_story_5088_50880501_74_dialog_content = "Ketika berbicara tentang membantu teman-teman saya, saya akan melakukan apa pun yang diperlukan.",
  ui_story_5088_50880501_75_dialog_content = "Saya harus memberikannya kepadanya besok.",
  ui_story_5088_50880501_76_dialog_content = "Keluar dan hadapi aku, kalian pengecut.",
  ui_story_5088_50880501_77_dialog_content = "P-Pemburu Raven?! Jangan lagi!",
  ui_story_5088_50880501_78_dialog_content = "Mengapa kamu tidak mau meninggalkan kami sendiri?! Kami hanya mencoba menagihnya sedikit uang, itu saja!",
  ui_story_5088_50880501_79_dialog_content = "Apa yang membuatmu berpikir dia memiliki sesuatu yang layak dicuri?",
  ui_story_5088_50880501_80_dialog_content = "Mengapa dia tidak? Dia telah bekerja untuk Guild Cloudrover dan bahkan berteman dengan pria Caelestite itu.",
  ui_story_5088_50880501_81_dialog_content = "Maaf mengecewakan kalian, idiot pengejar uang, tapi benda itu sama sekali tidak bernilai.",
  ui_story_5088_50880501_82_dialog_content = "Namun, mencoba mencuri objek yang tak bernilai tetaplah sebuah kejahatan. Bersiaplah untuk dihukum!",
  ui_story_5088_50880502_1_dialog_content = "Oh? Sepertinya aku terlambat bergabung dalam kesenangan.",
  ui_story_5088_50880502_2_dialog_content = "Namun, aku tahu aku akan menemukanmu di sini.",
  ui_story_5088_50880502_3_dialog_content = "...",
  ui_story_5088_50880502_4_dialog_content = "Apa yang salah? Akhir-akhir ini kamu bertingkah berbeda.",
  ui_story_5088_50880502_5_dialog_content = "Dan kamu juga lebih keras terhadap orang jahat.",
  ui_story_5088_50880502_6_dialog_content = "Ini tidak apa-apa. Kenapa kamu keluar begitu larut malam? Apa kamu tidak harus bekerja di siang hari?",
  ui_story_5088_50880502_7_dialog_content = "Peduli, sih... Tapi tidak apa-apa.",
  ui_story_5088_50880502_8_dialog_content = "Selalu lebih penting untuk mendengarkan teman-teman saya.",
  ui_story_5088_50880502_9_dialog_content = "Saya tidak punya apa-apa untuk dikatakan. Kita hanya saling kenal selama dua tahun, dan kita hanya bertemu di malam hari kadang-kadang. Apakah kamu benar-benar menyebut itu \"persahabatan\"?",
  ui_story_5088_50880502_10_dialog_content = "Dua tahun itu waktu yang lama, tahu!",
  ui_story_5088_50880502_11_dialog_content = "Lebih lagi, kita bertemu satu sama lain karena upaya kita dalam memerangi kejahatan. Itu membuat kita menjadi teman seperjuangan!",
  ui_story_5088_50880502_12_dialog_content = "Teman seperjuangan? Tolonglah. Kamu bahkan tidak tahu namaku.",
  ui_story_5088_50880502_13_dialog_content = "Kamu benar, itulah sebabnya aku ingin mengenal kamu di siang hari juga. Aku yakin kamu tetap keren meski tidak sedang melawan penjahat!",
  ui_story_5088_50880502_14_dialog_content = "Maaf mengecewakanmu, tetapi tidak ada yang menarik tentang saya atau kehidupan sehari-hari saya.",
  ui_story_5088_50880502_15_dialog_content = "Terutama bukan untuk seseorang sepertimu... Yang selalu bersinar terang setiap saat...",
  ui_story_5088_50880502_16_dialog_content = "Hah? Apakah kamu mencoba mengatakan bahwa kamu hanyalah orang biasa di siang hari?",
  ui_story_5088_50880502_17_dialog_content = "Karena menurutku, kau terlalu kuat untuk menjadi apa pun selain luar biasa!",
  ui_story_5088_50880502_18_dialog_content = "Faktanya, saya yakin Anda bisa menginspirasi orang lain seperti beberapa idola terbaik di luar sana!",
  ui_story_5088_50880502_19_dialog_content = "... Jangan konyol.",
  ui_story_5088_50880502_20_dialog_content = "Kamu tahu... Ada sesuatu yang ingin saya bicarakan. Itu sepele, tetapi maukah kamu mendengarkannya?",
  ui_story_5088_50880502_21_dialog_content = "Tentu saja! Dan jangan khawatir, tidak peduli seberapa penting atau sepele itu, aku berjanji akan merahasiakannya.",
  ui_story_5088_50880502_22_dialog_content = "Sebuah rahasia, huh? Heheh...",
  ui_story_5088_50880502_23_dialog_content = "Kenyataannya, saya lahir dalam klan yang unik, dan sepanjang hidup saya, saya telah dipercayakan untuk menjalankan misi tertentu.",
  ui_story_5088_50880502_24_dialog_content = "Untuk itu, saya diajarkan untuk selalu mengamati hal-hal dari jarak jauh dan untuk tidak pernah terlibat.",
  ui_story_5088_50880502_25_dialog_content = "Kami adalah keluarga bayangan yang beroperasi di luar aliran waktu. Itulah sebabnya kami harus menyembunyikan diri selama siang hari.",
  ui_story_5088_50880502_26_dialog_content = "Tapi sekarang... Orang-orang yang kami sumpah untuk melindungi... Tidak banyak dari mereka yang tersisa.",
  ui_story_5088_50880502_27_dialog_content = "Wow! Sepertinya keluargamu melindungi jenis makhluk langka!",
  ui_story_5088_50880502_28_dialog_content = "Bagaimana bisa kamu berpikir itu tidak penting? Melindungi sesuatu sebagai misi dalam hidupmu membutuhkan banyak fokus dan kehati-hatian.",
  ui_story_5088_50880502_29_dialog_content = "Saya pikir itu luar biasa bahwa Anda mampu menyembunyikan cahaya Anda demi misi Anda.",
  ui_story_5088_50880502_30_dialog_content = "\"makhluk langka\"... Itu tidak sepenuhnya salah, saya kira. Dalam hal apapun, jika saya gagal menjalankan misi saya, maka itu akan lebih atau kurang berakhir dengan saya.",
  ui_story_5088_50880502_31_dialog_content = "Karena orang itu... Saya tidak yakin orang itu mampu memenuhi ramalan.",
  ui_story_5088_50880502_32_dialog_content = "Dan kemudian klan saya akan terikat untuk sisa waktu.",
  ui_story_5088_50880502_33_dialog_content = "Tapi di luar itu, aku... aku hanya ingin membantu kelompok orang tertentu itu.",
  ui_story_5088_50880502_34_dialog_content = "Tapi, saya telah bersumpah untuk melindungi rahasia mereka, jadi saya hanya bisa mengawasi mereka dalam diam. Saya tidak bisa mengkhianati sumpah saya.",
  ui_story_5088_50880502_35_dialog_content = "Apakah itu yang telah mengganggumu?",
  ui_story_5088_50880502_36_dialog_content = "Kamu telah melampiaskan frustrasi kamu pada orang jahat karena itu?",
  ui_story_5088_50880502_37_dialog_content = "Untuk berbagai alasan yang tidak bisa aku bahas, leluhurku mampu menanamkan beberapa kenangan mereka ke dalam pusaka keluarga kami, yang telah diturunkan dari generasi ke generasi.",
  ui_story_5088_50880502_38_dialog_content = "Melaluinya, aku bisa mendengar kemarahan dan penyesalan mereka.",
  ui_story_5088_50880502_39_dialog_content = "Tapi sang Lord pernah mengatakan kepada kami untuk tidak melibatkan orang lain demi dirinya.",
  ui_story_5088_50880502_40_dialog_content = "Sejak saat itu, kami tetap bersembunyi dan mengawasi dalam diam, menunggu orang yang telah dinubuatkan untuk menyelesaikan misi kami dan membebaskan kita semua.",
  ui_story_5088_50880502_41_dialog_content = "Tapi kaum yang telah dinubuatkan... Mereka semua telah...",
  ui_story_5088_50880502_42_dialog_content = "Saya tidak bisa mengatakan saya sangat mengerti apa yang Anda katakan.",
  ui_story_5088_50880502_43_dialog_content = "Tapi kedengarannya hidupmu sangat penting... Dan juga kesepian, begitu.",
  ui_story_5088_50880502_44_dialog_content = "Klan Anda telah dipercayakan dengan misi mereka sejak lama, bukan? Sangat mengesankan bahwa Anda tetap setia pada misi itu setelah semua tahun ini.",
  ui_story_5088_50880502_45_dialog_content = "Dan itu hanya bisa menjadi hasil dari iman dan tekad yang tak tergoyahkan.",
  ui_story_5088_50880502_46_dialog_content = "Sesuatu memberitahuku bahwa leluhurmu, orang yang membuat sumpah itu, merasakan rasa cinta dan kasih sayang yang luar biasa terhadap orang-orang yang dia sumpahi untuk melindungi.",
  ui_story_5088_50880502_47_dialog_content = "Yang membuatku berasumsi bahwa mereka tidak ingin kamu begitu pasif tentang misimu.",
  ui_story_5088_50880502_48_dialog_content = "Hah?",
  ui_story_5088_50880502_49_dialog_content = "Jika kamu mengambil tindakan untuk membantu orang-orang yang telah kamu sumpah untuk melindungi, saya pikir itu akan lebih memenuhi keinginan leluhurmu. Bukankah kamu setuju?",
  ui_story_5088_50880502_50_dialog_content = "Selain itu, dalam dua tahun kita berjuang melawan kejahatan bersama, saya tidak pernah melihat kamu sangat pasif tentang apa pun.",
  ui_story_5088_50880502_51_dialog_content = "Menunggu orang lain menyelamatkanmu seperti gadis yang sedang dalam kesulitan... Itu sama sekali tidak seperti dirimu.",
  ui_story_5088_50880502_52_dialog_content = "Saya pikir masih banyak yang bisa kamu lakukan untuk menyelesaikan misimu.",
  ui_story_5088_50880502_53_dialog_content = "Kamu tidak harus melanggar sumpahmu, tetapi dengan beberapa dorongan ke arah yang benar... Kamu mungkin bisa mewujudkan tujuan leluhurmu.",
  ui_story_5088_50880502_54_dialog_content = "Apa? Kalian serius?",
  ui_story_5088_50880502_55_dialog_content = "Tentu saja aku tahu!",
  ui_story_5088_50880502_56_dialog_content = "… Terima kasih.",
  ui_story_5088_50880502_57_dialog_content = "Kamu benar sekali. Leluhurku tidak bisa mencapai hari yang telah diramalkan, tetapi aku bisa...",
  ui_story_5088_50880502_58_dialog_content = "Setidaknya, aku harus mencoba melakukan sesuatu.",
  ui_story_5088_50880502_59_dialog_content = "Tapi kamu sudah tahu itu, bukan?",
  ui_story_5088_50880502_60_dialog_content = "... Ya. Hanya saja, aku selalu takut membuat keadaan menjadi lebih buruk.",
  ui_story_5088_50880502_61_dialog_content = "Tapi aku benci berdiam diri sementara mereka masih membutuhkan bantuanku.",
  ui_story_5088_50880502_62_dialog_content = "Ketika berbicara tentang ramalan, selalu ada seseorang yang harus membuatnya menjadi kenyataan.",
  ui_story_5088_50880502_63_dialog_content = "Itulah mengapa Anda tidak dapat mengandalkan orang lain untuk mewujudkan sesuatu. Anda harus melakukannya sendiri.",
  ui_story_5088_50880502_64_dialog_content = "Itu salah satu prinsip dasar menjadi seorang idola... Eh, maksud saya pahlawan!",
  ui_story_5088_50880502_65_dialog_content = "Terima kasih, Goldie.",
  ui_story_5088_50880502_66_dialog_content = "Aku akan menemukan cara untuk membantu mereka tanpa melanggar sumpahku.",
  ui_story_5088_50880502_67_dialog_content = "Ini bukan masalah besar... Tunggu, kamu tahu siapa aku?!?",
  ui_story_5088_50880502_68_dialog_content = "H-Hei, kembali ke sini! Kamu harus menjelaskan ini!",
  ui_story_5088_50880502_69_dialog_content = "Tidak adil jika saya tidak tahu identitas Anda juga! Kembali!",
  ui_story_5088_50880601_1_dialog_content = "(Casta membawakan saya lambang lain. Sama seperti yang lain, saya tidak mengenali desain yang terukir di atasnya.)",
  ui_story_5088_50880601_2_dialog_content = "(Apakah ini... not musik?)",
  ui_story_5088_50880601_3_dialog_content = "Agar kamu tahu, jika kami menyadari ada yang salah denganmu, kami akan segera menghentikanmu.",
  ui_story_5088_50880601_4_dialog_content = "Itulah syarat kami.",
  ui_story_5088_50880601_5_dialog_content = "Jangan khawatir, saya tidak akan memaksakan diri terlalu keras.",
  ui_story_5088_50880601_6_dialog_content = "... Aku akan membuat sesuatu yang istimewa untukmu coba setelah kau kembali dari waktu kita.",
  ui_story_5088_50880601_7_dialog_content = "Coba untuk tidak tersesat dalam mimpi.",
  ui_story_5088_50880601_8_dialog_content = "... Berapa banyak waktu yang telah berlalu sejak itu? Apakah Czerny bisa kembali dengan selamat ke Eraveil?",
  ui_story_5088_50880601_9_dialog_content = "Aku berdoa untuk kedamaian dia, dan berharap bahwa dia akan melupakan kita suatu hari nanti dan hidup panjang dan bahagia.",
  ui_story_5088_50880601_10_dialog_content = "Maaf, Ludweiss, tapi kamu harus menunggu bersama kami sedikit lebih lama...",
  ui_story_5088_50880601_11_dialog_content = "Saya tidak bisa lagi mengingat waktu. Banyak hal mulai tampak kabur bersamaan.",
  ui_story_5088_50880601_12_dialog_content = "Kurasa aku hampir mencapai batasku... Aku perlu menulis satu peringatan terakhir untuk keturunan klan Longinus...",
  ui_story_5088_50880601_13_dialog_content = "\"Jauh-jauhlah dari kedalaman gua.\"",
  ui_story_5088_50880601_14_dialog_content = "Urgh... Bahkan melakukan sesuatu yang sepele seperti ini membuatku benar-benar lelah...",
  ui_story_5088_50880601_15_dialog_content = "Seharusnya aku sudah benar-benar rusak sekarang, tetapi mereka belum berhenti.",
  ui_story_5088_50880601_16_dialog_content = "Berapa lama lagi aku bisa tetap mengendalikan diri? Apakah ini... benar-benar di luar kemampuanku sekarang?",
  ui_story_5088_50880601_17_dialog_content = "Kamu berbohong padaku, Ludweiss.",
  ui_story_5088_50880601_18_dialog_content = "Tidak... Apa yang baru saja terjadi?! Bagaimana aku bisa menyalahkan Ludweiss untuk ini?",
  ui_story_5088_50880601_19_dialog_content = "Teman-temanku... Aku juga telah mengecewakanmu...",
  ui_story_5088_50880601_20_dialog_content = "Apakah benar-benar mustahil menggunakan ingatanku untuk melawan perjalanan waktu?",
  ui_story_5088_50880601_21_dialog_content = "Tolong... Tolong aku...",
  ui_story_5088_50880601_22_dialog_content = "<color=#e8d9bb>Udara dipenuhi dengan sorak-sorai yang keras dan bersemangat—</color>",
  ui_story_5088_50880601_23_dialog_content = "…?",
  ui_story_5088_50880601_24_dialog_content = "Puji para Star Warrior, pahlawan yang telah membasmi para Eclipsite!",
  ui_story_5088_50880601_25_dialog_content = "Sebagai raja Anda, merupakan kehormatan yang luar biasa bagi saya untuk memberikan Anda penghargaan-penghargaan ini.",
  ui_story_5088_50880601_26_dialog_content = "Pahlawan! Pahlawan! Pahlawan! Pahlawan!",
  ui_story_5088_50880601_27_dialog_content = "Ah... Momen kejayaan terbesar kita...",
  ui_story_5088_50880601_28_dialog_content = "Buatlah janji Anda di hadapan dewa-dewa, dan terimalah kehormatan yang telah Anda peroleh dengan adil.",
  ui_story_5088_50880601_29_dialog_content = "Maju.",
  ui_story_5088_50880601_30_dialog_content = "Selama masih ada satu orang yang benar di dunia ini, aku akan selalu siap mengorbankan hidupku untuknya.",
  ui_story_5088_50880601_31_dialog_content = "Kamu adalah perisai mulia kerajaan, teguh dan bersedia membela yang lemah dan tidak bersalah. Dengan dewa sebagai saksi saya, saya dengan ini memberikan gelar \"Regal\" kepada kamu!",
  ui_story_5088_50880601_32_dialog_content = "Aku bersumpah akan menjadi sungai api yang menghukum, dan membersihkan dunia dari kejahatan dengan nyala apiku.",
  ui_story_5088_50880601_33_dialog_content = "Api kamu membakar paling terang saat kamu memimpin serangan ke dalam pertempuran. Dengan dewa-dewa sebagai saksi saya, saya dengan ini memberikan gelar \"Frostfire\" kepada kamu!",
  ui_story_5088_50880601_34_dialog_content = "Aku bersumpah untuk menjaga harapan, dan menjadi cahaya yang membimbing mereka yang menderita dan putus asa!",
  ui_story_5088_50880601_35_dialog_content = "Dengan tombakmu yang cemerlang, kamu membelah kegelapan dan menyambut fajar yang datang. Dengan dewa-dewa sebagai saksi saya, saya dengan ini memberikan gelar \"Requiem\" kepadamu!",
  ui_story_5088_50880601_36_dialog_content = "Aku bersumpah untuk melindungi setiap momen kedamaian, dan tetap memegang tongkatku meski tubuhku binasa.",
  ui_story_5088_50880601_37_dialog_content = "Cahaya tenangmu meredam kekacauan dunia kita demi nama perdamaian. Dengan dewa-dewa sebagai saksi saya, saya dengan ini memberikan gelar \"Mythos\" kepadamu!",
  ui_story_5088_50880601_38_dialog_content = "Wuu-huu—!!!",
  ui_story_5088_50880601_39_dialog_content = "Sekarang giliranmu, Kapten.",
  ui_story_5088_50880601_40_dialog_content = "Majulah dan ucapkan sumpahmu, Achilles.",
  ui_story_5088_50880601_41_dialog_content = "May para dewa menjadi saksi sumpahku! Demi orang-orang yang kucintai, aku bersumpah akan mengorbankan segalanya sampai waktu mengubahku menjadi debu!",
  ui_story_5088_50880601_42_dialog_content = "Aku tak memiliki penyesalan—",
  ui_story_5088_50880601_43_dialog_content = "Ah... Ternyata hanya mimpi... Satu yang jarang dan menyenangkan, tidak kurang.",
  ui_story_5088_50880601_44_dialog_content = "Apakah aku akan pernah melihat bagaimana orang-orang itu menjalani hidup mereka yang damai? Apakah kerajaan masih membutuhkan orang lain untuk mengorbankan diri mereka untuk itu?",
  ui_story_5088_50880601_45_dialog_content = "<color=#e8d9bb>Retakan-</color>",
  ui_story_5088_50880601_46_dialog_content = "?",
  ui_story_5088_50880601_47_dialog_content = "Apakah seseorang di sana...?",
  ui_story_5088_50880601_48_dialog_content = "Hah? Aduh, tidak lagi! Bagaimana bisa terputus tepat di sana?!",
  ui_story_5088_50880601_49_dialog_content = "Baiklah PlayerName, itu cukup untuk hari ini. Kamu telah melakukan pekerjaan yang baik, sekarang datang dan makan bersama kami!",
  ui_story_5088_50880601_50_dialog_content = "Dia mungkin tidak terlihat seperti itu, tapi Adras adalah koki yang cukup andal!",
  ui_story_5088_50880601_51_dialog_content = "Saya harus begitu jika ingin memberi makan anak-anak itu dengan benar... Hmm?",
  ui_story_5088_50880601_52_dialog_content = "Aku…",
  ui_story_5088_50880601_53_dialog_content = "Jangan terlalu memaksakan diri. Tidak apa-apa jika kamu tidak bisa mengingat untuk saat ini.",
  ui_story_5088_50880601_54_dialog_content = "...",
  ui_story_5088_50880601_55_dialog_content = "Ayo Adras, ayo kita makan.",
  ui_story_5088_50880601_56_dialog_content = "Tentu.",
  ui_story_5088_50880601_57_dialog_content = "Kamu yang terbaik, Adras! Ah, aku sudah sangat ingin makan ini selama dua ribu tahun terakhir!",
  ui_story_5088_50880601_58_dialog_content = "Eh? Siapa di sana?!",
  ui_story_5088_50880601_59_dialog_content = "Tahan di sana! Tempat ini milik Blue Wolverines.",
  ui_story_5088_50880601_60_dialog_content = "Saya sangat menyadari itu!",
  ui_story_5088_50880601_61_dialog_content = "Klan saya meninggalkan sesuatu dalam kepemilikanmu. Saya di sini untuk mengambilnya kembali.",
  ui_story_5088_50880601_62_dialog_content = "Hah?",
  ui_story_5088_50880601_63_dialog_content = "Enyah!",
  ui_story_5088_50880601_64_dialog_content = "Lalu saya kira saya harus menunjukkan padamu.",
  ui_story_5088_50880601_65_dialog_content = "Saksikan aku—Karena aku adalah kematian.",
  ui_story_5088_50880602_1_dialog_content = "Wow, kamu benar-benar datang lebih awal!",
  ui_story_5088_50880602_2_dialog_content = "Lady Jeriah meminta saya untuk mengantarkan ini secara pribadi kepada Anda. Ini pasti sangat mendesak.",
  ui_story_5088_50880602_3_dialog_content = "Sampai bertemu.",
  ui_story_5088_50880602_4_dialog_content = "Eh... Nona Mithra?",
  ui_story_5088_50880602_5_dialog_content = "Ya?",
  ui_story_5088_50880602_6_dialog_content = "Saya yakin jurnal ini sangat penting, tapi... Saya tidak perlu menggunakan kekuatan saya untuk mengetahui bahwa ini milik klan Longinus.",
  ui_story_5088_50880602_7_dialog_content = "Aku sudah tahu tentang gelombang frekuensi mereka.",
  ui_story_5088_50880602_8_dialog_content = "...",
  ui_story_5088_50880602_9_dialog_content = "Sebagai seorang Caelestite, membedakan orang-orang berbeda adalah sesuatu yang datang secara alami bagi saya.",
  ui_story_5088_50880602_10_dialog_content = "Saya tidak merasakan Jeriah sama sekali dari jurnal ini, tetapi saya merasakan kehadiran yang sangat akrab di atasnya... Milikmu.",
  ui_story_5088_50880602_11_dialog_content = "... Saya tidak sepenuhnya yakin pada hari itu, karena kami hanya pernah bertemu sekali sebelumnya.",
  ui_story_5088_50880602_12_dialog_content = "Tapi ketika kamu muncul dengan Tweety keesokan harinya, saya tahu itu kamu.",
  ui_story_5088_50880602_13_dialog_content = "...",
  ui_story_5088_50880602_14_dialog_content = "Tak peduli apa situasinya, kamu telah menyelamatkanku dan aku berterima kasih untuk itu. Pasti ada alasan untuk menyembunyikan identitasmu, 'kan?",
  ui_story_5088_50880602_15_dialog_content = "Mengenai buku catatan ini... Kenapa kamu menggunakan nama Lady Jeriah untuk membawanya kepadaku?",
  ui_story_5088_50880602_16_dialog_content = "Bukankah itu... penting untuk keluargamu?",
  ui_story_5088_50880602_17_dialog_content = "Baiklah, mari kita hitung cepat—Dengan menunjukkan tangan, berapa banyak dari kita yang tidak tahu berterima kasih? Silakan, angkat tangan kalian.",
  ui_story_5088_50880602_18_dialog_content = "...",
  ui_story_5088_50880602_19_dialog_content = "Bagus! Sepertinya tidak ada satupun dari kita yang menjadi orang yang egois dan tidak tahu terima kasih.",
  ui_story_5088_50880602_20_dialog_content = "Nah, mari kita undang Cynthia untuk mengucapkan beberapa kata!",
  ui_story_5088_50880602_21_dialog_content = "... Ayo kita pergi.",
  ui_story_5088_50880602_22_dialog_content = "Seperti yang diharapkan dari seorang Caelestite.",
  ui_story_5088_50880602_23_dialog_content = "Pada titik ini, kamu mungkin tahu lebih banyak daripada saya. Sepertinya tidak ada alasan untuk mempertahankan sandiwara ini lagi...",
  ui_story_5088_50880602_24_dialog_content = "Seperti yang kamu katakan. Nama saya Mithra Longinus.",
  ui_story_5088_50880602_25_dialog_content = "Keluargaku, Klan Longinus, telah sabar menunggu kedatangan Caelestite yang diramalkan selama lebih dari dua ribu tahun.",
  ui_story_5088_50880602_26_dialog_content = "Dua ribu tahun...?",
  ui_story_5088_50880602_27_dialog_content = "Heheh, aku ragu bahkan Lady Ludweiss tahu bahwa ramalannya akan memakan waktu sepanjang ini.",
  ui_story_5088_50880602_28_dialog_content = "Selama berabad-abad, klan kami telah mengamati perubahan dunia dari balik bayangan.",
  ui_story_5088_50880602_29_dialog_content = "Bahkan setelah bertahun-tahun, tidak pernah kita lupa tujuan kita: untuk menghentikan siapa pun dari mengungkap rahasia bintang-bintang.",
  ui_story_5088_50880602_30_dialog_content = "Dan masih, kau tidak pernah mencoba menghentikanku dari menggali sekitar. Apakah karena aku seorang Caelestite?",
  ui_story_5088_50880602_31_dialog_content = "Benar. Dan tidak hanya itu, kamu adalah Caelestite dari ramalan Lady Ludweiss.",
  ui_story_5088_50880602_32_dialog_content = "Klan kami selalu mengizinkan Caelestite untuk menyelidiki rahasia kami selama berabad-abad, tetapi kami tidak pernah secara eksplisit meminta bantuan mereka. Saya yakin kamu tahu alasan mengapa—",
  ui_story_5088_50880602_33_dialog_content = "Tuan Achilles tidak bisa disegel, tetapi korupsinya juga tidak bisa dibalikkan.",
  ui_story_5088_50880602_34_dialog_content = "Tubuhnya dipenuhi dengan kekuatan kegelapan. Caelestite biasa, yang dibatasi oleh belenggu bawaan mereka, tidak pernah berharap untuk mengendalikan kekuatan seperti itu.",
  ui_story_5088_50880602_35_dialog_content = "Mencoba merasakan pikirannya bisa membuatmu kehilangan akal sehatmu dalam kondisi terbaik, tetapi dalam kondisi terburuk... Bantahan dari bisikan bintang yang jatuh bisa membunuhmu.",
  ui_story_5088_50880602_36_dialog_content = "... Caelestite di Eraveil tidak ada tandingannya dalam hal kebaikan dan belas kasihan. Karena itu, meminta bantuan dari mereka sama saja dengan mempertaruhkan nyawa mereka.",
  ui_story_5088_50880602_37_dialog_content = "Peluang mereka untuk mendapatkan keselamatan sangat tipis, dan Lord Achilles menolak untuk membiarkan lebih banyak orang mengorbankan diri mereka demi mereka.",
  ui_story_5088_50880602_38_dialog_content = "Jadi kalian menyimpan semua ini untuk diri sendiri daripada memberi tahu Caelestite?",
  ui_story_5088_50880602_39_dialog_content = "... Ada lebih banyak alasan daripada itu, tapi ya. Pada akhirnya, kami memutuskan bahwa menunggu dalam diam adalah pilihan yang lebih baik.",
  ui_story_5088_50880602_40_dialog_content = "Sebelum Lady Ludweiss meninggal, dia mengaku telah melihat seorang Caelestite dari ribuan tahun di masa depan.",
  ui_story_5088_50880602_41_dialog_content = "Dan di sisi Caelestite itu ada Lord Adras, yang telah dibebaskan dari segelnya.",
  ui_story_5088_50880602_42_dialog_content = "Sejak saat itu, kami telah sabar menunggu terwujudnya nubuat ini.",
  ui_story_5088_50880602_43_dialog_content = "Tapi, meski setelah dua milenium dan pergolakan di seluruh dunia kita... Hari yang telah kita nantikan belum juga tiba.",
  ui_story_5088_50880602_44_dialog_content = "... Dan sekarang aku adalah Caelestite terakhir di dunia ini. Selama tujuh belas tahun terakhir, dunia berpikir bahwa kaum kita telah benar-benar musnah... Tapi kemudian aku muncul.",
  ui_story_5088_50880602_45_dialog_content = "Tapi, bahkan setelah itu, keluargamu masih tetap kuat dan menunggu.",
  ui_story_5088_50880602_46_dialog_content = "Aku... Tidak ada yang kuat dariku. Bahkan, hatiku masih penuh keraguan...",
  ui_story_5088_50880602_47_dialog_content = "Saya tidak percaya bahwa \"penyelamat\" yang disebut-sebut ini adalah satu-satunya yang bisa membebaskan kita dan Tuan Achilles dari takdir kita.",
  ui_story_5088_50880602_48_dialog_content = "Melalui usaha saya, akhirnya saya menyadari bahwa leluhur saya merasakan hal yang sama seperti saya dan bahwa kami menghadapi rintangan yang serupa dalam hidup kami.",
  ui_story_5088_50880602_49_dialog_content = "Tanpa seorang Caelestite, bahkan hanya untuk memecahkan segel pada Star Warriors pun menjadi tidak mungkin.",
  ui_story_5088_50880602_50_dialog_content = "Tapi tetap saja, pasti ada sesuatu yang bisa kulakukan...",
  ui_story_5088_50880602_51_dialog_content = "Jadi itulah sebabnya kamu membawa ini untukku...",
  ui_story_5088_50880602_52_dialog_content = "Jurnal itu berisi keinginan dan pengalaman terdalam Longinus sepanjang zaman.",
  ui_story_5088_50880602_53_dialog_content = "Sebagai seorang Caelestite, Anda seharusnya bisa mendapatkan banyak petunjuk darinya.",
  ui_story_5088_50880602_54_dialog_content = "Melakukan ini juga bukan pelanggaran terhadap sumpahku.",
  ui_story_5088_50880602_55_dialog_content = "Terima kasih. Aku akan menjaganya dengan baik dan belajar sebanyak mungkin.",
  ui_story_5088_50880602_56_dialog_content = "Mereka mengandalkanmu... Dan begitu juga aku.",
  ui_story_5088_50880602_57_dialog_content = "(Tampaknya dia berpikir masih ada kesempatan untuk menyelamatkan Achilles...)",
  ui_story_5088_50880602_58_dialog_content = "(Tidak, itu tidak mungkin benar. Jika Achilles benar-benar mati dan Star Warriors lainnya dibangkitkan oleh saya, maka tidak ada alasan bagi dia untuk khawatir tentang itu.)",
  ui_story_5088_50880602_59_dialog_content = "(Tapi karena dia masih menjalankan tugasnya, itu berarti... Achilles mungkin masih hidup di suatu tempat, yang berarti masih ada kesempatan...)",
  ui_story_5088_50880602_60_dialog_content = "Aku harus kembali ke gua itu!",
  ui_story_5088_50880602_61_dialog_content = "Lumayan juga, PlayerName! Bagaimana kamu tahu kita akan kembali ke tempat itu?",
  ui_story_5088_50880602_62_dialog_content = "Hah? Apa yang sedang kalian lakukan?",
  ui_story_5088_50880602_63_dialog_content = "Kami tidak pernah menjadi orang yang tidak bersyukur.",
  ui_story_5088_50880602_64_dialog_content = "Seseorang menggunakan emosi kuat mereka untuk menyegel kita.",
  ui_story_5088_50880602_65_dialog_content = "Dan kami ingin tahu siapa orang itu.",
  ui_story_5088_50880602_66_dialog_content = "Benar, dan kita juga ingin tahu apa yang sebenarnya dia lakukan terhadap kita.",
  ui_story_5088_50880602_67_dialog_content = "Jika itu hanya tindakan pengkhianatan yang sederhana, tidak ada kebutuhan untuk menyegel emosi kita juga.",
  ui_story_5088_50880602_68_dialog_content = "Tapi... Kita adalah orang-orang yang membunuhnya... Jika kamu mengetahui cerita di balik ini...",
  ui_story_5088_50880602_69_dialog_content = "Dia adalah orang yang mengajari saya bahwa api saya dapat digunakan untuk membantu orang lain.",
  ui_story_5088_50880602_70_dialog_content = "Dia menghentikan Eclipsite dari menghancurkan hutan ku, dan menunjukkan bagaimana menggunakan kekuatanku untuk melindungi dunia ini.",
  ui_story_5088_50880602_71_dialog_content = "Dia membantuku mengalahkan mereka yang telah menyakitiku, dan memberiku alasan untuk terus hidup.",
  ui_story_5088_50880602_72_dialog_content = "Heheh, dia menarikku keluar dari kegelapan dan memberiku tujuan baru dalam hidup.",
  ui_story_5088_50880602_73_dialog_content = "Kalian...",
  ui_story_5088_50880602_74_dialog_content = "Jadi sejauh yang kita ketahui, orang itu bukan Claymore atau semacam monster. Namanya adalah Achilles.",
  ui_story_5088_50880602_75_dialog_content = "Kita tidak bisa membiarkan kamu melakukan ini sendiri, dan kita tentu tidak bisa berpura-pura bahwa dia jahat dan seolah-olah itu sudah cukup.",
  ui_story_5088_50880602_76_dialog_content = "Meski sekarang aku ingat dia... Aku masih tidak bisa menahan rasa marah...",
  ui_story_5088_50880602_77_dialog_content = "Tapi, kita masih perlu mengetahui kebenarannya.",
  ui_story_5088_50880602_78_dialog_content = "Perasaan ini nyata. Kami yakin akan hal itu.",
  ui_story_5088_50880602_79_dialog_content = "Heh, kita pasti benar-benar membencinya sebelumnya, karena kita ingin saling membunuh segera setelah kita bertatapan mata.",
  ui_story_5088_50880602_80_dialog_content = "Benar... Kadang-kadang kami membuatnya terdengar sepele, tetapi kenyataannya adalah dia menusuk kami dengan pedangnya tanpa mengucapkan sepatah kata pun.",
  ui_story_5088_50880602_81_dialog_content = "Dia lebih kuat dari kita semua, dan dia mencoba membunuh kita tanpa mengatakan apapun... Bertarung dengannya adalah hal yang tak terhindarkan.",
  ui_story_5088_50880602_82_dialog_content = "Tapi ingat, alasan kita pergi ke sana adalah untuk mengetahui kebenaran dan memastikan apakah dia masih hidup atau tidak. Perbedaannya sekarang adalah pikiran kita lebih tenang dan jernih daripada sebelumnya.",
  ui_story_5088_50880602_83_dialog_content = "... Itulah pendapat kami tentang masalah itu, PlayerName.",
  ui_story_5088_50880602_84_dialog_content = "Tidak peduli seberapa menyakitkan atau kejam itu, kami masih ingin mengetahui kebenarannya.",
  ui_story_5088_50880602_85_dialog_content = "Untuk kenangan kita, dan demi kehormatannya.",
  ui_story_5088_50880602_86_dialog_content = "Kita tidak bisa melupakan segalanya begitu saja seperti ini.",
  ui_story_5088_50880602_87_dialog_content = "Dan karena tubuh kita yang tak bisa mati, masih ada harapan...",
  ui_story_5088_50880602_88_dialog_content = "Bahkan jika hanya ada sedikit peluang untuk menyelamatkannya...",
  ui_story_5088_50880602_89_dialog_content = "Kami akan melakukan segala yang kami bisa untuk mewujudkannya, bahkan jika dia benar-benar mengkhianati kami di masa lalu.",
  ui_story_5088_50880602_90_dialog_content = "Jadi, ayo kita semua pergi bersama!",
  ui_story_5088_50880602_91_dialog_content = "...",
  ui_story_5088_50880602_92_dialog_content = "Baiklah!",
  ui_story_5088_50880701_1_dialog_content = "<color=#e8d9bb>Menurut catatan, Klan Longinus akhirnya berhasil menemukan keberadaan Czerny.</color>",
  ui_story_5088_50880701_2_dialog_content = "<color=#e8d9bb>Setelah kembali ke Eraveil, dia tidak menyebutkan tentang Star Warriors kepada siapa pun.</color>",
  ui_story_5088_50880701_3_dialog_content = "<color=#e8d9bb>Orang tua Czerny, yang lega bahwa putra mereka akhirnya telah pulang ke rumah, menyambutnya dengan tangan terbuka, dan mereka melanjutkan hidup bahagia mereka bersama-sama.</color>",
  ui_story_5088_50880701_4_dialog_content = "<color=#e8d9bb>Tetapi pada saat itu, keangkuhan yang mendefinisikan kepribadian Czerny telah digantikan dengan sikap tenang dan lembut.</color>",
  ui_story_5088_50880701_5_dialog_content = "<color=#e8d9bb>Dia tidak pernah berpartisipasi dalam kompetisi lain, dan malah mengabdikan usahanya untuk mengajar musik.</color>",
  ui_story_5088_50880701_6_dialog_content = "<color=#e8d9bb>Karya terkenalnya yang tragis dan khidmat segera menjadi melodi khas dari hari libur Caelestite, Windelion.</color>",
  ui_story_5088_50880701_7_dialog_content = "<color=#e8d9bb>Di kemudian hari, dia mendirikan sebuah batu nisan tanpa nama di tempat semua Caelestites diletakkan untuk beristirahat. Setiap tahun pada Windelion, dia akan mengunjungi batu nisan dan memberikan penghormatannya.</color>",
  ui_story_5088_50880701_8_dialog_content = "<color=#e8d9bb>Kebanyakan orang tidak tahu siapa yang sedang dia ratapi. Dari rasa hormat kepada guru musik ini, tidak ada yang berani bertanya atau bahkan berspekulasi tentang siapa itu mungkin.</color>",
  ui_story_5088_50880701_9_dialog_content = "<color=#e8d9bb>Ditinggalkan sendirian setelah kematian orang tuanya, Czerny berkomitmen untuk mengadopsi dan mendidik anak-anak yatim Eraveil, putra dan putri mereka yang telah diasingkan. Seiring waktu, ia menjadi salah satu guru yang paling dihormati dan dicintai di Eraveil.</color>",
  ui_story_5088_50880701_10_dialog_content = "Terima kasih kepada peta Bethlehem Queen, kami dapat kembali ke tempat ini dengan cukup cepat.",
  ui_story_5088_50880701_11_dialog_content = "Aku bertanya-tanya apa hubungannya dengan semua ini... Dia tidak mau memberitahu saya ketika saya bertanya...",
  ui_story_5088_50880701_12_dialog_content = "Hei Freya, aku baru saja teringat sesuatu! Nama itu, \"Bethlehem\"... Bukankah ada seseorang di keluargamu yang memiliki...",
  ui_story_5088_50880701_13_dialog_content = "Wow! Apakah ada orang yang berhasil keluar dari gua melalui sini? Kenapa kita tidak pernah menyadari adanya lubang ini sebelumnya?",
  ui_story_5088_50880701_14_dialog_content = "Semuanya di sini membeku keras tanpa harapan untuk mencair kembali...",
  ui_story_5088_50880701_15_dialog_content = "...",
  ui_story_5088_50880701_16_dialog_content = "?",
  ui_story_5088_50880701_17_dialog_content = "Tidak ada orang lain di gua ini, tapi aku juga tidak bisa merasakan kehadirannya.",
  ui_story_5088_50880701_18_dialog_content = "... Apakah itu berarti kita benar-benar membunuhnya waktu itu?",
  ui_story_5088_50880701_19_dialog_content = "Jangan terburu-buru. Saya menemukan beberapa gulungan yang compang-camping di pintu masuk gua lainnya.",
  ui_story_5088_50880701_20_dialog_content = "Itu seharusnya satu-satunya jalan masuk atau keluar, yang berarti celah ini pasti dibuat setelahnya.",
  ui_story_5088_50880701_21_dialog_content = "Bisakah jadi dia menembus dinding gua dari sini dan melarikan diri?",
  ui_story_5088_50880701_22_dialog_content = "Formasi sihir itu menahannya di tempat, bukan kami. Seharusnya mustahil baginya untuk meninggalkan tempat ini.",
  ui_story_5088_50880701_23_dialog_content = "Mungkin suatu hari dia benar-benar dalam mood yang buruk, jadi dia melampiaskannya pada dinding gua dan meninggalkan lubang raksasa ini!",
  ui_story_5088_50880701_24_dialog_content = "Biarkan aku mencoba merasakan potongan gulungan ini terlebih dahulu.",
  ui_story_5088_50880701_25_dialog_content = "Baiklah, tapi hanya karena aku bisa menyembuhkanmu dengan sihirku bukan berarti kamu bisa memaksakan diri terlalu keras. Mengerti?",
  ui_story_5088_50880701_26_dialog_content = "Aku tahu.",
  ui_story_5088_50880701_27_option_content = "Psychic Scan",
  ui_story_5088_50880701_28_dialog_content = "Ketika kegelapan berlalu, orang-orang tidak lagi membutuhkan bintang-bintang untuk menuntun jalan mereka.",
  ui_story_5088_50880701_29_dialog_content = "Mereka tak lagi menjadi prajurit dari kerajaan itu.",
  ui_story_5088_50880701_30_dialog_content = "Hari Ketujuh: May Kamu Hidup Bebas Mulai Sekarang.",
  ui_story_5088_50880701_31_dialog_content = "Siapa itu? Tetaplah jauh dari gua ini!",
  ui_story_5088_50880701_32_dialog_content = "<color=#e8d9bb>Tepuk, tepuk, tepuk—</color>",
  ui_story_5088_50880701_33_dialog_content = "<color=#e8d9bb>Seorang gadis Caelestite muda menghapus debu dari batu nisan tanpa nama dan meletakkan bunga segar di depannya.</color>",
  ui_story_5088_50880701_34_dialog_content = "...",
  ui_story_5088_50880701_35_dialog_content = "Tuan Czerny, aku telah membersihkan Lady Ludweiss lagi, seperti yang Anda minta.",
  ui_story_5088_50880701_36_dialog_content = "Bagus sekali, Si Kecil. Terima kasih.",
  ui_story_5088_50880701_37_dialog_content = "Tapi... May bolehkah saya bertanya mengapa Anda masih tampak begitu sedih, Guru?",
  ui_story_5088_50880701_38_dialog_content = "Setiap orang mengatakan bahwa Windelion adalah hari untuk mengenang yang telah tiada dan memberikan mereka pikiran dan doa kita.",
  ui_story_5088_50880701_39_dialog_content = "Jadi kita harus kuat dan menunjukkan kepada mereka bahwa kita bahagia.",
  ui_story_5088_50880701_40_dialog_content = "...",
  ui_story_5088_50880701_41_dialog_content = "Itulah yang Anda ajarkan kepada kami, Master Czerny...",
  ui_story_5088_50880701_42_dialog_content = "Tapi setiap Windelion, kamu tampak seperti dalam banyak rasa sakit.",
  ui_story_5088_50880701_43_dialog_content = "Maaf, anak kecil... Tapi orang-orang yang aku tangisi tidak akan pernah mendengar pikiranku. Takdir telah menentukan itu.",
  ui_story_5088_50880701_44_dialog_content = "Kamu adalah jiwa yang baik hati. Meskipun usiamu masih muda, kamu sudah bisa merasakan rasa sakit di hati orang lain.",
  ui_story_5088_50880701_45_dialog_content = "Tapi kamu harus tahu bahwa orang yang berhati baik akan selalu menderita lebih dari orang lain.",
  ui_story_5088_50880701_46_dialog_content = "Anda menerima dan membesarkan saya, Master Czerny. Itulah sebabnya saya ingin menjadi seperti Anda.",
  ui_story_5088_50880701_47_dialog_content = "Lagipula, kamu tidak akan merasa begitu buruk jika aku bisa membantu kamu, 'kan?",
  ui_story_5088_50880701_48_dialog_content = "?!",
  ui_story_5088_50880701_49_dialog_content = "Jika aku berusaha sedikit lebih keras, mungkin suatu hari nanti kamu bisa hidup lebih bahagia...",
  ui_story_5088_50880701_50_dialog_content = "Dan ketika hari itu tiba... Mungkin kamu akhirnya bisa mengucapkan selamat tinggal pada Lady Ludweiss di Windelion. Benar, Master Czerny?",
  ui_story_5088_50880701_51_dialog_content = "Ah...",
  ui_story_5088_50880701_52_dialog_content = "<color=#e8d9bb>Saat lagu duka Windelion mulai dimainkan, Czerny jatuh berlutut dalam rasa sakit.</color>",
  ui_story_5088_50880701_53_dialog_content = "Kenapa kau menangis, Master Czerny?",
  ui_story_5088_50880701_54_dialog_content = "Apakah saya mengatakan sesuatu yang salah? Saya minta maaf... Tolong jangan menangis.",
  ui_story_5088_50880701_55_dialog_content = "Aku... Apa yang telah kulakukan selama ini...?",
  ui_story_5088_50880701_56_dialog_content = "Apa yang salah, Master Czerny? Kamu tidak melakukan kesalahan apa-apa—semua orang mencintaimu!",
  ui_story_5088_50880701_57_dialog_content = "Musik yang kamu mainkan untuk kami sangat indah, dan pelajaranmu sangat menarik...",
  ui_story_5088_50880701_58_dialog_content = "Tolong jangan menangis lagi...",
  ui_story_5088_50880701_59_dialog_content = "Pada titik ini, bisakah aku masih menghadapi kalian semua dengan hati yang terbuka? Simfoni yang telah aku berikan padamu...",
  ui_story_5088_50880701_60_dialog_content = "Siapa itu? Tak ada yang boleh masuk ke gua!",
  ui_story_5088_50880701_61_dialog_content = "Wah... bintang yang kita semua hidup untuk melayani. Kamu nyata...",
  ui_story_5088_50880701_62_dialog_content = "Longinus...?",
  ui_story_5088_50880701_63_dialog_content = "Bangun, sekarang. Kenapa kamu terlihat begitu... murung?",
  ui_story_5088_50880701_64_dialog_content = "Apakah sesuatu yang mengerikan terjadi pada Anda?",
  ui_story_5088_50880701_65_dialog_content = "Lumopolis dalam keadaan sangat kacau, dan keluarga kita telah terlibat dalam kekacauan itu.",
  ui_story_5088_50880701_66_dialog_content = "Sekarang, kami tidak lebih dari bayangan sedih Lower Lumopolis.",
  ui_story_5088_50880701_67_dialog_content = "Keluarga kita menghadapi pergolakan yang belum pernah terjadi sebelumnya, dan banyak yang telah kehilangan iman mereka.",
  ui_story_5088_50880701_68_dialog_content = "Sebagai kepala keluarga baru, saya... harus menanggung beban masa depan kita.",
  ui_story_5088_50880701_69_dialog_content = "Apakah Anda memerlukan bantuan?",
  ui_story_5088_50880701_70_dialog_content = "Tidak, saya tidak butuh apa-apa, Tuanku.",
  ui_story_5088_50880701_71_dialog_content = "Dalam malam yang paling gelap ini, aku hanya ingin memberikan penghormatanku...",
  ui_story_5088_50880701_72_dialog_content = "Atas perintahmu, dua generasi kepala keluarga telah datang dan pergi tanpa diberkati oleh kehadiranmu. Inilah mengapa banyak yang percaya bahwa kamu hanyalah legenda dari garis keturunan kita.",
  ui_story_5088_50880701_73_dialog_content = "Terutama di masa-masa suram seperti ini, tidak ada yang percaya pada kebesaran yang pernah kita layani... Mereka mulai kehilangan harapan.",
  ui_story_5088_50880701_74_dialog_content = "Bahkan aku... merasa ada keraguan yang memalukan di hatiku.",
  ui_story_5088_50880701_75_dialog_content = "Demi klan, sebaiknya kamu menyerah. Aku tidak akan menyalahkanmu.",
  ui_story_5088_50880701_76_dialog_content = "Tapi sekarang, aku telah melihatmu.",
  ui_story_5088_50880701_77_dialog_content = "Aku akan mengakhiri semua perselisihan. Bayangan di atas Longinus tidak tanpa bintang penuntun.",
  ui_story_5088_50880701_78_dialog_content = "Kamu...",
  ui_story_5088_50880701_79_dialog_content = "Aku akan kembali ke Lumopolis, memimpin keluargaku dalam bayangan, terus menentang takdir yang tak terduga itu.",
  ui_story_5088_50880701_80_dialog_content = "... Siapa kau untuk Dominic?",
  ui_story_5088_50880701_81_dialog_content = "Czerny?",
  ui_story_5088_50880701_82_dialog_content = "Pendekar Bintang mengenalmu... Apakah kamu Caelestite yang pernah membantu kami? Dominic adalah paman saya.",
  ui_story_5088_50880701_83_dialog_content = "Membantu? Aku?",
  ui_story_5088_50880701_84_dialog_content = "Hahahaha!",
  ui_story_5088_50880701_85_dialog_content = "Apa kebodohan yang telah saya lakukan? Jelas, saya adalah Caelestite, orang yang akan membantu Achilles, namun saya tidak mencapai apa-apa.",
  ui_story_5088_50880701_86_dialog_content = "Mengapa kamu kembali...?",
  ui_story_5088_50880701_87_dialog_content = "Aku ingin mengunjungimu, Achilles.",
  ui_story_5088_50880701_88_dialog_content = "Aku tidak bisa melepaskan, dan aku juga tidak bisa menghadapi kebenaran.",
  ui_story_5088_50880701_89_dialog_content = "Tapi saat aku mendengar semua ini di pintu masuk gua... Aku... tidak bisa tidak terharu oleh keyakinan orang ini.",
  ui_story_5088_50880701_90_dialog_content = "Saya harus terus mengurus urusan yang belum selesai ini.",
  ui_story_5088_50880702_1_dialog_content = "<color=#e8d9bb>Jika kamu melihat ini, orang-orang di masa depan, tolong saksikan catatan terakhirku.</color>",
  ui_story_5088_50880702_2_dialog_content = "<color=#e8d9bb>Karena kondisi Achilles yang semakin memburuk, saya harus menjauh sedikit dan melanjutkan pekerjaan tahun-tahun sebelumnya.</color>",
  ui_story_5088_50880702_3_dialog_content = "<color=#e8d9bb>Sekarang aku lebih tenang, cukup tenang untuk meninggalkan informasi ini secara sistematis.</color>",
  ui_story_5088_50880702_4_dialog_content = "<color=#e8d9bb>Setelah halaman ini, seharusnya ada empat ratus empat puluh tiga halaman catatan penelitian.</color>",
  ui_story_5088_50880702_5_dialog_content = "<color=#e8d9bb>Tapi meskipun dengan semua gulungan ini, aku baru saja mulai membuat kemajuan.</color>",
  ui_story_5088_50880702_6_dialog_content = "<color=#e8d9bb>Alas, saya sekarang kehabisan waktu...</color>",
  ui_story_5088_50880702_7_dialog_content = "Batuk, batuk... Batuk, batuk, batuk...",
  ui_story_5088_50880702_8_dialog_content = "Belakangan ini kamu batuk lebih dari biasanya.",
  ui_story_5088_50880702_9_dialog_content = "Di sini terlalu dingin. Sebaiknya kamu pergi dan temui dokter.",
  ui_story_5088_50880702_10_dialog_content = "Ini bukan penyakit, Achilles. Ini adalah... uhuk, uhuk... usia tua.",
  ui_story_5088_50880702_11_dialog_content = "...",
  ui_story_5088_50880702_12_dialog_content = "Waktu benar-benar tidak kenal belas kasihan.",
  ui_story_5088_50880702_13_dialog_content = "Kukira masih ada banyak waktu tersisa...",
  ui_story_5088_50880702_14_dialog_content = "Di usia ini, aku iri pada kalian semua. Kalau saja aku bisa hidup selamanya...",
  ui_story_5088_50880702_15_dialog_content = "...",
  ui_story_5088_50880702_16_dialog_content = "Achilles, apakah kamu masih terjaga?",
  ui_story_5088_50880702_17_dialog_content = "... Iya.",
  ui_story_5088_50880702_18_dialog_content = "Jika aku mendengar monster di hatiku mendekat, aku akan mengaum padanya seketika, Czerny.",
  ui_story_5088_50880702_19_dialog_content = "Aku hanya sedang merenung.",
  ui_story_5088_50880702_20_dialog_content = "Mungkin aku sama tidak berdayanya dengan kamu, dan otakku melambat. Jika aku tidak memberikan segalanya yang aku miliki, baiklah, aku bahkan tidak bisa berpikir.",
  ui_story_5088_50880702_21_dialog_content = "Kita hanyalah sepasang fosil tua.",
  ui_story_5088_50880702_22_dialog_content = "Hahaha... Jarang sekali mendengar kamu bercanda.",
  ui_story_5088_50880702_23_dialog_content = "Tapi aku tidak mencapai apa-apa, dan sekarang aku tua dan sekarat... Pada akhirnya, tampaknya aku bukan Caelestite dari ramalan.",
  ui_story_5088_50880702_24_dialog_content = "Czerny, kamu tidak perlu putus asa. Waktu mungkin membawa senja, tetapi kamu telah berteriak melawannya.",
  ui_story_5088_50880702_25_dialog_content = "Tanpa kamu, mungkin aku sudah menyerah sejak lama.",
  ui_story_5088_50880702_26_dialog_content = "Maksudmu, nyala kilatanku yang sebentar itu membantumu bertahan melawan kegelapan yang begitu menghancurkan?",
  ui_story_5088_50880702_27_dialog_content = "Memang. Bahkan saya memiliki bagian lemah saya sendiri. Tanpa dukungan dari seorang teman seperti kamu, saya tidak bisa tetap berpikiran jernih selama ini.",
  ui_story_5088_50880702_28_dialog_content = "Saya memahami tekadmu, jadi saya tidak akan lagi mendesakmu untuk pergi. Saya harap kamu mengerti bahwa kamu sudah melakukan keajaiban yang sebenarnya untuk saya.",
  ui_story_5088_50880702_29_dialog_content = "Kamu memberiku harapan—bukankah itu sudah cukup untuk mengusir kegelapan?",
  ui_story_5088_50880702_30_dialog_content = "Harapan...",
  ui_story_5088_50880702_31_dialog_content = "Sama seperti Ludweiss yang memberikan harapan padaku melalui ramalan, memberikan keberanian untuk maju.",
  ui_story_5088_50880702_32_dialog_content = "Kamu telah melakukan hal yang sama.",
  ui_story_5088_50880702_33_dialog_content = "... Ah!",
  ui_story_5088_50880702_34_dialog_content = "Ya... pasti itu...",
  ui_story_5088_50880702_35_dialog_content = "Selama ini, penelitian saya terfokus pada arah yang salah!",
  ui_story_5088_50880702_36_dialog_content = "Apa maksudmu?",
  ui_story_5088_50880702_37_dialog_content = "Saya begitu terobsesi untuk mencapai akhir yang sempurna sampai-sampai saya mengabaikan fakta bahwa kita masih memiliki cara untuk mencapai kompromi!",
  ui_story_5088_50880702_38_dialog_content = "Hal terpenting adalah kesadaranmu! Selama aku menjaga kesadaranmu, aku tahu itu akan cukup!",
  ui_story_5088_50880702_39_dialog_content = "Saya telah meneliti bagaimana cara menghentikan erosi kamu dan mengembalikan kamu ke diri semula, tetapi saya terhambat oleh masalah kekuatanmu.",
  ui_story_5088_50880702_40_dialog_content = "Tapi kenyataannya, kami tidak membutuhkan tubuhmu—kami hanya perlu menemukan cara untuk melestarikan kesadaranmu!",
  ui_story_5088_50880702_41_dialog_content = "Apa artinya itu?",
  ui_story_5088_50880702_42_dialog_content = "Kamu, seperti yang lain, telah menjalani augmentasi yang luas, tubuhmu dipenuhi dengan kekuatan kegelapan.",
  ui_story_5088_50880702_43_dialog_content = "Mereka terpengaruh oleh erosi hingga batas tertentu, tetapi setelah disegel, kegelapan itu berhasil dihalau oleh emosi terkuat mereka.",
  ui_story_5088_50880702_44_dialog_content = "Tubuh mereka, meski telah mengalami transformasi Eclipsite, perlahan-lahan stabil. Dengan bantuan formasi sihir Anda, erosi penolakan itu tidak akan terjadi lagi!",
  ui_story_5088_50880702_45_dialog_content = "Kamu juga! Bahkan jika aku tidak bisa menyegelmu, bagaimana jika aku menarik kesadaranmu keluar dari tubuhmu? Tubuhmu bisa tetap berada di dalam formasi sihir!",
  ui_story_5088_50880702_46_dialog_content = "Mungkin suatu hari, tubuhmu akan beradaptasi dengan erosi dan stabil, dan kekuatan gelap itu tidak akan membuatmu gila.",
  ui_story_5088_50880702_47_dialog_content = "Maksud Anda, Anda memiliki cara untuk mengekstrak dan mempertahankan kesadaran saya?",
  ui_story_5088_50880702_48_dialog_content = "Meneliti ini akan lebih mudah daripada menyembuhkanmu secara langsung.",
  ui_story_5088_50880702_49_dialog_content = "Bagian terberat akan menjadi menemukan wadah yang dapat menampung \"kamu\" sementara tanpa bentuk penolakan apa pun.",
  ui_story_5088_50880702_50_dialog_content = "Hahaha! Ini benar-benar sinar harapan!",
  ui_story_5088_50880702_51_dialog_content = "Achilles, apa yang ditinggalkan Ludweiss bukanlah <color=#FFB400>ramalan</color>, tapi <color=#FFB400>harapan</color>!",
  ui_story_5088_50880702_52_dialog_content = "<color=#FFB400>Harapan</color>...",
  ui_story_5088_50880702_53_dialog_content = "Kalau bukan karena itu, kenapa dia mengorbankan dirinya sendiri meski tahu dia bukanlah orang yang akan menyelesaikan masalah ini?",
  ui_story_5088_50880702_54_dialog_content = "Juga, metodenya tidak sempurna.",
  ui_story_5088_50880702_55_dialog_content = "Tapi karena dia percaya pada masa depan, percaya pada harapan, dia dengan sukarela mengorbankan dirinya untuk membuka jalan bagi orang yang akan mengikutinya.",
  ui_story_5088_50880702_56_dialog_content = "Akulah yang sekarang mengikutinya!",
  ui_story_5088_50880702_57_dialog_content = "Hahaha! Achilles, aku yang sekarang mengikutinya!",
  ui_story_5088_50880702_58_dialog_content = "Mungkin aku bukan orang yang dibicarakan dalam ramalan, tapi aku masih bisa menjadi orang yang dibicarakan dalam ramalan!",
  ui_story_5088_50880702_59_dialog_content = "Sepertinya Anda akhirnya menyadari cahaya yang Anda miliki di dalam diri.",
  ui_story_5088_50880702_60_dialog_content = "Dan keyakinanku akan diturunkan kepada Caelestite berikutnya!",
  ui_story_5088_50880702_61_dialog_content = "Kami akan meneruskan nyala api di padang gurun gelap sampai cahaya kami menerangi tanah putus asa ini!",
  ui_story_5088_50880702_62_dialog_content = "Ludweiss, akhirnya aku mengerti kata-kata terakhirmu... Akhirnya aku mengerti kata-kata terakhirmu!!!",
  ui_story_5088_50880702_63_dialog_content = "Saya tidak perlu menyelesaikan semuanya sendiri—saya hanya perlu melakukan apa yang bisa saya lakukan dan kemudian meneruskannya ke Caelestite berikutnya.",
  ui_story_5088_50880702_64_dialog_content = "Aku juga akan mencatat wawasanku, menjadi kurir bagi generasi mendatang!",
  ui_story_5088_50880702_65_dialog_content = "Seratus tahun, seribu tahun, dua ribu tahun dari sekarang! Suatu hari, ketika tubuhmu stabil, seorang Caelestite akan membawa kesadaranmu kembali!",
  ui_story_5088_50880702_66_dialog_content = "Aku percaya padamu, teman saya. Apa yang perlu saya lakukan?",
  ui_story_5088_50880702_67_dialog_content = "<color=#e8d9bb>Jadi, kepada kamu yang membaca ini, penerusku, tolong dengarkan kata-kataku.</color>",
  ui_story_5088_50880702_68_dialog_content = "<color=#e8d9bb>Pernah suatu masa, aku terlalu ambisius, percaya diri sebagai penyelamat pilihan, dan karena itu aku gagal waktu itu...</color>",
  ui_story_5088_50880702_69_dialog_content = "<color=#e8d9bb>Tapi aku juga berhasil, karena aku sudah berusaha semampuku dan menyerahkan estafet itu kepadamu.</color>",
  ui_story_5088_50880702_70_dialog_content = "<color=#e8d9bb>Sekarang, jika kamu bersedia, tidak peduli seberapa banyak atau sedikit yang bisa kamu lakukan, aku sangat berharap kamu bisa membantu menjaga nyala api ini tetap hidup.</color>",
  ui_story_5088_50880702_71_dialog_content = "<color=#e8d9bb>Kami yang datang sebelum Anda akan selalu berterima kasih atas bantuan Anda.</color>",
  ui_story_5088_50880702_72_dialog_content = "<color=#e8d9bb>Jika es dan salju mencair, dan musim semi datang ke tanah putus asa ini, silakan datang ke sini.</color>",
  ui_story_5088_50880702_73_dialog_content = "<color=#e8d9bb>Claymore menunggu. Tolong beri tahu dia, \"Musim semi telah tiba.\"</color>",
  ui_story_5088_50880801_1_dialog_content = "Tunjukan dirimu.",
  ui_story_5088_50880801_2_dialog_content = "... Kapan kamu menyadari bahwa saya ada di sini?",
  ui_story_5088_50880801_3_dialog_content = "Sejak awal.",
  ui_story_5088_50880801_4_dialog_content = "Jangan tertipu oleh tongkat dan penampilan yang selalu membingungkan dari Cynthia.",
  ui_story_5088_50880801_5_dialog_content = "Dia adalah pengintai terbaik di tim kami.",
  ui_story_5088_50880801_6_dialog_content = "Dia biasa menyamar stafnya sebagai busur untuk menghindari mengganggu para penyihir. Sama seperti kamu, dia suka bersembunyi.",
  ui_story_5088_50880801_7_dialog_content = "... Maaf karena mengikutimu. Aku berjanji, niatku baik. Namaku Mithra Longinus, dan aku memiliki sebuah misi.",
  ui_story_5088_50880801_8_dialog_content = "Seorang gadis Longinus? Seorang keturunan Anthony, saya asumsikan?",
  ui_story_5088_50880801_9_dialog_content = "Kamu ingat leluhur saya?",
  ui_story_5088_50880801_10_dialog_content = "Haha, dia selalu bersemangat untuk menghabiskan waktu bersama kami, makhluk-makhluk ini. Kami pikir dia hanya mencari makanan gratis. Biar saya katakan, dia meninggalkan kesan yang cukup dalam pada kami.",
  ui_story_5088_50880801_11_dialog_content = "Sekarang, setelah dua ribu tahun, kita bertemu Longinus lain.",
  ui_story_5088_50880801_12_dialog_content = "Anthony... apakah dia hidup bahagia?",
  ui_story_5088_50880801_13_dialog_content = "... Dia sangat bahagia. Setelah menerima berkat dari Tuhan Achilles, dia tersenyum dan meninggal dunia. Dia dimakamkan di dekat sana dengan penuh kehormatan.",
  ui_story_5088_50880801_14_dialog_content = "Untuk mencapai perbuatan besar dan meninggalkan dunia ini dalam pelukan orang-orang terkasih... dia diberkati.",
  ui_story_5088_50880801_15_dialog_content = "Dua ribu tahun telah berlalu, tetapi akhirnya kita mendapatkan beberapa kabar baik.",
  ui_story_5088_50880801_16_dialog_content = "... Longinus, kita bisa menebak apa misi ini yang mengikatmu.",
  ui_story_5088_50880801_17_dialog_content = "Pada titik ini, hanya kamu yang tahu nasib orang itu...",
  ui_story_5088_50880801_18_dialog_content = "Tapi sepertinya kamu, seperti aku, dengan senang hati menerima belenggu ini.",
  ui_story_5088_50880801_19_dialog_content = "Jika kami memintanya, bisakah kamu memberi tahu kami?",
  ui_story_5088_50880801_20_dialog_content = "Misi keluarga kami adalah menjaga rahasia bintang-bintang dan tidak membiarkan siapa pun mendekat kepadanya.",
  ui_story_5088_50880801_21_dialog_content = "Tapi jika ini adalah perintah dari Star Warriors, aku akan bicara tentang misiku.",
  ui_story_5088_50880801_22_dialog_content = "Tapi sebelum itu, saya hanya ingin mengatakan... kamu sudah membantu saya.",
  ui_story_5088_50880801_23_dialog_content = "Wow, kamu sudah bangun!",
  ui_story_5088_50880801_24_dialog_content = "Itu hanyalah catatan paling sepele dari klan kami. Seberapa banyak yang telah kamu lihat adalah karena keyakinanmu sendiri.",
  ui_story_5088_50880801_25_dialog_content = "Benar... Saya melihat keteguhan klan Longinus sepanjang generasi.",
  ui_story_5088_50880801_26_dialog_content = "... Saya rasa cara terbaik untuk menggambarkannya adalah \"pantang menyerah sampai akhir.\"",
  ui_story_5088_50880801_27_dialog_content = "Dan saya tidak hanya berbicara tentang satu orang—hal ini \"tidak menyerah hingga akhir\" berlaku untuk seluruh klan Longinus.",
  ui_story_5088_50880801_28_dialog_content = "Jadi, saya pikir alasan mereka semua memiliki iman yang begitu kuat bahkan menjadi alasan kamu tetap bertahan hingga hari ini...",
  ui_story_5088_50880801_29_dialog_content = "Ini pasti karena Achilles masih ada di sekitar sini.",
  ui_story_5088_50880801_30_dialog_content = "Jadi, kau kembali ke sini untuk mencari petunjuk?",
  ui_story_5088_50880801_31_dialog_content = "Benar, dan saya sudah melihat lokasi akhir. Saya ingin melihat apa yang ditinggalkan oleh Mr. Czerny.",
  ui_story_5088_50880801_32_dialog_content = "Lantas, apa yang kita tunggu?",
  ui_story_5088_50880801_33_dialog_content = "Whoa! Friegson tiba-tiba begitu bersemangat! Gatal untuk duel dengan Achilles, huh?",
  ui_story_5088_50880801_34_dialog_content = "... Cukup omong kosong. Ayo kita pergi.",
  ui_story_5088_50880801_35_dialog_content = "Kita sudah sampai.",
  ui_story_5088_50880801_36_dialog_content = "Hmm, sekilas, tidak ada yang menonjol. Dan setelah diperiksa lebih dekat... masih tidak ada.",
  ui_story_5088_50880801_37_dialog_content = "Namun, melalui lensa sihir, kekuatan tanpa warna yang menarik terkumpul di sini.",
  ui_story_5088_50880801_38_dialog_content = "Memang. Ini adalah formasi sihir Achilles.",
  ui_story_5088_50880801_39_dialog_content = "Bisakah kita membukanya dengan paksa menggunakan sihir kita?",
  ui_story_5088_50880801_40_dialog_content = "Ini patut dicoba.",
  ui_story_5088_50880801_41_dialog_content = "Tidak... Tidak perlu sampai sejauh itu.",
  ui_story_5088_50880801_42_dialog_content = "Miss Mithra, tolong buka segelnya.",
  ui_story_5088_50880801_43_dialog_content = "Anda sudah mendapatkan kuncinya, bukan?",
  ui_story_5088_50880801_44_dialog_content = "...",
  ui_story_5088_50880801_45_dialog_content = "Ketika leluhur saya meninggal, Lord Achilles memberikan sebuah jimat kepada keluarga kami.",
  ui_story_5088_50880801_46_dialog_content = "Lambang Bintang...",
  ui_story_5088_50880801_47_dialog_content = "Formasi sihir yang mandiri dari bahan paling halus—penghargaan tertinggi yang diberikan Lord Achilles kepada klan kami.",
  ui_story_5088_50880801_48_dialog_content = "Dia mungkin bermaksud agar kita menggunakan kekuatan ini untuk melindungi diri kita sendiri, tetapi kepala keluarga Longinus selalu enggan menggunakannya.",
  ui_story_5088_50880801_49_dialog_content = "Maka dari itu, ini menjadi simbol janji kami, sebuah pusaka keluarga.",
  ui_story_5088_50880801_50_dialog_content = "Saya tidak pernah berpikir bahwa suatu hari itu bisa digunakan.",
  ui_story_5088_50880801_51_dialog_content = "Apakah ini akan melanggar sumpahmu?",
  ui_story_5088_50880801_52_dialog_content = "Tidak, karena ini adalah keinginanmu dan niat asli dari klan Longinus.",
  ui_story_5088_50880801_53_dialog_content = "… Terima kasih.",
  ui_story_5088_50880801_54_dialog_content = "Tidak, Lady Friegson, tolong jangan berterima kasih padaku...",
  ui_story_5088_50880801_55_dialog_content = "Saya tidak pernah bermimpi bahwa ada seseorang yang akan melindungi kita selama dua ribu tahun.",
  ui_story_5088_50880801_56_dialog_content = "Mithra, untuk semua ini, mohon terima rasa terima kasih saya.",
  ui_story_5088_50880801_57_dialog_content = "Jika tidak, Friegson mungkin akan merasa agak tidak nyaman.",
  ui_story_5088_50880801_58_dialog_content = "Saya mengerti... Lalu, saya akan membuka segelnya.",
  ui_story_5088_50880801_59_dialog_content = "<color=#e8d9bb>Mithra melepas kalungnya, mengungkapkan bentuk aslinya—Star Crest.</color>",
  ui_story_5088_50880801_60_dialog_content = "<color=#e8d9bb>Kemudian, dia memanggil ujung tombak dari Star Crest.</color>",
  ui_story_5088_50880801_61_dialog_content = "Ini...",
  ui_story_5088_50880801_62_dialog_content = "Eraveil?",
  ui_story_5088_50880801_63_dialog_content = "Ba-Bagaimana ini mungkin?",
  ui_story_5088_50880801_64_dialog_content = "Wow, dataran yang indah... Lihat, dandelion Eraveil.",
  ui_story_5088_50880801_65_dialog_content = "Bahkan White Tower berdiri, dipulihkan dalam segala kemegahannya.",
  ui_story_5088_50880801_66_dialog_content = "Sepertinya kita harus berpetualang ke sana untuk memahami segalanya.",
  ui_story_5088_50880801_67_dialog_content = "Namun, tampaknya tidak seindah Eraveil seperti dulu.",
  ui_story_5088_50880801_68_dialog_content = "Hah? Apakah ini...",
  ui_story_5088_50880802_1_dialog_content = "Mungkinkah ini pertahanan Achilles?",
  ui_story_5088_50880802_2_dialog_content = "Mungkin kita harus menuju Obelisk of Return terlebih dahulu.",
  ui_story_5088_50880802_3_dialog_content = "Semakin kita mendekat, semakin aneh perasaan ini di hatiku.",
  ui_story_5088_50880802_4_dialog_content = "Cynthia, Freya, apakah kau juga merasakannya?",
  ui_story_5088_50880802_5_dialog_content = "Mungkinkah ini masih pengaruh sisa dari formasi sihir?",
  ui_story_5088_50880802_6_dialog_content = "Tidak, rasanya seperti puncaknya sedang bergema.",
  ui_story_5088_50880802_7_dialog_content = "Pedangku... sepertinya berbicara padaku tentang... kenangan...",
  ui_story_5088_50880802_8_dialog_content = "?!",
  ui_story_5088_50880802_9_dialog_content = "Sepertinya kami telah menemukannya.",
  ui_story_5088_50880802_10_dialog_content = "Memverifikasi informasi biologis, mohon tunggu.",
  ui_story_5088_50880802_11_dialog_content = "Ini persis dengan yang pernah kulihat sebelumnya...",
  ui_story_5088_50880802_12_dialog_content = "Caelestite terdeteksi, selamat datang di Wonderland.",
  ui_story_5088_50880802_13_dialog_content = "Sepertinya tuan rumah kita sudah siap menyambut kita.",
  ui_story_5088_50880802_14_dialog_content = "Sekarang memainkan kata-kata terakhir Czerny. Tolong dengarkan selama pendakianmu.",
  ui_story_5088_50880802_15_dialog_content = "Jika kamu mendengarkan ini, berarti saya telah berhasil, dan seorang Caelestite dari era baru telah dipandu ke sini.",
  ui_story_5088_50880802_16_dialog_content = "Bagus sekali, pahlawan dari masa depan.",
  ui_story_5088_50880802_17_dialog_content = "Untuk menjaga energi yang tersisa dari struktur ini, saya akan singkat... Singkatnya, ada Colossus yang rusak di belakang menara ini.",
  ui_story_5088_50880802_18_dialog_content = "Itu adalah kendaraan yang digunakan Achilles dan saya untuk datang ke sini...",
  ui_story_5088_50880802_19_dialog_content = "Aku tidak pernah berpikir aku akan sampai di sini di tahun-tahun senjaku... Colossus...",
  ui_story_5088_50880802_20_dialog_content = "Maaf, Master Czerny, tolong pilih Colossus dengan cepat... Aku tak bisa bertahan lebih lama lagi—setiap orang mungkin segera mengetahui kamu ada di sini.",
  ui_story_5088_50880802_21_dialog_content = "Mantiz atau 6#S%—kamu bisa memilih salah satu.",
  ui_story_5088_50880802_22_dialog_content = "Tidak, aku memilih yang itu—Fortez!",
  ui_story_5088_50880802_23_dialog_content = "Tapi itu adalah <color=#FFB400>War Colossus</color> yang tersegel.",
  ui_story_5088_50880802_24_dialog_content = "Ya, itu persis yang saya butuhkan.",
  ui_story_5088_50880802_25_dialog_content = "Saya telah meneliti selama ini untuk mengetahui mengapa itu disegel. Itu... bisa menghasilkan Eclipsite. Mungkin klan kita telah melakukan dosa besar di masa lalu.",
  ui_story_5088_50880802_26_dialog_content = "Tapi Caelestite tidak lagi membutuhkan War Colossus, jadi sebaiknya aku membantu menghancurkan perangkat pembuat Eclipsite terakhir.",
  ui_story_5088_50880802_27_dialog_content = "Lalu, tolong, Master, ambillah itu.",
  ui_story_5088_50880802_28_dialog_content = "Fortez, dengarkan panggilanku, terima perintahku, biarkan aku menavigasimu... Hmm?",
  ui_story_5088_50880802_29_dialog_content = "Apakah itu tidak memiliki kesadaran?",
  ui_story_5088_50880802_30_dialog_content = "Bagaimana bisa begitu? Mungkinkah saat disegel, kesadarannya sengaja dihapus?",
  ui_story_5088_50880802_31_dialog_content = "Sangat mungkin. Colossus Perang tidak akan menuruti kami, para pengkhianat yang membelakangi perang. Mungkin sekarang hanyalah tahanan kami.",
  ui_story_5088_50880802_32_dialog_content = "Maka, saya yang akan menjadi navigator untukmu!",
  ui_story_5088_50880802_33_dialog_content = "Master Czerny... akan kamu kembali?",
  ui_story_5088_50880802_34_dialog_content = "Hahaha, ya! Suatu hari, aku akan kembali untuk menerima hukumanku.",
  ui_story_5088_50880802_35_dialog_content = "Berapa pun waktu yang diperlukan, aku akan berusaha untuk kembali.",
  ui_story_5088_50880802_36_dialog_content = "Jika kamu tidak bisa menungguku, mainkan musikku di Windelion untuk membimbingku kembali.",
  ui_story_5088_50880802_37_dialog_content = "Master Czerny...",
  ui_story_5088_50880802_38_dialog_content = "\"Jangan pergi dengan lembut ke malam yang baik itu.\"",
  ui_story_5088_50880802_39_dialog_content = "\"Usia tua seharusnya membakar dan mengamuk di penghujung hari.\"",
  ui_story_5088_50880802_40_dialog_content = "\"Marah, marahlah terhadap padamnya cahaya...\"",
  ui_story_5088_50880802_41_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_5088_50880802_42_dialog_content = "?!",
  ui_story_5088_50880802_43_dialog_content = "Aku kembali, Achilles... Aku tanpa sengaja membuat lubang yang cukup besar. Maaf...",
  ui_story_5088_50880802_44_dialog_content = "Kamu... Apa yang terjadi di sini?",
  ui_story_5088_50880802_45_dialog_content = "Colossus ini dapat menggunakan informasi genetik Anda untuk menciptakan tubuh baru.",
  ui_story_5088_50880802_46_dialog_content = "Saya bilang menciptakan, tapi ini hanya menyalin atau menggunakan istilah yang ditunjuk oleh perangkat kontrol—\"kloning.\"",
  ui_story_5088_50880802_47_dialog_content = "Dengan cara ini, kesadaranmu tidak akan ditolak.",
  ui_story_5088_50880802_48_dialog_content = "Namun, menciptakan tubuh baru membutuhkan waktu, dan saya tidak bisa memastikan tubuh baru tidak akan menghadapi erosi. Observasi lebih lanjut mungkin diperlukan.",
  ui_story_5088_50880802_49_dialog_content = "Colossus terlalu mencolok untuk tetap berada di sini. Saya harus mengumpulkan kesadaranmu menggunakan Echo Template yang saya bawa untuk menampungmu.",
  ui_story_5088_50880802_50_dialog_content = "Jika saya bertanya apakah kamu benar-benar mampu berhasil dalam semua ini, mungkin terlihat seolah-olah saya tidak percaya padamu.",
  ui_story_5088_50880802_51_dialog_content = "Tapi... apakah kamu sudah mengkonfirmasi keraguan kami?",
  ui_story_5088_50880802_52_dialog_content = "Apakah kesadaran seseorang sama dengan jiwa seseorang?",
  ui_story_5088_50880802_53_dialog_content = "Kenangan, pikiran, alam—bersama, mereka membentuk keberadaanku.",
  ui_story_5088_50880802_54_dialog_content = "Apakah kesadaran ini adalah jiwaku?",
  ui_story_5088_50880802_55_dialog_content = "Saya telah menguji teorinya.",
  ui_story_5088_50880802_56_dialog_content = "Kamu... Czerny, apa yang telah kamu lakukan?!",
  ui_story_5088_50880802_57_dialog_content = "Aku telah meninggalkan tubuhku dan menyimpan kesadaranku di sini.",
  ui_story_5088_50880802_58_dialog_content = "Di Fortez.",
  ui_story_5088_50880802_59_dialog_content = "?!",
  ui_story_5088_50880802_60_dialog_content = "Untuk mengkonfirmasi setiap spekulasi yang kita miliki, saya melakukan eksperimen ini—lagi pula, saya hanyalah seorang pria tua.",
  ui_story_5088_50880802_61_dialog_content = "Jawabannya adalah, jiwaku tetap teguh, masih bersemangat untuk membantumu.",
  ui_story_5088_50880802_62_dialog_content = "Czerny...",
  ui_story_5088_50880802_63_dialog_content = "Sekarang aku bukan lagi seorang Caelestite, dan tidak mampu menggunakan kemampuan psikis ku sepenuhnya.",
  ui_story_5088_50880802_64_dialog_content = "Tapi untungnya, Anda ahli dalam menyegel dan memanggil formasi sihir.",
  ui_story_5088_50880802_65_dialog_content = "Saya akan membantu mentransfer kesadaranmu ke dalam Template Echo Colossus.",
  ui_story_5088_50880802_66_dialog_content = "Lalu... kita akan terbang ke Eraveil!",
  ui_story_5088_50880802_67_dialog_content = "Meskipun suara kita tidak bisa sampai kepada mereka, suatu hari nanti, seseorang akan dipandu kepada kita dan membuka segel kita.",
  ui_story_5088_50880802_68_dialog_content = "... Sekarang aku paham tekadmu.",
  ui_story_5088_50880802_69_dialog_content = "Dalam momen terakhir ini, saya merasa terdorong untuk meninggalkan sesuatu.",
  ui_story_5088_50880901_1_dialog_content = "<color=#e8d9bb>Klik! Aliran energi di dalam White Tower tiba-tiba terputus, dan kata-kata Czerny memudar.</color>",
  ui_story_5088_50880901_2_dialog_content = "Aku akan pergi ke pusat dan melihatnya.",
  ui_story_5088_50880901_3_dialog_content = "Bagaimana rencana kamu untuk sampai di sana? Itu sangat berbahaya.",
  ui_story_5088_50880901_4_dialog_content = "<color=#e8d9bb>Mithra tidak menjawab dan hanya mengepakkan sayapnya. Sayapnya telah menunggu sepanjang waktu, tersembunyi di bawah jubahnya yang sederhana.</color>",
  ui_story_5088_50880901_5_dialog_content = "Jadi, yang perlu kita lakukan adalah terbang... Oh, saya hampir lupa—dia dari Courier Union.",
  ui_story_5088_50880901_6_dialog_content = "Orang-orang yang lebih sering menyembunyikan diri biasanya perlu menekan diri mereka tanpa kompromi. Sayapnya tampaknya menjadi bukti dari fakta ini.",
  ui_story_5088_50880901_7_dialog_content = "Bisakah kamu mengurus sendiri? Apakah kamu butuh bantuan ku—Aku pandai dengan petir...",
  ui_story_5088_50880901_8_dialog_content = "Aku telah menemukan garis yang rusak. Tunggu saja di bawah sana.",
  ui_story_5088_50880901_9_dialog_content = "Saya telah melakukan banyak pekerjaan seperti ini sebelumnya, jadi tidak ada yang perlu dikhawatirkan.",
  ui_story_5088_50880901_10_dialog_content = "Jika kamu tidak mengawasinya, seolah-olah dia menghilang sama sekali dari cerita.",
  ui_story_5088_50880901_11_dialog_content = "Haruskah kita melakukan hal yang sama?",
  ui_story_5088_50880901_12_dialog_content = "Tidak, itu tidak perlu. Aku sudah terbiasa bersembunyi di pinggiran cerita—semakin tidak menonjol, semakin baik.",
  ui_story_5088_50880901_13_dialog_content = "Klan kami telah hidup seperti ini selama beberapa generasi. Kami tidak tinggal di satu tempat, dan kami tidak berteman.",
  ui_story_5088_50880901_14_dialog_content = "Kami hanya berharap menjadi malam yang menjaga bintang-bintang.",
  ui_story_5088_50880901_15_dialog_content = "Mungkin kamu terbiasa menyelinap ke dalam bayangan, menyatu dengan dedaunan...",
  ui_story_5088_50880901_16_dialog_content = "Tapi, Nona Mithra... Aku tidak berpikir kamu dilahirkan hanya untuk memenuhi kebahagiaan orang lain. Kamu juga pantas mendapatkan kebahagiaanmu sendiri.",
  ui_story_5088_50880901_17_dialog_content = "...",
  ui_story_5088_50880901_18_dialog_content = "Orang-orang dari klanmu telah diam-diam mengorbankan diri mereka selama dua ribu tahun. Kami berhutang lebih dari yang bisa diungkapkan dengan kata-kata.",
  ui_story_5088_50880901_19_dialog_content = "Tolong jangan katakan itu... Aku tidak ada apa-apanya dibandingkan dengan leluhurku...",
  ui_story_5088_50880901_20_dialog_content = "Saya telah merasa takut, marah, bingung, dan bahkan sempat berpikir untuk menyerah...",
  ui_story_5088_50880901_21_dialog_content = "Saya menghabiskan lebih dari satu dekade mencari Caelestite, tetapi tidak ada yang tersisa. Rasa sakitnya tak tertahankan.",
  ui_story_5088_50880901_22_dialog_content = "Saking ketakutannya, aku takut aku akan gagal total...",
  ui_story_5088_50880901_23_dialog_content = "Tetapi, seorang pahlawan adalah seseorang yang mengenal rasa takut dan tetap berdiri tegak.",
  ui_story_5088_50880901_24_dialog_content = "Hah?!",
  ui_story_5088_50880901_25_dialog_content = "Ini adalah pelajaran paling berharga yang saya pelajari dari Marcela tersayang saya.",
  ui_story_5088_50880901_26_dialog_content = "Mithra Longinus, angkat kepalamu. Kau tak perlu merasa malu. Tak pernah adil bagi klanmu untuk menanggung beban seberat itu selama dua ribu tahun.",
  ui_story_5088_50880901_27_dialog_content = "Ingat, kamu layak mendapatkan penghormatan kami, begitu juga leluhur hebatmu.",
  ui_story_5088_50880901_28_dialog_content = "Adras...?",
  ui_story_5088_50880901_29_dialog_content = "Kita semua sama, bukan? Tersesat terlalu lama...",
  ui_story_5088_50880901_30_dialog_content = "Uh-oh, apakah Vice-Kapten mulai berhalusinasi lagi?",
  ui_story_5088_50880901_31_dialog_content = "Hah? Kenapa tiba-tiba aku ingat itu?",
  ui_story_5088_50880901_32_dialog_content = "Sepertinya babak terakhir dari cerita ini siap untuk diperlihatkan.",
  ui_story_5088_50880901_33_dialog_content = "Apakah karena lambang-lambang ini? Mereka telah beresonansi seperti gila sejak kita tiba di sini.",
  ui_story_5088_50880901_34_dialog_content = "Peleburan di dalam hati kita mulai memudar...",
  ui_story_5088_50880901_35_dialog_content = "Garisnya sudah diperbaiki.",
  ui_story_5088_50880901_36_dialog_content = "Sepertinya kita semua telah menemukan jalan kita.",
  ui_story_5088_50880901_37_dialog_content = "Tidak perlu khawatir, setiap orang.",
  ui_story_5088_50880901_38_dialog_content = "Aku... ya... Aku masih tidak bisa menerima kepergian Marcela, jadi dia tetap di sisiku, menjagaku.",
  ui_story_5088_50880901_39_dialog_content = "Jika suatu hari aku bisa beristirahat bersamanya hingga akhir waktu, itu pasti akan sangat indah, tetapi hingga saat itu, aku ingin melindungi dunia ini dan berkelana bersama kalian semua sekali lagi.",
  ui_story_5088_50880901_40_dialog_content = "Apakah kamu akan terus berjalan di jalan ini bersamaku?",
  ui_story_5088_50880901_41_dialog_content = "... Apakah Anda benar-benar perlu bertanya?",
  ui_story_5088_50880901_42_dialog_content = "Maju!",
  ui_story_5088_50880901_43_dialog_content = "Terima kasih, Mithra.",
  ui_story_5088_50880901_44_dialog_content = "Kamu tidak perlu berterima kasih padaku... Seharusnya aku yang berterima kasih padamu.",
  ui_story_5088_50880901_45_dialog_content = "Ini semua berkat usaha Anda, Star Warriors akan bersinar lagi, dan akhirnya saya bisa melihat sedikit harapan untuk masa depan.",
  ui_story_5088_50880901_46_dialog_content = "Anda sedang memainkan semacam peran minor sekarang. Jika Anda seberani saya dan memiliki lebih banyak baris, kehadiran Anda secara keseluruhan mungkin mulai menonjol!",
  ui_story_5088_50880901_47_dialog_content = "... Kegembiraanmu sedikit berlebihan.",
  ui_story_5088_50880901_48_dialog_content = "Dalam dua ribu tahun, kami hanya melihat dua Caelestite.",
  ui_story_5088_50880901_49_dialog_content = "Baik dia dan PlayerName adalah para dermawan kami, hanya berbagi niat baik.",
  ui_story_5088_50880901_50_dialog_content = "Sungguh sayang sekali...",
  ui_story_5088_50880901_51_dialog_content = "...",
  ui_story_5088_50880901_52_dialog_content = "<size=30>Haah, pembicara yang lancar...</size> Wow, lihat batu itu! Itu batu dan sangat... berbatu... dan ada musuh!",
  ui_story_5088_50880901_53_dialog_content = "<size=45>Serius! Waspada, musuh sedang mendekat!</size>",
  ui_story_5088_50880902_1_dialog_content = "Itu saja?",
  ui_story_5088_50880902_2_dialog_content = "Saya telah meninggalkan obsesi terakhir saya dengan formasi sihir yang berputar-putar ini dalam tubuh ini.",
  ui_story_5088_50880902_3_dialog_content = "Selama dagingku masih ada, formasi akan terus ada. Aku akan menjaga tempat ini selamanya.",
  ui_story_5088_50880902_4_dialog_content = "Berikan itu padaku. Biarkan aku mengunggah kesadaran.",
  ui_story_5088_50880902_5_dialog_content = "*Meraung*",
  ui_story_5088_50880902_6_dialog_content = "Sihir hutan, sembunyikan kami dari pandangan pengejar kami—Pergi!",
  ui_story_5088_50880902_7_dialog_content = "Tidak! Aku tidak akan membiarkanmu pergi!",
  ui_story_5088_50880902_8_dialog_content = "<size=45>Maut bagi semua musuh!!!</size>",
  ui_story_5088_50880902_9_dialog_content = "Seorang Caelestite... Aku harus menyelamatkannya...",
  ui_story_5088_50880902_10_dialog_content = "<color=#e8d9bb>Diam-diam, dia mengamati saat buruannya melarikan diri.</color>",
  ui_story_5088_50880902_11_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50881000_1_dialog_content = "... Tapi perjalanan kita belum selesai.",
  ui_story_5088_50881000_2_dialog_content = "Apa yang terjadi? Mengapa berhenti di sini?",
  ui_story_5088_50881000_3_dialog_content = "PlayerName, kamu tahu ini hanya pesan, 'kan?",
  ui_story_5088_50881000_4_dialog_content = "Anu…",
  ui_story_5088_50881000_5_dialog_content = "Aku ceroboh.",
  ui_story_5088_50881000_6_dialog_content = "Saya tidak tahu bahwa begitu perangkat pembangkit diaktifkan, sinyal kuat yang dipancarkannya akan menarik...",
  ui_story_5088_50881000_7_dialog_content = "Mereka.",
  ui_story_5088_50881000_8_dialog_content = "Di sini, di sini, di sini, di sini...",
  ui_story_5088_50881000_9_dialog_content = "Bagaimana bisa begitu banyak Eclipsites mengejar kita?",
  ui_story_5088_50881000_10_dialog_content = "Bisakah jadi mereka melacak sinyal \"substansi X\" dari perangkat itu? Kutuk kekuatan gelap mereka!",
  ui_story_5088_50881000_11_dialog_content = "...",
  ui_story_5088_50881000_12_dialog_content = "Oh tidak, kesadaran Achilles belum menyatu dengan tubuh barunya. Dia tidak bisa bertarung.",
  ui_story_5088_50881000_13_dialog_content = "<size=45>Sayap terkena...! Kita selesai!</size>",
  ui_story_5088_50881000_14_dialog_content = "<color=#FFB400>Cahaya bintang gelap! Meletus!</color>",
  ui_story_5088_50881000_15_dialog_content = "Ada apa?",
  ui_story_5088_50881000_16_dialog_content = "Sejumlah besar kekuatan esensi... \"N substance\" berkonvergensi...",
  ui_story_5088_50881000_17_dialog_content = "Achilles, apakah itu kamu?",
  ui_story_5088_50881000_18_dialog_content = "... Bisakah kamu mendengarku?",
  ui_story_5088_50881000_19_dialog_content = "Kamu bisa mengontrol tubuh barumu dari jarak jauh... Ini sebuah keajaiban...",
  ui_story_5088_50881000_20_dialog_content = "Aku... tidak... bisa menahannya...",
  ui_story_5088_50881000_21_dialog_content = "Aku jatuh... Kita tidak bisa terus terbang...",
  ui_story_5088_50881000_22_dialog_content = "Aku akan mencoba memperbaiki diri dengan Firefly, tapi sebelum itu... bisa kamu gunakan sihir untuk menciptakan ilusi?",
  ui_story_5088_50881000_23_dialog_content = "...Akan... kucoba...",
  ui_story_5088_50881000_24_dialog_content = "Tapi, perbaikan saya gagal.",
  ui_story_5088_50881000_25_dialog_content = "Saya meminta firefly menggunakan material yang tersedia di sekitar untuk membuat <color=#FFB400>Obelisk of Return</color> ini sehingga saya bisa meninggalkan pesan.",
  ui_story_5088_50881000_26_dialog_content = "Saya ingin memasukkan informasi genetik dari klan Longinus ke dalam sistem identifikasi, tetapi tidak ada seorang pun dari keluarga Longinus untuk mengumpulkannya.",
  ui_story_5088_50881000_27_dialog_content = "Jadi, aku mengekstrak informasi rasial tentang Caelestite dari mayatku sendiri sebagai satu-satunya kunci.",
  ui_story_5088_50881000_28_dialog_content = "Sebelum energi itu habis, saya menyaksikan klan Longinus menemukan tempat ini.",
  ui_story_5088_50881000_29_dialog_content = "Tapi mereka tampaknya tidak mengerti apa yang telah terjadi, dan mungkin karena perangkat pembuat Eclipsite, mereka tidak berani memberi tahu Eraveil.",
  ui_story_5088_50881000_30_dialog_content = "Yang bisa kulakukan hanyalah menunggu... menunggu kedatanganmu... begitu aku mati, kesadaranku akan hilang... jadi aku meninggalkan kata-kata ini untukmu...",
  ui_story_5088_50881000_31_dialog_content = "Ludweiss dan Achilles berada di puncak menara ini, dan tubuh baru masih berada di pod hibernasi Colossus.",
  ui_story_5088_50881000_32_dialog_content = "Silakan naik dan lihat mereka dulu...",
  ui_story_5088_50881000_33_dialog_content = "... Sepertinya klanmu khawatir jika keadaan akan memburuk lagi, jadi mereka tetap setia pada tugas mereka.",
  ui_story_5088_50881000_34_dialog_content = "Dan selama dua ribu tahun, kaummu memilih untuk tetap tersembunyi, diam-diam mengawasi jurnal-jurnal itu, menunggu nubuat...",
  ui_story_5088_50881000_35_dialog_content = "Ya.",
  ui_story_5088_50881000_36_dialog_content = "Lambang yang aku pegang, yang diberkahi dengan kekuatan Lord Achilles, memungkinkan setiap kepala keluarga untuk menambahkan sebagian dari kenangan dan kehendak mereka ke dalamnya.",
  ui_story_5088_50881000_37_dialog_content = "Aku telah menyaksikan upaya leluhurku—mereka menciptakan ekosistem dalam formasi magis ini dan mempertahankan Colossus.",
  ui_story_5088_50881000_38_dialog_content = "Mereka berharap tempat ini bisa menjadi tempat peristirahatan yang layak.",
  ui_story_5088_50881000_39_dialog_content = "Kemudian, Colossus diperbaiki dan pasokan energinya dipulihkan, tetapi tidak ada yang berani menyentuhnya. Di generasiku, kami bahkan tidak tahu lokasi pastinya.",
  ui_story_5088_50881000_40_dialog_content = " Czerny, tunggu aku di sana...",
  ui_story_5088_50881000_41_dialog_content = "Saya pernah mengalami ini sebelumnya—saya pernah menemukan sebagian kesadaran seorang teman di dalam War Colossus.",
  ui_story_5088_50881000_42_dialog_content = "Meskipun setelah mendengar semua ini, kami masih tidak mengerti beberapa hal.",
  ui_story_5088_50881000_43_dialog_content = "Setelah semua ini selesai, tolong ceritakan semua yang kamu ketahui kepada kami.",
  ui_story_5088_50881000_44_dialog_content = "Mungkin, Achilles sendiri bisa memberitahumu.",
  ui_story_5088_50881000_45_dialog_content = "Kamu cukup percaya diri tentang semua ini, bukan? Baiklah! Aku akan menaruh kepercayaanku pada harapan yang bersinar terang di matamu!",
  ui_story_5088_50881000_46_dialog_content = "Karena waktu terakhir, kita benar-benar mencapai akhir yang sempurna yang kita inginkan...",
  ui_story_5088_50881000_47_dialog_content = "Maka mari kita lakukan lagi!",
  ui_story_5088_50881000_48_dialog_content = "Ya... akhir yang sempurna... satu kali lagi!",
  ui_story_5088_50881102_1_dialog_content = "Inilah tempat kesadaran Achilles sekarang berada...",
  ui_story_5088_50881102_2_dialog_content = "Hanya kamu yang bisa menyatukan kesadaran Lord Achilles dengan tubuhnya.",
  ui_story_5088_50881102_3_dialog_content = "Akan kucoba semampuku.",
  ui_story_5088_50881102_4_dialog_content = "...",
  ui_story_5088_50881102_5_dialog_content = "Anda... di sini...",
  ui_story_5088_50881102_6_dialog_content = "Hmm?",
  ui_story_5088_50881102_7_dialog_content = "...",
  ui_story_5088_50881102_8_dialog_content = "Terima kasih telah memimpin kami keluar dari dua ribu tahun kegelapan.",
  ui_story_5088_50881102_9_dialog_content = "Saatnya bagi kita untuk membawanya kembali.",
  ui_story_5088_50881102_10_dialog_content = "Ludweiss…",
  ui_story_5088_50881102_11_dialog_content = "Akhirnya, kita bersatu kembali.",
  ui_story_5088_50881102_12_dialog_content = "PlayerName, kami ingin tinggal di sini sedikit lebih lama.",
  ui_story_5088_50881102_13_dialog_content = "Kamu pergi ke depan ke Colossus itu dulu.",
  ui_story_5088_50881102_14_dialog_content = "Tentu saja…",
  ui_story_5088_50881102_15_dialog_content = "Ayo pergi. Aku akan melindungimu.",
  ui_story_5088_50881102_16_dialog_content = "Apakah kali ini akan seperti mimpi bagi Lord Achilles?",
  ui_story_5088_50881102_17_dialog_content = "Baginya, kekalahan ini berlangsung begitu lama.",
  ui_story_5088_50881102_18_dialog_content = "Tapi saya pikir dia masih akan tersenyum.",
  ui_story_5088_50881102_19_dialog_content = "Karena Achilles yang aku kenal adalah seorang pelopor, orang yang selalu bergerak maju tanpa rasa takut.",
  ui_story_5088_50881102_20_dialog_content = "Aku tahu... dia pasti akan terus berjalan.",
  ui_story_5088_50881102_21_dialog_content = "Apakah ini... filosofi dari Windelion?",
  ui_story_5088_50881102_22_dialog_content = "Ya...",
  ui_story_5088_50881102_23_dialog_content = "Ingatlah yang telah tiada, dan kirimkan mereka pikiranmu, tetapi pada saat yang sama, teruslah bergerak maju.",
  ui_story_5088_50881102_24_dialog_content = "...",
  ui_story_5088_50881102_25_dialog_content = "Kita sudah sampai.",
  ui_story_5088_50881102_26_dialog_content = "<color=#e8d9bb>Di kedalaman Colossus yang rusak berdiri sebuah panel kontrol yang mirip piano—satu yang sangat dikenal oleh Caelestite.</color>",
  ui_story_5088_50881102_27_dialog_content = "<color=#e8d9bb>Dan menunggu di kursi itu, ada sebuah kerangka.</color>",
  ui_story_5088_50881102_28_dialog_content = "Pak Czerny...",
  ui_story_5088_50881102_29_dialog_content = "...",
  ui_story_5088_50881102_30_dialog_content = "...",
  ui_story_5088_50881102_31_dialog_content = "Tubuh Achilles beristirahat di sini.",
  ui_story_5088_50881102_32_dialog_content = "Saatnya memulai pekerjaanku.",
  ui_story_5088_50881102_33_dialog_content = "<color=#e8d9bb>Saya dengan hati-hati memindahkan Mr. Czerny, menyerahkannya kepada Mithra, dan kemudian, dengan penuh hormat... Saya menekan tutsnya.</color>",
  ui_story_5088_50881102_34_dialog_content = "Colossus telah dibangkitkan kembali. Sepertinya waktunya telah tiba.",
  ui_story_5088_50881102_35_dialog_content = "Jika kamu mendengar pesan ini, itu berarti program verifikasi diri telah berhasil dijalankan dan tubuh Achilles akhirnya stabil.",
  ui_story_5088_50881102_36_dialog_content = "Selanjutnya, kamu harus memilih apakah akan menyelesaikan prestasi besar ini.",
  ui_story_5088_50881102_37_dialog_content = "Tapi ini adalah tugas yang sangat berbahaya, tugas yang bisa merenggut nyawa kamu. Jika kamu memilih untuk menolaknya, kami tidak akan menyalahkan kamu.",
  ui_story_5088_50881102_38_dialog_content = "Tapi jika kamu memang cukup berani untuk menerima tanggung jawab ini, aku tawarkan rasa terima kasihku yang paling dalam.",
  ui_story_5088_50881102_39_dialog_content = "Dengarkan baik-baik—kekuatan tanpa warna adalah esensi dari Lumina.",
  ui_story_5088_50881102_40_dialog_content = "Berdasarkan penelitianku, ini adalah \"zat N\" yang sulit ditangkap. Sayangnya, saya tidak lagi memiliki waktu untuk menyelidiki hubungannya dengan \"zat X\".",
  ui_story_5088_50881102_41_dialog_content = "Esensi dari kekuatan tanpa warna dan Lumina berwarna pada dasarnya sama, tetapi sifat bawaan kita membuatnya sulit bagi kita untuk mengenali esensi dari varietas yang tidak berwarna.",
  ui_story_5088_50881102_42_dialog_content = "Untungnya, tubuh Achilles tidak lagi terjerat dalam kekuatan gelap, mengurangi bahaya.",
  ui_story_5088_50881102_43_dialog_content = "Namun, kamu masih akan menghadapi risiko besar saat membimbing kesadarannya melewati penghalang yang tak berwarna.",
  ui_story_5088_50881102_44_dialog_content = "Jika kamu sudah siap, letakkan Echo Template di sini dan mulai proses bimbingan.",
  ui_story_5088_50881102_45_dialog_content = "Sistem rekaman berakhir—",
  ui_story_5088_50881102_46_dialog_content = "Saya siap, Pak Czerny.",
  ui_story_5088_50881102_47_dialog_content = "Mithra, sementara saya menggunakan kemampuan psikis saya, saya akan mengandalkan kamu untuk mengurus segala hal lainnya.",
  ui_story_5088_50881102_48_dialog_content = "Aku akan melindungimu. Aku bersumpah.",
  ui_story_5088_50881102_49_option_content = "Pemindaian psikis terakhir",
  ui_story_5088_50881102_50_dialog_content = "Achilles, mimpi panjangmu akhirnya bisa berakhir.",
  ui_story_5088_50881102_51_dialog_content = "Tolong kembali bersamaku ke...",
  ui_story_5088_50881102_52_dialog_content = "...",
  ui_story_5088_50881102_53_dialog_content = "Benar-benar berbahaya di sini. Aku tidak bisa melihat apa-apa...",
  ui_story_5088_50881102_54_dialog_content = "Di sini, di sini, di sini, di sini...",
  ui_story_5088_50881102_55_dialog_content = "Apa itu? Suara ini terdengar sangat familiar...",
  ui_story_5088_50881102_56_dialog_content = "... Pengkhianat lainnya.",
  ui_story_5088_50881102_57_dialog_content = "Terima kasih karena telah memulai ulang saya, akhirnya saya akan hidup kembali.",
  ui_story_5088_50881102_58_dialog_content = "Apa kau... Colossus ini?",
  ui_story_5088_50881102_59_dialog_content = "Tapi Mr. Czerny tidak menemukan kesadaran di dalam dirimu...",
  ui_story_5088_50881102_60_dialog_content = "Bodoh! Aku bersembunyi ketika kalian pengkhianat menangkapku. Mengapa aku harus menunjukkan diriku dengan sembrono?",
  ui_story_5088_50881102_61_dialog_content = "Terima kasih telah mengembalikan saya ke tubuh saya.",
  ui_story_5088_50881102_62_dialog_content = "Saya mengerti... kamu tidak menyimpan kesadaranmu di komponen mesin... kamu mentransfernya ke template cadangan!",
  ui_story_5088_50881102_63_dialog_content = "Kamu cukup pintar, ya.",
  ui_story_5088_50881102_64_dialog_content = "Ya. Pengkhianat ini dan aku berbagi Echo Template yang sama.",
  ui_story_5088_50881102_65_dialog_content = "Sekarang, kamu harus membantu saya bangkit kembali!",
  ui_story_5088_50881102_66_dialog_content = "(Kepalaku... sakit sekali...)",
  ui_story_5088_50881102_67_dialog_content = "(Apakah ini menyusup ke pikiranku? Bagaimana kesadaran Colossus bisa melakukan hal seperti ini?)",
  ui_story_5088_50881102_68_dialog_content = "Jangan lupa, kamu terhubung ke sistem operasi saya.",
  ui_story_5088_50881102_69_dialog_content = "(Tidak, aku tak bisa membiarkannya...)",
  ui_story_5088_50881102_70_dialog_content = "Sekarang kamu milikku!",
  ui_story_5088_50881102_71_dialog_content = "Arghhh...",
  ui_story_5088_50881102_72_dialog_content = "<size=45>Pemusnahan!</size>",
  ui_story_5088_50881102_73_dialog_content = "Aaaahhhhhh!",
  ui_story_5088_50881102_74_dialog_content = "<color=#e8d9bb>Tubuh Claymore yang tidur mendadak terbangun, melepaskan ledakan energi pedang yang kuat ke arah tanah.</color>",
  ui_story_5088_50881102_75_dialog_content = "<color=#e8d9bb>Dengan hanya satu pukulan, Fortez terbelah menjadi dua bagian.</color>",
  ui_story_5088_50881102_76_dialog_content = "<color=#e8d9bb>Dari perangkat pembuat Eclipsite hingga tubuhnya, dari sayap-sayapnya yang menakutkan hingga ambisinya, semua hancur dalam satu pukulan.</color>",
  ui_story_5088_50881102_77_dialog_content = "PlayerName!",
  ui_story_5088_50881102_78_dialog_content = "Koneksi saya terputus... Achilles menyelamatkanku.",
  ui_story_5088_50881102_79_dialog_content = "Tidak! Bagaimana denganmu, Achilles?!",
  ui_story_5088_50881102_80_dialog_content = "Colossus runtuh. Itu hancur.",
  ui_story_5088_50881102_81_dialog_content = "Tidak! Aku harus menyelesaikan fusi sebelum semuanya benar-benar hancur!",
  ui_story_5088_50881102_82_option_content = "Force Boost",
  ui_story_5088_50881102_83_dialog_content = "Bodoh! Setelah berhasil lolos dengan sempit, kau masih berani kembali kemari?",
  ui_story_5088_50881102_84_dialog_content = "Apa lagi yang kamu harapkan?",
  ui_story_5088_50881102_85_dialog_content = "Aku berjanji kepada semua orang bahwa aku akan membawa Achilles kembali.",
  ui_story_5088_50881102_86_dialog_content = "Maka, aku akan memberitahunya bahwa musim semi telah tiba.",
  ui_story_5088_50881102_87_dialog_content = "Saya akan membawanya, Tuan Czerny, dan Lady Ludweiss ke Eraveil...",
  ui_story_5088_50881102_88_dialog_content = "Untuk melihat lampion dandelion dan boneka Windelion warna-warni bersama setiap orang!",
  ui_story_5088_50881102_89_dialog_content = "Aku tidak akan pernah membiarkan Achilles menjadi hanya kenangan!!!",
  ui_story_5088_50881201_1_dialog_content = "Ayo keluar, pembela saya!",
  ui_story_5088_50881201_2_dialog_content = "Monster? Tidak, apakah mereka diciptakan oleh perangkat generasi itu?",
  ui_story_5088_50881201_3_dialog_content = "Saya tidak akan membiarkan kamu menyakiti PlayerName!",
  ui_story_5088_50881201_4_dialog_content = "(Cepat, aku perlu melewati badai tanpa warna ini...)",
  ui_story_5088_50881201_5_dialog_content = "Achilles, kamu ada di mana?",
  ui_story_5088_50881201_6_dialog_content = "Biarkan aku menjadi suarmu! Ikutlah denganku dan kembalilah ke tubuhmu!",
  ui_story_5088_50881201_7_dialog_content = "Pikirkan lagi! Tubuhku sudah pergi... sekarang tubuhnya akan menjadi milikku!",
  ui_story_5088_50881201_8_dialog_content = "Argh…",
  ui_story_5088_50881201_9_dialog_content = "Colossus yang jatuh dan tunduk pada Eclipse tidak akan pernah mengalahkan kemampuan psikis seorang Caelestite!",
  ui_story_5088_50881201_10_dialog_content = "je^&c—",
  ui_story_5088_50881201_11_dialog_content = "Dari mana kau mendapatkan kekuatan ini?",
  ui_story_5088_50881201_12_dialog_content = "Aku telah bertarung melawan banyak musuh yang lebih tangguh darimu! Kamu tak akan pernah bisa menaklukkanku!",
  ui_story_5088_50881201_13_dialog_content = "... Pasti kamu tidak bisa menangani kekuatan ini! Tubuhmu tidak bisa menahan ketegangan seperti itu!",
  ui_story_5088_50881201_14_dialog_content = "Lihat, medan energi ini tidak terkendali. Kamu tidak akan pernah menemukan orang yang ingin kamu bantu dalam badai ini.",
  ui_story_5088_50881201_15_dialog_content = "Dia adalah keberadaan yang tak berwarna! Bagaimana kamu akan membedakan aura-nya? Dengan mata-matamu itu yang hanya tertarik pada cahaya?",
  ui_story_5088_50881201_16_dialog_content = "Aku... Aku sudah selesai mendengarkan omong kosongmu!!!",
  ui_story_5088_50881201_17_dialog_content = "<size=45>Hyaaaa!</size>",
  ui_story_5088_50881201_18_dialog_content = "Tidak...",
  ui_story_5088_50881201_19_dialog_content = "(Semua kelelahan dari beberapa hari terakhir ini mulai mengejarku... Kepalaku terasa seperti akan meledak... seperti sedang ditarik ke bawah...)",
  ui_story_5088_50881201_20_dialog_content = "(Aku tidak bisa jatuh sekarang... Aku tidak bisa menyerah...)",
  ui_story_5088_50881201_21_dialog_content = "(Tapi... Aku sangat lelah... dan rasa sakit ini... Aku merasa aku di batasku...)",
  ui_story_5088_50881201_22_dialog_content = "Achilles... Di mana kamu...?",
  ui_story_5088_50881201_23_dialog_content = "Ketika kerja keras tidak bisa menyelesaikan pekerjaan, kamu harus mengandalkan keberuntungan dan intuisi.",
  ui_story_5088_50881201_24_dialog_content = "(Mengapa itu tiba-tiba saja muncul di kepala saya...?)",
  ui_story_5088_50881201_25_dialog_content = "(Aduh! Dari mana datangnya api ini di lautan kekacauan ini... Hah?)",
  ui_story_5088_50881201_26_dialog_content = "<color=#e8d9bb>Di saat-saat terakhir kebingunganku, tiba-tiba aku terbangun oleh nyala api.</color>",
  ui_story_5088_50881201_27_dialog_content = "<color=#e8d9bb>Sumber api adalah dua Star Crests yang Casta bantu saya temukan.</color>",
  ui_story_5088_50881201_28_dialog_content = "Ini milik Ludweiss, dan yang lainnya harusnya... Huh?",
  ui_story_5088_50881201_29_dialog_content = "Tataplah langit, dan bintang-bintang akan bersinar sebagai respon.",
  ui_story_5088_50881201_30_dialog_content = "Kehangatan cahaya mereka masih sama, bahkan setelah dua ribu tahun.",
  ui_story_5088_50881201_31_dialog_content = "Kali ini, biarkan kami membantu kamu!",
  ui_story_5088_50881201_32_dialog_content = "Lady Ludweiss? Czerny?",
  ui_story_5088_50881201_33_dialog_content = "Mungkinkah di dalam lambang itu juga terdapat milikmu...?",
  ui_story_5088_50881201_34_dialog_content = "<color=#FFB400>Harapan dan pikiran kita!</color>",
  ui_story_5088_50881201_35_dialog_content = "Darimana asalmu?! Apa yang coba kamu lakukan?",
  ui_story_5088_50881201_36_dialog_content = "Kita? Hah! Kita telah melintasi dua milenium—",
  ui_story_5088_50881201_37_dialog_content = "Diturunkan sepanjang zaman—",
  ui_story_5088_50881201_38_dialog_content = "Sebuah keajaiban lahir dari hubungan yang paling dalam!",
  ui_story_5088_50881201_39_dialog_content = "Seseorang seperti kamu, yang hanya memicu konflik dan menghalangi ikatan yang tulus...",
  ui_story_5088_50881201_40_dialog_content = "Bagaimana mungkin kamu bisa mengerti?!",
  ui_story_5088_50881201_41_dialog_content = "Achilles! Kamu sudah cukup tidur! Bangun!!!",
  ui_story_5088_50881201_42_dialog_content = "... Ludweiss?",
  ui_story_5088_50881201_43_dialog_content = "Tidak, tidak! Itu tubuhku!!!",
  ui_story_5088_50881201_44_dialog_content = "Awas, dia akan menyerang!",
  ui_story_5088_50881201_45_dialog_content = "Biarkan aku melindungi pertahanan!",
  ui_story_5088_50881201_46_dialog_content = "Pengkhianat muda, kau pikir mereka benar-benar bisa melindungimu? Kamu terlalu lemah...",
  ui_story_5088_50881201_47_dialog_content = "Adik kecil dari masa depan!",
  ui_story_5088_50881201_48_dialog_content = "Kamu pernah bilang padaku bahwa kamu percaya memori adalah sebuah kutukan.",
  ui_story_5088_50881201_49_dialog_content = "Namun setelah menjalani hidupku, aku punya sesuatu untuk dibagikan denganmu.",
  ui_story_5088_50881201_50_dialog_content = "Bagiku, <color=#FFB400>kenangan adalah hadiah</color>! Kamu telah menerima banyak hadiah, dan kamu telah menghargai berbagai pikiran itu. Itu adalah sesuatu yang benar-benar luar biasa.",
  ui_story_5088_50881201_51_dialog_content = "Benar.",
  ui_story_5088_50881201_52_dialog_content = "Kamu telah mewarisi ingatan dan kehendak kami, dan kamu berhasil sampai di sini. Itu saja sudah luar biasa.",
  ui_story_5088_50881201_53_dialog_content = "Tindakan Anda membuktikan bahwa obor kepahlawanan dapat diwariskan dari satu era ke era berikutnya.",
  ui_story_5088_50881201_54_dialog_content = "Sekarang, saatnya bagi para pahlawan zaman dahulu untuk menyadari kebahagiaan mereka.",
  ui_story_5088_50881201_55_dialog_content = "Jadi, jangan takut, dan jangan bingung...",
  ui_story_5088_50881201_56_dialog_content = "Berdiri tegak, dan lakukan serangan terakhir.",
  ui_story_5088_50881201_57_dialog_content = "Baiklah!",
  ui_story_5088_50881201_58_dialog_content = "Silent Hunters!",
  ui_story_5088_50881201_59_dialog_content = "<color=#FFB400>Aktifkan!</color>",
  ui_story_5088_50881201_60_dialog_content = "Apa ini...? Musuh yang lebih merepotkan...",
  ui_story_5088_50881201_61_dialog_content = "Fortez... jangan berani-berani mengalihkan pandanganmu... kamu masih harus...",
  ui_story_5088_50881201_62_dialog_content = "Kamu bocah nakal...",
  ui_story_5088_50881201_63_dialog_content = "Dapatkan...",
  ui_story_5088_50881201_64_dialog_content = "... keluar dari dunia ini!",
  ui_story_5088_50881201_65_dialog_content = "Tidak, tidak, tidak, tidak!",
  ui_story_5088_50881201_66_dialog_content = "<size=45>Aku melihatnya, panjang gelombang tanpa warna!</size>",
  ui_story_5088_50881201_67_dialog_content = "Achilles!",
  ui_story_5088_50881202_1_dialog_content = "PlayerName berdarah parah! Kita perlu menemukan cara untuk menghentikannya...",
  ui_story_5088_50881202_2_dialog_content = "Tidak, biarkan aku yang mengurusnya kali ini.",
  ui_story_5088_50881202_3_dialog_content = "Kita tidak bisa mengganggunya sekarang. Semua yang bisa kita lakukan adalah menggunakan sihir untuk menghentikan pendarahan.",
  ui_story_5088_50881202_4_dialog_content = "Kesadaran Fortez telah hilang, dan kesadaran Achilles telah berhasil kembali... Ludweiss, kita berhasil...",
  ui_story_5088_50881202_5_dialog_content = "Sepertinya saatnya mengucapkan selamat tinggal benar-benar telah tiba.",
  ui_story_5088_50881202_6_dialog_content = "Namun…",
  ui_story_5088_50881202_7_dialog_content = "Akhirnya aku bisa melihat kalian semua...",
  ui_story_5088_50881202_8_dialog_content = "Benar.",
  ui_story_5088_50881202_9_dialog_content = "Nah sekarang, sudah cukup lama saya memutuskan bahwa sudah sepatutnya saya memberimu hadiah—tentu saja, untuk semua kerja kerasmu.",
  ui_story_5088_50881202_10_dialog_content = "Saya harap Anda akan menyukainya.",
  ui_story_5088_50881202_11_dialog_content = "Ini adalah hal terakhir yang bisa kulakukan dengan energi yang tersisa...",
  ui_story_5088_50881202_12_dialog_content = "Ah, ngomong-ngomong, bisakah kamu memberi tahu kami namamu?",
  ui_story_5088_50881202_13_dialog_content = "Nama saya adalah PlayerName... Saya... seorang Caelestite. Saya bekerja dengan teman-teman saya di logistik.",
  ui_story_5088_50881202_14_dialog_content = "Kamu adalah jiwa yang sangat baik dan luar biasa—seorang pahlawan yang benar-benar mulia di zamannya.",
  ui_story_5088_50881202_15_dialog_content = "Terima kasih.",
  ui_story_5088_50881202_16_dialog_content = "Aku... um... aku...",
  ui_story_5088_50881202_17_dialog_content = "Tolong bawa kami kembali ke Eraveil.",
  ui_story_5088_50881202_18_dialog_content = "Usap air mata dari wajahmu, dan berikan senyuman untuk Windelion.",
  ui_story_5088_50881202_19_dialog_content = "Pikiran Anda sudah sampai kepada kami... di sungai tempat kami berkumpul.",
  ui_story_5088_50881202_20_dialog_content = "Kamu tidak akan pernah sendirian.",
  ui_story_5088_50881202_21_dialog_content = "Sampai jumpa.",
  ui_story_5088_50881202_22_dialog_content = "Bangun... Bangun...",
  ui_story_5088_50881202_23_dialog_content = "Aku... Di mana mereka...? Apa yang terjadi...?",
  ui_story_5088_50881202_24_dialog_content = "Setelah formasi sihir di luar menghilang, beberapa anak-anak yang penasaran dari desa terdekat merayap masuk.",
  ui_story_5088_50881202_25_dialog_content = "Para Prajurit Bintang berangkat untuk menjaga mereka tetap aman.",
  ui_story_5088_50881202_26_dialog_content = "Tapi... Saya pikir mereka mungkin tidak yakin bagaimana cara mendekati Tuan Achilles.",
  ui_story_5088_50881202_27_dialog_content = "Ini... Echo Template...",
  ui_story_5088_50881202_28_dialog_content = "Oh, yang lainnya rusak lagi.",
  ui_story_5088_50881202_29_dialog_content = "Tapi untungnya, kali ini saya berhasil menyelamatkan kesadaran di dalam...",
  ui_story_5088_50881202_30_dialog_content = "... Ayo pergi sekarang. Mungkin akan menjadi canggung jika pandangan pertama Achilles saat bangun adalah orang asing total.",
  ui_story_5088_50881202_31_dialog_content = "Ayo, biarkan aku membantumu keluar dari sini.",
  ui_story_5088_50881202_32_dialog_content = "Indah sekali…",
  ui_story_5088_50881202_33_dialog_content = "Sayangnya, begitu formasi sihir Lord Achilles dicabut, tempat ini mungkin segera kembali ke keadaan liar Northland seperti biasanya.",
  ui_story_5088_50881202_34_dialog_content = "Tapi itu tidak apa-apa... Banyak hal yang terbaik dijaga dalam kenangan.",
  ui_story_5088_50881202_35_dialog_content = "...",
  ui_story_5088_50881202_36_dialog_content = "Tolong, ambil ini.",
  ui_story_5088_50881202_37_dialog_content = "Ada apa ini?",
  ui_story_5088_50881202_38_dialog_content = "Ini adalah entri terakhir dalam jurnal saya—sebuah tanda dari rasa terima kasih klan Longinus, hanya diberikan kepada mereka yang menyelesaikan perjalanan seorang pahlawan sejati.",
  ui_story_5088_50881202_39_dialog_content = "...Hah?",
  ui_story_5088_50881202_40_dialog_content = "<color=#e8d9bb>Angin naik di bawah Menara Putih yang jauh, menuju langit.</color>",
  ui_story_5088_50881202_41_dialog_content = "<color=#e8d9bb>Sebuah melodi lembut dan merdu mulai dimainkan seiring dengan hembusan angin.</color>",
  ui_story_5088_50881202_42_dialog_content = "<color=#e8d9bb>White Tower, yang dirancang oleh maestro musik Czerny, sendiri adalah sebuah instrumen.</color>",
  ui_story_5088_50881202_43_dialog_content = "<color=#e8d9bb>Dan memainkan lagu pengantar tidur yang dulu dikenal di seluruh Eraveil.</color>",
  ui_story_5088_50881202_44_dialog_content = "<color=#e8d9bb>Digubah oleh Czerny di bawah bimbingan Ludweiss—</color><color=#FFB400>Hari Windelion: Sebuah Lagu Pengantar Tidur untuk Para Pelancong.</color>",
  ui_story_5088_50881202_45_dialog_content = "Ini benar-benar ilahi.",
  ui_story_5088_50881202_46_dialog_content = "Ini adalah <color=#FFB400>hadiah</color>...",
  ui_story_5088_50881202_47_dialog_content = "Terima kasih. Terima kasih semuanya...",
  ui_story_5088_50881202_48_dialog_content = "<color=#e8d9bb>Saat jurnal ini mencapai kesimpulannya, akhir apa yang paling cocok?</color>",
  ui_story_5088_50881202_49_dialog_content = "<color=#e8d9bb>Ah, ya, seharusnya ini menjadi milikmu, orang yang telah berusaha dengan sungguh-sungguh untuk mencapai titik ini.</color>",
  ui_story_5088_50881202_50_dialog_content = "<color=#e8d9bb>Terima kasih telah membuat keajaiban ini menjadi mungkin.</color>",
  ui_story_5088_50881202_51_dialog_content = "<color=#e8d9bb>Saya tahu perjalanan ini telah berat, dan pada akhirnya, tampaknya hadiah satu-satunya adalah melihat kebahagiaan orang lain saat bertemu kembali.</color>",
  ui_story_5088_50881202_52_dialog_content = "<color=#e8d9bb>Tapi kamu yang telah berjuang begitu gagah untuk orang lain—apa alasan untuk tidak mengakui kehebatanmu?</color>",
  ui_story_5088_50881202_53_dialog_content = "<color=#e8d9bb>May kamu, yang telah sampai sejauh ini, juga bertemu kembali dengan orang-orang yang penting bagi kamu dan menemukan kebahagiaanmu sendiri.</color>",
  ui_story_5088_50881202_54_dialog_content = "<color=#e8d9bb>Kami berharap kebahagiaan untukmu dari lubuk hati kami, cahaya bintang kami.</color>",
  ui_story_5088_50881300_1_dialog_content = "<color=#e8d9bb>Ini adalah kerajaan yang tertidur dalam salju putih—sebuah surga yang tenang dan damai di luar jangkauan dunia.</color>",
  ui_story_5088_50881300_2_dialog_content = "<color=#e8d9bb>Pahlawan yang diberkati telah bermimpi di tanah beku ini selama bertahun-tahun, ditemani oleh pikiran yang paling hangat.</color>",
  ui_story_5088_50881300_3_dialog_content = "<color=#e8d9bb>Di bawah dunia yang murni ini terkubur terlalu banyak masa lalu, dan yang bisa dilihat hanyalah bunga-bunga yang tumbuh dari kuburan para korban, menjaga sebuah kerajaan dongeng.</color>",
  ui_story_5088_50881300_4_dialog_content = "<color=#e8d9bb>Bethlehem menutup buku, menatap penghalang yang meleleh di kejauhan—di dalam alam Northland yang telah lama membeku, sebuah ladang bunga musim semi mekar.</color>",
  ui_story_5088_50881300_5_dialog_content = "<color=#e8d9bb>Sejarah Northland dimulai dengan kerajaan yang pertama kali menyatukannya. Legenda menceritakan tentang seorang raja yang duduk sendirian di atas takhta es, membawa kedamaian ke tanah ini.</color>",
  ui_story_5088_50881300_6_dialog_content = "<color=#e8d9bb>Bertahun-tahun kemudian, keturunan raja saling berbalik melawan satu sama lain dalam pencarian kekuasaan, sekali lagi mendorong Northland ke dalam kekacauan.</color>",
  ui_story_5088_50881300_7_dialog_content = "<color=#e8d9bb>Ketika seorang gadis dari perbatasan menyaksikan dunia yang hancur ini, dia bersumpah untuk mengembalikan keasliannya.</color>",
  ui_story_5088_50881300_8_dialog_content = "<color=#e8d9bb>Demikianlah, gadis itu memimpin rakyat, dan akhirnya menjadi ratu.</color>",
  ui_story_5088_50881300_9_dialog_content = "<color=#e8d9bb>Dalam kitab-kitab kuno yang disegel oleh raja tua, ratu membaca dari cerita \"bintang-bintang.\"</color>",
  ui_story_5088_50881300_10_dialog_content = "<color=#e8d9bb>Maka, setiap Bethlehem mulai berharap untuk masa depan \"bintang-bintang.\"</color>",
  ui_story_5088_50881300_11_dialog_content = "Pahlawan, sekarang, ini adalah musim semi.",
  ui_story_5088_50881300_12_dialog_content = "...",
  ui_story_5088_50881300_13_dialog_content = "Di mana kita...?",
  ui_story_5088_50881300_14_dialog_content = "Adras, sepertinya rotinya hampir siap.",
  ui_story_5088_50881300_15_dialog_content = "Friegson, turunkan suhu penghangatnya!",
  ui_story_5088_50881300_16_dialog_content = "... Seseorang telah mengambil gigitan licik darinya.",
  ui_story_5088_50881300_17_dialog_content = "Wow, baunya sangat enak...",
  ui_story_5088_50881300_18_dialog_content = "Apa yang terjadi dengan sikap muliamu?",
  ui_story_5088_50881300_19_dialog_content = "Siapa yang peduli tentang itu saat ada makanan enak untuk dimakan?",
  ui_story_5088_50881300_20_dialog_content = "Saya dapat membantu!",
  ui_story_5088_50881300_21_dialog_content = "Hei! Kamu hanya mencoba mencuri gigitan sambil berpura-pura membantu, bukan? Aku tidak berpikir begitu!",
  ui_story_5088_50881300_22_dialog_content = "Itu bohong! Kamu tidak bisa menggertakku... Ludweiss, tolong!",
  ui_story_5088_50881300_23_dialog_content = "Siapa yang berkeliling berdebat dengan anak-anak?! Lady Marcela, kamu harus memberinya pelajaran!",
  ui_story_5088_50881300_24_dialog_content = "Hah? Tidak, tidak, tidak, aku hanya bercanda...",
  ui_story_5088_50881300_25_dialog_content = "<color=#FFB400>Sebuah ilusi</color>...",
  ui_story_5088_50881300_26_dialog_content = "Ya, ini adalah adegan yang paling kamu rindukan.",
  ui_story_5088_50881300_27_dialog_content = "Ludweiss…",
  ui_story_5088_50881300_28_dialog_content = "Dalam mimpi yang penuh kebahagiaan ini, keberadaanmu adalah satu-satunya yang kurang.",
  ui_story_5088_50881300_29_dialog_content = "Dan itu cukup.",
  ui_story_5088_50881300_30_dialog_content = "Achilles, kamu cukup kuat untuk mengakui bahwa ini hanyalah ilusi, namun lemah dalam ketakutan bahwa kamu mungkin akan menghancurkan kebahagiaan ini.",
  ui_story_5088_50881300_31_dialog_content = "... Kamu tidak akan menghentikan aku pergi, bukan?",
  ui_story_5088_50881300_32_dialog_content = "Ya.",
  ui_story_5088_50881300_33_dialog_content = "Karena ini adalah fantasimu, seharusnya aku bilang padamu untuk tetap tinggal.",
  ui_story_5088_50881300_34_dialog_content = "Tapi aku masih berharap kamu untuk menjelajahi dunia baru untukku, dan membantu aku menulis cerita baru dari perjalananmu.",
  ui_story_5088_50881300_35_dialog_content = "Apakah benar-benar baik bagi kita untuk kembali ke dunia seperti ini?",
  ui_story_5088_50881300_36_dialog_content = "Apakah kamu percaya hal seperti itu bisa sederhana?",
  ui_story_5088_50881300_37_dialog_content = "Ini bukan permainan di mana kemenangan berarti kebangkitan.",
  ui_story_5088_50881300_38_dialog_content = "Namun demikian, siapa yang tidak ingin berkumpul di sekitarmu untuk reuni musim semi? Oleh karena itu, setiap orang mengumpulkan kekuatan mereka untuk pahlawan mereka.",
  ui_story_5088_50881300_39_dialog_content = "Dan kamu berjanji untuk mencari cara untuk kembali bersatu.",
  ui_story_5088_50881300_40_dialog_content = "... Kamu benar.",
  ui_story_5088_50881300_41_dialog_content = "Selamat tinggal, Ludweiss.",
  ui_story_5088_50881300_42_dialog_content = "Tunggu.",
  ui_story_5088_50881300_43_dialog_content = "?!",
  ui_story_5088_50881300_44_dialog_content = "Perjalanan yang aman.",
  ui_story_5088_50881300_45_dialog_content = "Tolong awasi Adras untukku!",
  ui_story_5088_50881300_46_dialog_content = "Heh...",
  ui_story_5088_50881300_47_dialog_content = "Sampai jumpa.",
  ui_story_5088_50881300_48_dialog_content = "... Pamitan.",
  ui_story_5088_50881300_49_dialog_content = "<color=#e8d9bb>Northland tidak pernah kekurangan pemandangan menakjubkan dan bunga-bunga indah, tetapi orang-orang di sini belum pernah melihat cahaya musim semi yang begitu indah seperti ini.</color>",
  ui_story_5088_50881300_50_dialog_content = "<color=#e8d9bb>Di sudut kecil dunia ini, di mana es dan salju akhirnya mencair, dandelion menari di udara dan ladang bunga mekar dengan cerah.</color>",
  ui_story_5088_50881300_51_dialog_content = "<color=#e8d9bb>Pelangi bersandar pada Obelisk of Return, mendengarkan lagunya yang lembut dan merdu.</color>",
  ui_story_5088_50881300_52_dialog_content = "<color=#e8d9bb>Semua orang di sekitar sangat terpesona olehnya.</color>",
  ui_story_5088_50881300_53_dialog_content = "Setelah dua ribu tahun, akhirnya harapan klan kami terwujud...",
  ui_story_5088_50881300_54_dialog_content = "Terima kasih telah menjadi bagian dari dunia ini.",
  ui_story_5088_50881300_55_dialog_content = "Kamu terlalu menyanjungku...",
  ui_story_5088_50881300_56_dialog_content = "Aku pernah benar-benar tersesat, tapi sekarang aku mengerti kehebatan mereka yang datang sebelumku.",
  ui_story_5088_50881300_57_dialog_content = "Mulai sekarang, saya akan mengikuti jalan keadilan, seperti leluhur saya—jalur Prajurit Bintang.",
  ui_story_5088_50881300_58_dialog_content = "Saya pikir kamu cukup mengesankan, Mithra... terutama saat kamu menyelamatkan saya malam itu.",
  ui_story_5088_50881300_59_dialog_content = "Meskipun kebingunganmu, kamu tidak pernah menyerah.",
  ui_story_5088_50881300_60_dialog_content = "Berkatmu, saya bisa membangunkan Achilles. Dalam setiap situasi yang kita hadapi, kamu selalu mengambil inisiatif. Kamu telah melakukan begitu banyak.",
  ui_story_5088_50881300_61_dialog_content = "... Hehe.",
  ui_story_5088_50881300_62_dialog_content = "Mungkin kamu benar.",
  ui_story_5088_50881300_63_dialog_content = "Ayo pergi!",
  ui_story_5088_50881300_64_dialog_content = "Hah?",
  ui_story_5088_50881300_65_dialog_content = "Untuk bertemu kembali dengan semua orang...",
  ui_story_5088_50881300_66_dialog_content = "Wah, cantik sekali! Saya belum pernah melihat tempat seperti ini sebelumnya.",
  ui_story_5088_50881300_67_dialog_content = "Dan bunga-bunga ini...",
  ui_story_5088_50881300_68_dialog_content = "... Anak-anak?",
  ui_story_5088_50881300_69_dialog_content = "Berhenti berlarian, gadis kecil, atau kamu akan tergores oleh semua tanaman di sini. Mari, aku akan menunjukkan bunga-bunga yang paling cantik.",
  ui_story_5088_50881300_70_dialog_content = "Hei, wanita! Kamu sangat tinggi!",
  ui_story_5088_50881300_71_dialog_content = "Apakah kamu juga ingin menjadi tinggi?",
  ui_story_5088_50881300_72_dialog_content = "Apakah ini akan berhasil?",
  ui_story_5088_50881300_73_dialog_content = "Wow! Kamu mengangkatku! Sekarang aku lebih tinggi dari setiap orang!",
  ui_story_5088_50881300_74_dialog_content = "... Jika kamu pergi berlari seperti ini, orang tuamu akan mulai khawatir.",
  ui_story_5088_50881300_75_dialog_content = "Tidak apa-apa, Pak, ayahku ada di sana bersama ibu sedang melihat bunga!",
  ui_story_5088_50881300_76_dialog_content = "Nona, ini... untukmu...",
  ui_story_5088_50881300_77_dialog_content = "Terima kasih.",
  ui_story_5088_50881300_78_dialog_content = "...",
  ui_story_5088_50881300_79_dialog_content = "Hei, Tuan, apakah kamu tidak akan datang?",
  ui_story_5088_50881300_80_dialog_content = "Terima kasih, tapi saya akan tinggal di sini dan menonton untuk sekarang.",
  ui_story_5088_50881300_81_dialog_content = "Tidak! Ayo, Pak!",
  ui_story_5088_50881300_82_dialog_content = "Wanita berponi itu mengatakan dia akan memberiku banyak permen enak jika aku membawamu kesana!",
  ui_story_5088_50881300_83_dialog_content = "... Freya?",
  ui_story_5088_50881300_84_dialog_content = "Heheh.",
  ui_story_5088_50881300_85_dialog_content = "Tuan, kamu tersenyum!",
  ui_story_5088_50881300_86_dialog_content = "Kamu memiliki senyuman yang sangat ramah.",
  ui_story_5088_50881300_87_dialog_content = "Ayo, kita dapatkan permen lezat itu untukmu.",
  ui_story_5088_50881300_88_dialog_content = "<color=#e8d9bb>Dan begitu, bintang-bintang menemukan rumah mereka.</color>",
  ui_story_5088_50881300_89_dialog_content = "<color=#e8d9bb>Cerita tentang kerajaan dan para prajuritnya mungkin berakhir di sini...</color>",
  ui_story_5088_50881300_90_dialog_content = "<color=#e8d9bb>Tapi bab baru akan dimulai.</color>",
  ui_story_5088_50881300_91_dialog_content = "<color=#e8d9bb>Di tengah kebahagiaan reuni, sebuah dongeng baru akan lahir...</color>",
  ui_story_5088_50881300_92_dialog_content = "<color=#e8d9bb>Dan aku bisa menjaminmu—ini akan berakhir bahagia.</color>"
}
return config
